		string text = (npcDataPacket != null) ? GetSceneNpcHistoryNameForPrompt(npcDataPacket) : ((fallbackSpeakerName ?? "").Trim());
		return string.IsNullOrWhiteSpace(text) ? "某NPC" : text;
