	private static LocationCharacter CreateSceneGuideFallbackTavernkeeper(CultureObject culture)
	{
		if (culture?.Tavernkeeper == null)
		{
			return null;
		}
		try
		{
			Type type = AppDomain.CurrentDomain.GetAssemblies().Select((Assembly a) => a?.GetType("SandBox.CampaignBehaviors.TavernEmployeesCampaignBehavior", throwOnError: false)).FirstOrDefault((Type t) => t != null);
			MethodInfo methodInfo = type?.GetMethod("CreateTavernkeeper", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[2]
			{
				typeof(CultureObject),
				typeof(LocationCharacter.CharacterRelations)
			}, null);
			return methodInfo?.Invoke(null, new object[2]
			{
				culture,
				LocationCharacter.CharacterRelations.Neutral
			}) as LocationCharacter;
		}
		catch (Exception ex)
		{
			try
			{
				Logger.Log("SceneGuide", "fallback_tavernkeeper_create_failed error=" + ex.Message);
			}
			catch
			{
			}
			return null;
		}
	}

	private static void EnsureSceneGuideTavernkeeperTarget(LocationComplex locationComplex, Location currentLocation, Dictionary<string, List<LocationCharacter>> targetsByLabel)
	{
		if (locationComplex == null || currentLocation == null || targetsByLabel == null)
		{
			return;
		}
		try
		{
			Location tavernLocation = locationComplex.GetLocationWithId("tavern");
			if (tavernLocation == null || FindSceneLocationPath(currentLocation, tavernLocation) == null)
			{
				return;
			}
			if (targetsByLabel.TryGetValue("酒馆老板", out var existingTargets) && existingTargets != null && existingTargets.Any((LocationCharacter x) => x != null && locationComplex.GetLocationOfCharacter(x) == tavernLocation))
			{
				return;
			}
			LocationCharacter locationCharacter = tavernLocation.GetCharacterList().FirstOrDefault(IsSceneGuideTavernkeeper);
			if (locationCharacter == null)
			{
				Settlement settlement = Settlement.CurrentSettlement ?? PlayerEncounter.LocationEncounter?.Settlement;
				if (settlement == null || !settlement.IsTown)
				{
					return;
				}
				locationCharacter = CreateSceneGuideFallbackTavernkeeper(settlement.Culture);
				if (locationCharacter == null)
				{
					return;
				}
				tavernLocation.AddCharacter(locationCharacter);
				try
				{
					Logger.Log("SceneGuide", "fallback_tavernkeeper_added settlement=" + (settlement.StringId ?? "") + " location=tavern");
				}
				catch
				{
				}
			}
			if (!TryGetSceneGuideTargetLabel(locationCharacter, out var displayName, out var _) || !string.Equals(displayName, "酒馆老板", StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
			if (!targetsByLabel.TryGetValue(displayName, out var list))
			{
				list = new List<LocationCharacter>();
				targetsByLabel[displayName] = list;
			}
			if (!list.Contains(locationCharacter))
			{
				list.Add(locationCharacter);
			}
		}
		catch (Exception ex2)
		{
			try
			{
				Logger.Log("SceneGuide", "fallback_tavernkeeper_target_failed error=" + ex2.Message);
			}
			catch
			{
			}
		}
	}

	private List<SceneGuidePromptTarget> BuildSceneGuidePromptTargets(Agent guideAgent = null, int firstPromptId = 1)
	{
		List<SceneGuidePromptTarget> list = new List<SceneGuidePromptTarget>();
		LocationComplex locationComplex = LocationComplex.Current;
		Location location = CampaignMission.Current?.Location;
		if (locationComplex == null || location == null)
		{
			return list;
		}
		Dictionary<string, List<LocationCharacter>> dictionary = new Dictionary<string, List<LocationCharacter>>(StringComparer.OrdinalIgnoreCase);
		foreach (LocationCharacter item in locationComplex.GetListOfCharacters())
		{
			if (!TryGetSceneGuideTargetLabel(item, out var displayName, out var _))
			{
				continue;
			}
			if (string.Equals(displayName, "商贩", StringComparison.OrdinalIgnoreCase) && (item.Character?.IsHero ?? false))
			{
				continue;
			}
			Location locationOfCharacter = locationComplex.GetLocationOfCharacter(item);
			if (locationOfCharacter == null)
			{
				continue;
			}
			List<Location> sceneLocationPath = FindSceneLocationPath(location, locationOfCharacter);
			if (sceneLocationPath == null || sceneLocationPath.Count == 0)
			{
				continue;
			}
			if (!dictionary.TryGetValue(displayName, out var value))
			{
				value = new List<LocationCharacter>();
				dictionary[displayName] = value;
			}
			value.Add(item);
		}
		EnsureSceneGuideTavernkeeperTarget(locationComplex, location, dictionary);
		Vec3 vec = guideAgent?.Position ?? Agent.Main?.Position ?? Vec3.Zero;
		string[] array = new string[14] { "盔甲匠", "武器匠", "铁匠", "马匹贩子", "商贩", "工坊工人", "理发师", "竞技场老板", "酒馆老板", "赎金经纪人", "棋局主持", "酒馆女侍", "乐师", "雇佣兵" };
		foreach (string text in array)
		{
			if (!dictionary.TryGetValue(text, out var value2) || value2 == null || value2.Count == 0)
			{
				continue;
			}
			LocationCharacter locationCharacter = value2[0];
			if (string.Equals(text, "商贩", StringComparison.OrdinalIgnoreCase))
			{
				locationCharacter = value2.OrderBy(delegate(LocationCharacter x)
				{
					Agent agent = ResolveAgentForLocationCharacter(x);
					if (agent != null && agent.IsActive())
					{
						return agent.Position.DistanceSquared(vec);
					}
					return float.MaxValue;
				}).ThenBy((LocationCharacter x) => (x.Character?.Name?.ToString() ?? "").Trim(), StringComparer.CurrentCulture).FirstOrDefault();
			}
			else if (string.Equals(text, "酒馆老板", StringComparison.OrdinalIgnoreCase))
			{
				Location tavernLocation = locationComplex.GetLocationWithId("tavern");
				bool currentIsTavern = IsSceneLocation(location, "tavern");
				locationCharacter = value2.OrderBy(delegate(LocationCharacter x)
				{
					Location candidateLocation = locationComplex.GetLocationOfCharacter(x);
					if (currentIsTavern)
					{
						return candidateLocation == location ? 0 : 1;
					}
					return candidateLocation == tavernLocation ? 0 : 1;
				}).ThenBy(delegate(LocationCharacter x)
				{
					Agent agent = ResolveAgentForLocationCharacter(x);
					return agent != null && agent.IsActive() ? 0 : 1;
				}).ThenBy((LocationCharacter x) => (x.Character?.Name?.ToString() ?? "").Trim(), StringComparer.CurrentCulture).FirstOrDefault();
			}
			else
			{
				locationCharacter = value2.OrderBy((LocationCharacter x) => (x.Character?.Name?.ToString() ?? "").Trim(), StringComparer.CurrentCulture).FirstOrDefault();
			}
			if (locationCharacter == null)
			{
				continue;
			}
			Location locationOfCharacter2 = locationComplex.GetLocationOfCharacter(locationCharacter);
			if (locationOfCharacter2 == null)
			{
				continue;
			}
			list.Add(new SceneGuidePromptTarget
			{
				PromptId = Math.Max(1, firstPromptId) + list.Count,
				DisplayName = text,
				LocationCode = GetSceneSummonLocationCode(locationOfCharacter2),
				LocationCharacter = locationCharacter,
				SourceLocation = locationOfCharacter2
			});
			if (list.Count >= SCENE_GUIDE_PROMPT_TARGET_LIMIT)
			{
				break;
			}
		}
		return list;
	}

	private static List<SceneGuidePromptTarget> CloneSceneGuidePromptTargets(List<SceneGuidePromptTarget> source)
	{
		if (source == null || source.Count == 0)
		{
			return null;
		}
		List<SceneGuidePromptTarget> list = new List<SceneGuidePromptTarget>(source.Count);
		foreach (SceneGuidePromptTarget item in source)
		{
			if (item == null)
			{
				continue;
			}
			list.Add(new SceneGuidePromptTarget
			{
				PromptId = item.PromptId,
				DisplayName = item.DisplayName,
				LocationCode = item.LocationCode,
				LocationCharacter = item.LocationCharacter,
				SourceLocation = item.SourceLocation
			});
		}
		return list;
	}

	private static void AppendSceneSummonPromptSection(StringBuilder prompt, List<SceneSummonPromptTarget> targets)
	{
		if (prompt == null || targets == null || targets.Count == 0)
		{
			return;
		}
		prompt.AppendLine("【可召目标】：");
		foreach (SceneSummonPromptTarget target in targets)
		{
			if (target != null && target.PromptId > 0 && !string.IsNullOrWhiteSpace(target.DisplayName))
			{
				prompt.AppendLine(target.PromptId + " " + target.DisplayName.Trim() + " " + (target.LocationCode ?? "处"));
			}
		}
	}

	private static void AppendSceneUnifiedTargetPromptSection(StringBuilder prompt, List<SceneSummonPromptTarget> summonTargets, List<SceneGuidePromptTarget> guideTargets)
	{
		if (prompt == null)
		{
			return;
		}
		List<string> list = new List<string>();
		HashSet<int> hashSet = new HashSet<int>();
		foreach (SceneSummonPromptTarget item in summonTargets ?? new List<SceneSummonPromptTarget>())
		{
			if (item != null && item.PromptId > 0 && !string.IsNullOrWhiteSpace(item.DisplayName) && hashSet.Add(item.PromptId))
			{
				list.Add(item.PromptId + " " + item.DisplayName.Trim() + " " + (item.LocationCode ?? "处"));
			}
		}
		foreach (SceneGuidePromptTarget item2 in guideTargets ?? new List<SceneGuidePromptTarget>())
		{
			if (item2 != null && item2.PromptId > 0 && !string.IsNullOrWhiteSpace(item2.DisplayName) && hashSet.Add(item2.PromptId))
			{
				list.Add(item2.PromptId + " " + item2.DisplayName.Trim() + " " + (item2.LocationCode ?? "处"));
			}
		}
		if (list.Count == 0)
		{
			return;
		}
		prompt.AppendLine("【带路与传唤NPC清单】：");
		foreach (string item3 in list)
		{
			prompt.AppendLine(item3);
		}
	}

	private static string BuildSceneMechanismPromptSection(List<SceneSummonPromptTarget> sceneSummonTargets = null, List<SceneGuidePromptTarget> sceneGuideTargets = null, string sceneSummonClosureInstruction = null, string sceneFollowControlInstruction = null, NpcDataPacket publicActionTarget = null)
	{
		string executionInstruction = publicActionTarget == null
			? string.Empty
			: NoblePrisonerEscortBehavior.BuildSceneExecutionPromptInstruction(publicActionTarget.AgentIndex);
		string inspectionSlaughterInstruction = publicActionTarget == null
			? string.Empty
			: TroopInspectionBehavior.BuildPrisonerSlaughterPromptInstructionForExternal(publicActionTarget.AgentIndex);
		if (AIConfigHandler.ShouldExcludeSceneMoveRuleForCurrentMission())
		{
			return string.Join(
				"\n",
				new[]
				{
					executionInstruction,
					inspectionSlaughterInstruction
				}.Where(text => !string.IsNullOrWhiteSpace(text))).Trim();
		}
		if (IsPrisonBreakRescueMissionActive())
		{
			string prisonBreakInstruction = string.IsNullOrWhiteSpace(sceneFollowControlInstruction) ? "" : sceneFollowControlInstruction.Trim();
			return string.IsNullOrWhiteSpace(executionInstruction)
				? prisonBreakInstruction
				: (prisonBreakInstruction + "\n" + executionInstruction).Trim();
		}
		StringBuilder stringBuilder = new StringBuilder();
		if (SettlementEntryTroopSelectionBehavior.IsOwnedOrAttachedSettlementEntryActiveForExternal(Mission.Current))
		{
			SetsSettlementSceneKind sceneKind = SettlementEntryTroopSelectionBehavior.GetSetsSettlementSceneKindForExternal(Mission.Current);
			bool massacreActive = SettlementEntryTroopSelectionBehavior.IsOwnedOrAttachedSettlementMassacreActiveForExternal(Mission.Current);
			bool requestPending = SettlementEntryTroopSelectionBehavior.HasOwnedOrAttachedSettlementMassacreRequestForExternal(Mission.Current);
			stringBuilder.AppendLine(SetsOwnedSettlementMassacreProfile.BuildRuntimeInstruction(sceneKind, massacreActive, requestPending));
		}
		AppendSceneUnifiedTargetPromptSection(stringBuilder, sceneSummonTargets, sceneGuideTargets);
		if (!string.IsNullOrWhiteSpace(sceneSummonClosureInstruction))
		{
			stringBuilder.AppendLine(sceneSummonClosureInstruction);
		}
		if (!string.IsNullOrWhiteSpace(sceneFollowControlInstruction))
		{
			stringBuilder.AppendLine(sceneFollowControlInstruction);
		}
		if (!string.IsNullOrWhiteSpace(executionInstruction))
		{
			stringBuilder.AppendLine(executionInstruction);
		}
		if (!string.IsNullOrWhiteSpace(inspectionSlaughterInstruction))
		{
			stringBuilder.AppendLine(inspectionSlaughterInstruction);
		}
		return stringBuilder.ToString().Trim();
	}

	private static bool CanUseSceneMechanismPostprocessForSpeaker(int speakerAgentIndex)
	{
		return !AIConfigHandler.ShouldExcludeSceneMoveRuleForCurrentMission()
			|| NoblePrisonerEscortBehavior.IsEscortedAgent(speakerAgentIndex)
			|| TroopInspectionBehavior.CanOfferPrisonerSlaughterActionForExternal(
				speakerAgentIndex,
				out _,
				out _);
	}

	private static string InjectSceneMechanismPromptSection(string prompt, string mechanismSection, bool allowAppendWithoutMarker = false)
	{
		string text = (prompt ?? "").Trim();
		string text2 = (mechanismSection ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text2))
		{
			return text;
		}
		const string marker = "【附加规则:scene_mechanism_actions】";
		int num = text.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (num < 0)
		{
			if (!allowAppendWithoutMarker)
			{
				return text;
			}
			return string.IsNullOrWhiteSpace(text) ? text2 : (text + "\n" + text2);
		}
		int num2 = text.IndexOf("【附加规则:", num + marker.Length, StringComparison.Ordinal);
		if (num2 < 0)
		{
			return text.TrimEnd() + "\n" + text2;
		}
		return text.Substring(0, num2).TrimEnd() + "\n" + text2 + "\n" + text.Substring(num2).TrimStart();
	}

	private void EnqueuePendingSceneSummonLaunch(int agentIndex, ActiveSceneSummonRequest request)
	{
		if (agentIndex < 0 || request == null)
		{
			return;
		}
		lock (_ttsBubbleSyncLock)
		{
			if (!_pendingSceneSummonLaunchQueues.TryGetValue(agentIndex, out var value))
			{
				value = new Queue<ActiveSceneSummonRequest>();
				_pendingSceneSummonLaunchQueues[agentIndex] = value;
			}
			value.Enqueue(request);
		}
	}

	private void EnqueuePendingSceneGuideLaunch(int agentIndex, ActiveSceneGuideRequest request)
	{
		if (agentIndex < 0 || request == null)
		{
			return;
		}
		lock (_ttsBubbleSyncLock)
		{
			if (!_pendingSceneGuideLaunchQueues.TryGetValue(agentIndex, out var value))
			{
				value = new Queue<ActiveSceneGuideRequest>();
				_pendingSceneGuideLaunchQueues[agentIndex] = value;
			}
			value.Enqueue(request);
		}
	}

	private bool TryDequeuePendingSceneSummonLaunch(int agentIndex, out ActiveSceneSummonRequest request)
	{
		request = null;
		if (agentIndex < 0)
		{
			return false;
		}
		lock (_ttsBubbleSyncLock)
		{
			if (_pendingSceneSummonLaunchQueues.TryGetValue(agentIndex, out var value) && value.Count > 0)
			{
				request = value.Dequeue();
				if (value.Count == 0)
				{
					_pendingSceneSummonLaunchQueues.Remove(agentIndex);
				}
				return request != null;
			}
		}
		return false;
	}

	private bool TryDequeuePendingSceneGuideLaunch(int agentIndex, out ActiveSceneGuideRequest request)
	{
		request = null;
		if (agentIndex < 0)
		{
			return false;
		}
		lock (_ttsBubbleSyncLock)
		{
			if (_pendingSceneGuideLaunchQueues.TryGetValue(agentIndex, out var value) && value.Count > 0)
			{
				request = value.Dequeue();
				if (value.Count == 0)
				{
					_pendingSceneGuideLaunchQueues.Remove(agentIndex);
				}
				return request != null;
			}
		}
		return false;
	}

	private void FlushPendingSceneSummonLaunches(int agentIndex, float additionalDelaySeconds = 0f)
	{
		Mission mission = Mission.Current;
		if (agentIndex < 0 || mission == null)
		{
			return;
		}
		while (TryDequeuePendingSceneSummonLaunch(agentIndex, out var request))
		{
			request.NextStageMissionTime = mission.CurrentTime + Math.Max(0f, additionalDelaySeconds);
			LogSceneSummonState("pending_launch_tts_finished", request, ResolveAgentForLocationCharacter(request.SpeakerLocationCharacter), ResolveAgentForLocationCharacter(request.TargetLocationCharacter), "extraDelay=" + additionalDelaySeconds.ToString("F2"), force: true);
		}
	}

	private void FlushPendingSceneGuideLaunches(int agentIndex, float additionalDelaySeconds = 0f)
	{
		Mission mission = Mission.Current;
		if (agentIndex < 0 || mission == null)
		{
			return;
		}
		while (TryDequeuePendingSceneGuideLaunch(agentIndex, out var request))
		{
			request.NextStageMissionTime = mission.CurrentTime + Math.Max(0f, additionalDelaySeconds);
		}
	}

	private void CancelSceneSummonBatch(int batchId)
	{
		if (batchId < 0)
		{
			return;
		}
		_activeSceneSummonBatches.Remove(batchId);
		foreach (ActiveSceneSummonRequest item in _activeSceneSummonRequests.Where((ActiveSceneSummonRequest x) => x != null && x.BatchId == batchId).ToList())
		{
			CleanupSceneSummonDoorProxyAgent(item);
		}
		_activeSceneSummonRequests.RemoveAll((ActiveSceneSummonRequest x) => x != null && x.BatchId == batchId);
		lock (_ttsBubbleSyncLock)
		{
			List<int> list = _pendingSceneSummonLaunchQueues.Keys.ToList();
			foreach (int item in list)
			{
				if (!_pendingSceneSummonLaunchQueues.TryGetValue(item, out var value) || value == null || value.Count == 0)
				{
					continue;
				}
				Queue<ActiveSceneSummonRequest> queue = new Queue<ActiveSceneSummonRequest>(value.Where((ActiveSceneSummonRequest x) => x != null && x.BatchId != batchId));
				if (queue.Count == 0)
				{
					_pendingSceneSummonLaunchQueues.Remove(item);
				}
				else
				{
					_pendingSceneSummonLaunchQueues[item] = queue;
				}
			}
		}
	}

	private void TryAdvanceSceneSummonBatch(ActiveSceneSummonRequest request, Agent speakerAgent)
	{
		if (request == null || request.BatchContinuationStarted || request.BatchId < 0 || request.KeepMessengerWithTarget)
		{
			return;
		}
		request.BatchContinuationStarted = true;
		if (!_activeSceneSummonBatches.TryGetValue(request.BatchId, out var value) || value == null || value.PendingTargets.Count == 0)
		{
			return;
		}
		if (TryStartNextSceneSummonBatchRequest(value, speakerAgent, isInitialRequest: false, out var preparedRequest))
		{
			LogSceneSummonState("batch_followup_queued", preparedRequest, speakerAgent, ResolveAgentForLocationCharacter(preparedRequest.TargetLocationCharacter), "remaining=" + value.PendingTargets.Count, force: true);
			return;
		}
		CancelSceneSummonBatch(request.BatchId);
	}

	private static string BuildSceneSummonBatchTargetSummary(SceneSummonBatchState batch, SceneSummonPromptTarget currentTarget)
	{
		List<string> list = new List<string>();
		if (currentTarget != null && !string.IsNullOrWhiteSpace(currentTarget.DisplayName))
		{
			list.Add(currentTarget.DisplayName.Trim());
		}
		if (batch != null)
		{
			foreach (SceneSummonPromptTarget pendingTarget in batch.PendingTargets)
			{
				string text = pendingTarget?.DisplayName;
				if (!string.IsNullOrWhiteSpace(text))
				{
					text = text.Trim();
					if (!list.Contains(text))
					{
						list.Add(text);
					}
				}
			}
		}
		if (list.Count == 0)
		{
			return "那些人";
		}
		if (list.Count == 1)
		{
			return list[0];
		}
		return string.Join("、", list);
	}

	private string BuildSceneSummonArrivedDisplayNames(int batchId, string fallbackTargetName)
	{
		if (batchId >= 0)
		{
			SceneSummonConversationSession sceneSummonConversationSession = _activeSceneSummonConversationSessions.FirstOrDefault((SceneSummonConversationSession x) => x != null && x.BatchId == batchId);
			if (sceneSummonConversationSession != null)
			{
				List<string> list = sceneSummonConversationSession.Participants.Where((SceneSummonConversationParticipant x) => x != null && !string.IsNullOrWhiteSpace(x.DisplayName)).Select((SceneSummonConversationParticipant x) => x.DisplayName.Trim()).Distinct().ToList();
				if (list.Count == 1)
				{
					return list[0];
				}
				if (list.Count > 1)
				{
					return string.Join("、", list);
				}
			}
		}
		return fallbackTargetName ?? "那个人";
	}

	private void TryRecordSceneSummonBatchCompletionFact(ActiveSceneSummonRequest request)
	{
		if (request == null || request.BatchId < 0 || request.SpeakerAgentIndex < 0)
		{
			return;
		}
		if (!_activeSceneSummonBatches.TryGetValue(request.BatchId, out var value) || value == null || value.CompletionFactRecorded)
		{
			return;
		}
		if (value.PendingTargets.Count > 0)
		{
			return;
		}
		int num = _activeSceneSummonRequests.Count((ActiveSceneSummonRequest x) => x != null && x.BatchId == request.BatchId);
		if (num > 1)
		{
			return;
		}
		string text = BuildSceneSummonArrivedDisplayNames(request.BatchId, request.TargetName);
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		string text2 = GetPlayerDisplayNameForShout();
		if (string.IsNullOrWhiteSpace(text2))
		{
			text2 = "此人";
		}
		AppendTargetedSceneNpcFact("你已将" + text2 + "要求召集的" + text + "都带到了" + text2 + "身边。", request.SpeakerAgentIndex, persistHeroPrivateHistory: true);
		value.CompletionFactRecorded = true;
	}

	private string BuildSceneSummonClosurePromptInstruction(IEnumerable<NpcDataPacket> participants)
	{
		if (participants == null)
		{
			return "";
		}
		foreach (NpcDataPacket participant in participants)
		{
			if (participant == null || participant.AgentIndex < 0)
			{
				continue;
			}
			if (TryGetSceneSummonConversationSessionForAgentIndex(participant.AgentIndex) != null)
			{
				return "【当前是传唤后的会面】若你明确同意之后跟随此人，系统会记录你开始跟随；若你明确表示这次会面到此结束，系统会结束会面；若此人改让你去叫【带路与传唤NPC清单】中的人，系统会记录传唤；若此人改让你带路去找【带路与传唤NPC清单】中的目标，系统会记录带路。正文只自然说话，不要自己写标签。";
			}
		}
		return "";
	}

	private string BuildSceneFollowControlPromptInstruction(NpcDataPacket speaker)
	{
		Agent agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && speaker != null && a.Index == speaker.AgentIndex);
		if (!CanAgentParticipateInSceneSpeech(agent))
		{
			return "";
		}
		if (IsPrisonBreakRescuePrisonerAgent(agent))
		{
			return IsPrisonBreakPrisonerFollowing(agent)
				? "【当前正按原版营救跟随玩家】若此人明确让你停下且你同意，系统会记录停止营救跟随。正文只自然说话，不要自己写标签。"
				: "【营救跟随】若此人明确让你跟随一起逃离且你同意，系统会记录原版营救跟随。正文只自然说话，不要自己写标签。";
		}
		if (TryGetSceneSummonConversationSessionForAgentIndex(agent.Index) != null)
		{
			return "";
		}
		return IsAgentFollowingPlayerBySceneCommand(agent) ? "【当前正跟随玩家】若此人明确让你停止跟随且你同意，系统会记录停止跟随；若此人改让你去叫【带路与传唤NPC清单】中的人，系统会记录传唤；若此人改让你带路去找【带路与传唤NPC清单】中的目标，系统会记录带路。正文只自然说话，不要自己写标签。" : "";
	}

	private static bool HasPartyTransferRuleContext(string extras)
	{
		return !string.IsNullOrWhiteSpace(extras) && extras.IndexOf("【附加规则:party_transfer】", StringComparison.OrdinalIgnoreCase) >= 0;
	}

	private static string BuildSceneNpcRoleIntroForPrompt(NpcDataPacket npc, Hero hero, IEnumerable<NpcDataPacket> presentNpcs = null, bool includeInventorySummary = false, bool includeTradePricing = false, bool partyTransferTopicSelected = false, MentionedWorldEntities promptMentions = null)
	{
		if (npc == null)
		{
			return "";
		}
		// This value belongs to the current prompt request. Do not read the
		// AsyncLocal fallback here: main-prompt assembly may resume on another thread.
		MentionedWorldEntities inventoryMentions = promptMentions;
		string name = GetSceneNpcIdentityNameForPrompt(npc);
		string givenName = hero == null ? GetSceneNpcGivenNameForPrompt(npc) : "";
		string identity = (npc.RoleDesc ?? "").Trim();
		if (string.IsNullOrWhiteSpace(identity))
		{
			identity = "未知身份";
		}
		string personality = string.IsNullOrWhiteSpace(npc.PersonalityDesc) ? "暂无记录" : npc.PersonalityDesc.Trim();
		string background = string.IsNullOrWhiteSpace(npc.BackgroundDesc) ? "暂无记录" : npc.BackgroundDesc.Trim();
		string faction = "无（独立）";
		string clan = "无家族";
		string clanRole = "成员";
		string reputation = MyBehavior.GetClanTierReputationLabelForExternal(0) + "（0 level）";
		string culture = (npc.CultureId ?? "").Trim();
		string age = MyBehavior.BuildAgeBracketLabelForExternal(npc.Age);
		string equipment = "未知";
		string inventorySummary = "";
		string currentDateText = "";
		if (hero != null)
		{
			try
			{
				string clanName = (hero.Clan?.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(clanName))
				{
					clan = clanName;
				}
				if (!string.IsNullOrWhiteSpace(clan) && !clan.EndsWith("家族", StringComparison.Ordinal))
				{
					clan += "家族";
				}
				int tier = hero.Clan?.Tier ?? 0;
				reputation = MyBehavior.GetClanTierReputationLabelForExternal(tier) + $"（{Math.Max(0, tier)} level）";
				string heroIdentity = MyBehavior.BuildHeroIdentityTitleForExternal(hero);
				if (!string.IsNullOrWhiteSpace(heroIdentity))
				{
					identity = heroIdentity.Trim();
				}
				string factionName = (hero.Clan?.Kingdom?.Name?.ToString() ?? "").Trim();
				if (string.IsNullOrWhiteSpace(factionName))
				{
					factionName = (hero.MapFaction?.Name?.ToString() ?? "").Trim();
				}
				if (string.IsNullOrWhiteSpace(factionName))
				{
					factionName = clan;
				}
				if (!string.IsNullOrWhiteSpace(factionName))
				{
					faction = factionName;
				}
				if (hero.Clan?.Leader == hero)
				{
					clanRole = "族长";
				}
				string cultureName = (hero.Culture?.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(cultureName))
				{
					culture = cultureName;
				}
				age = MyBehavior.BuildAgeBracketLabelForExternal(hero.Age);
				equipment = MyBehavior.BuildHeroEquipmentSummaryForExternal(hero);
				if (includeInventorySummary && RewardSystemBehavior.Instance != null)
				{
					int promptListMax = PromptListRetrievalService.GetMaxCandidateCount();
					inventorySummary = (RewardSystemBehavior.Instance.BuildFilteredInventorySummaryForAI(hero, inventoryMentions, promptListMax, includePrivateBattleEquipment: includeTradePricing) ?? "").Trim();
				}
			}
			catch
			{
			}
		}
		else
		{
			string unnamedRank = (npc.UnnamedRank ?? "").Trim();
			if (!string.IsNullOrWhiteSpace(unnamedRank))
			{
				clan = unnamedRank;
			}
			if (!string.IsNullOrWhiteSpace(clan) && clan != "无家族" && !clan.EndsWith("家族", StringComparison.Ordinal))
			{
				clan += "家族";
			}
			if (!string.IsNullOrWhiteSpace(culture))
			{
				faction = culture;
			}
			equipment = BuildNonHeroEquipmentSummaryForPrompt(npc);
			try
			{
				Agent agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == npc.AgentIndex);
				CharacterObject characterObject = agent?.Character as CharacterObject;
				if (includeInventorySummary && RewardSystemBehavior.Instance != null && characterObject != null && RewardSystemBehavior.Instance.TryGetSettlementMerchantKind(characterObject, out var _))
				{
					int promptListMax = PromptListRetrievalService.GetMaxCandidateCount();
					string text = RewardSystemBehavior.Instance.BuildFilteredSettlementMerchantInventorySummaryForAI(characterObject, inventoryMentions, promptListMax);
					if (!string.IsNullOrWhiteSpace(text))
					{
						inventorySummary = text.Trim();
					}
				}
			}
			catch
			{
			}
		}
		if (string.IsNullOrWhiteSpace(culture))
		{
			culture = "未知文化";
		}
		if (!culture.EndsWith("人", StringComparison.Ordinal))
		{
			culture += "人";
		}
		if (string.IsNullOrWhiteSpace(age))
		{
			age = "未知";
		}
		if (string.IsNullOrWhiteSpace(equipment))
		{
			equipment = "未知";
		}
		try
		{
			currentDateText = (MyBehavior.BuildCurrentDateFactForExternal() ?? "").Replace("\r", "").Trim();
			if (currentDateText.StartsWith("当前游戏日期：", StringComparison.Ordinal))
			{
				currentDateText = currentDateText.Substring("当前游戏日期：".Length).Trim();
			}
			int parenIndex = currentDateText.IndexOf('（');
			if (parenIndex >= 0)
			{
				currentDateText = currentDateText.Substring(0, parenIndex).Trim();
			}
		}
		catch
		{
			currentDateText = "";
		}
		bool hideReputation = ShouldHideSceneReputationForPrompt(npc, hero);
		StringBuilder stringBuilder = new StringBuilder();
		if (hero != null)
		{
			string pregnancySelfKnowledge = BuildHeroPregnancySelfKnowledgeForPrompt(hero);
			string clanRoleText = (clanRole == "族长") ? "族长" : (hero.IsFemale ? "女性成员" : "男性成员");
			stringBuilder.Append("你名叫")
				.Append(name)
				.Append("，是")
				.Append(faction)
				.Append("的")
				.Append(clan)
				.Append("的")
				.Append(clanRoleText)
				.Append("，你的身份是")
				.Append(identity);
			if (!hideReputation && !string.IsNullOrWhiteSpace(reputation))
			{
				stringBuilder.Append("，你").Append(reputation);
			}
			string heroJoinPartyRuntimeFact = AIConfigHandler.BuildRuntimeHeroJoinPartyInstructionForExternal(hero);
			if (!string.IsNullOrWhiteSpace(heroJoinPartyRuntimeFact))
			{
				stringBuilder.Append("。").Append(heroJoinPartyRuntimeFact.Trim().TrimEnd('。'));
			}
			if (!string.IsNullOrWhiteSpace(pregnancySelfKnowledge))
			{
				stringBuilder.Append("。").Append(pregnancySelfKnowledge);
			}
			stringBuilder.Append("。");
		}
		else
		{
			stringBuilder.Append("你是一个")
				.Append(name);
			if (!string.IsNullOrWhiteSpace(givenName) && !string.Equals(givenName, name, StringComparison.Ordinal))
			{
				stringBuilder.Append("，名叫").Append(givenName);
			}
			stringBuilder.Append("，你的身份是")
				.Append(identity);
			if (!hideReputation && !string.IsNullOrWhiteSpace(reputation))
			{
				stringBuilder.Append("，你").Append(reputation);
			}
			stringBuilder.Append("。");
			string partyRepresentativePrompt = BuildWildernessNonHeroPartyRepresentativePrompt(npc.AgentIndex);
			if (!string.IsNullOrWhiteSpace(partyRepresentativePrompt))
			{
				stringBuilder.Append(partyRepresentativePrompt);
			}
		}
		stringBuilder.AppendLine()
			.Append("你身上穿着")
			.Append(equipment)
			.Append("。");
		string npcCurrentMountLine = BuildNpcCurrentMountLineForPrompt(npc);
		if (!string.IsNullOrWhiteSpace(npcCurrentMountLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(npcCurrentMountLine);
		}
		if (hero != null)
		{
			try
			{
				if (!IsHeroInPlayerMainPartyForPrompt(hero))
				{
					bool hasPartyRestrictionContext = false;
					string npcTroopsLine = BuildHeroPartyTroopsLineForPrompt(hero, secondPerson: true);
					string npcPrisonersLine = BuildHeroPartyPrisonersLineForPrompt(hero, secondPerson: true);
					if (!string.IsNullOrWhiteSpace(npcTroopsLine))
					{
						stringBuilder.Append(npcTroopsLine).Append("。");
						hasPartyRestrictionContext = true;
					}
					if (!string.IsNullOrWhiteSpace(npcPrisonersLine))
					{
						stringBuilder.Append(npcPrisonersLine).Append("。");
						hasPartyRestrictionContext = true;
					}
					if (hasPartyRestrictionContext && !partyTransferTopicSelected)
					{
						stringBuilder.Append("备注：你暂时不可以转移你的俘虏和士兵。");
					}
				}
			}
			catch
			{
			}
		}
		else
		{
			try
			{
				PartyBase nonHeroParty = ResolveWildernessNonHeroPartyBaseForPrompt(npc.AgentIndex);
				if (nonHeroParty != null)
				{
					string npcTroopsLine = BuildPartyTroopsLineForPrompt(nonHeroParty, "你所属队伍共有", "你所属队伍无可战兵力", includeDetails: true);
					if (!string.IsNullOrWhiteSpace(npcTroopsLine))
					{
						stringBuilder.Append(npcTroopsLine).Append("。");
					}
					string npcPrisonersLine = BuildPartyPrisonersLineForPrompt(nonHeroParty, "你所属队伍", "你所属队伍无俘虏", includeDetails: true);
					if (!string.IsNullOrWhiteSpace(npcPrisonersLine) && !string.Equals(npcPrisonersLine, "你所属队伍无俘虏", StringComparison.Ordinal))
					{
						stringBuilder.Append(npcPrisonersLine).Append("。");
					}
				}
			}
			catch
			{
			}
		}
		if (hero != null)
		{
			string nobleEtiquettePrompt = MyBehavior.BuildNobleEtiquettePromptForExternal(hero);
			stringBuilder.AppendLine()
				.Append("你的个性为：")
				.Append(personality)
				.Append("。")
				.AppendLine()
				.Append("你的背景是：")
				.Append(background);
			if (!string.IsNullOrWhiteSpace(nobleEtiquettePrompt))
			{
				stringBuilder.Append("。").Append(nobleEtiquettePrompt);
			}
			else
			{
				stringBuilder.Append("。");
			}
		}
		stringBuilder.AppendLine()
			.Append("你的年纪是")
			.Append(age)
			.Append("，你是")
			.Append(culture)
			.Append("。");
		if (!string.IsNullOrWhiteSpace(currentDateText))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append("现在的时间是").Append(currentDateText).Append("。");
		}
		string sceneLocationLine = BuildSceneLocationAndSettlementLineForPrompt(hero);
		if (!string.IsNullOrWhiteSpace(sceneLocationLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(sceneLocationLine);
		}
		string settlementHeroNpcLine = (ShoutUtils.BuildCurrentSettlementHeroNpcLineForPrompt() ?? "").Replace("\r", "").Replace("\n", " ").Trim();
		if (!string.IsNullOrWhiteSpace(settlementHeroNpcLine))
		{
			const string prefix = "当前定居点HeroNPC：";
			if (settlementHeroNpcLine.StartsWith(prefix, StringComparison.Ordinal))
			{
				settlementHeroNpcLine = settlementHeroNpcLine.Substring(prefix.Length).Trim();
			}
			if (!string.IsNullOrWhiteSpace(settlementHeroNpcLine))
			{
				stringBuilder.AppendLine();
				stringBuilder.Append("这个定居点有这些人物：").Append(settlementHeroNpcLine);
			}
		}
		string settlementFlavorLine = BuildSettlementFlavorLineForPrompt(hero);
		if (!string.IsNullOrWhiteSpace(settlementFlavorLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(settlementFlavorLine);
		}
		string settlementRulerPresenceLine = BuildSettlementRulerPresenceLineForPrompt();
		if (!string.IsNullOrWhiteSpace(settlementRulerPresenceLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(settlementRulerPresenceLine);
		}
		bool includePlayerPartyRoster = ShouldIncludePlayerPartyRosterForScenePrompt(hero, partyTransferTopicSelected);
		bool useCompactPlayerPartyRoster = includePlayerPartyRoster && ShouldUseCompactPlayerPartyRosterForScenePrompt(partyTransferTopicSelected);
		string playerIntroLine = BuildScenePlayerIntroForPrompt(hero, npc, includeTradePricing, includePlayerPartyRoster, useCompactPlayerPartyRoster);
		if (!string.IsNullOrWhiteSpace(playerIntroLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(playerIntroLine);
		}
		string prisonerContextLine = BuildPrisonerContextLineForPrompt(npc, hero);
		if (!string.IsNullOrWhiteSpace(prisonerContextLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(prisonerContextLine);
		}
		string playerCommandRelationshipLine = BuildPlayerCommandRelationshipLineForPrompt(npc, hero);
		if (!string.IsNullOrWhiteSpace(playerCommandRelationshipLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(playerCommandRelationshipLine);
		}
		string nearbyPresentNpcLine = BuildNearbyPresentNpcLineForPrompt(npc, presentNpcs);
		if (!string.IsNullOrWhiteSpace(nearbyPresentNpcLine))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(nearbyPresentNpcLine);
		}
		if (includeInventorySummary && !string.IsNullOrWhiteSpace(inventorySummary))
		{
			stringBuilder.AppendLine();
			stringBuilder.Append(hero != null ? BuildNpcInventorySummaryHeader(hero) : BuildNpcInventorySummaryHeader(GetSceneNpcHistoryNameForPrompt(npc)));
			stringBuilder.AppendLine();
			stringBuilder.Append(inventorySummary);
		}
		return stringBuilder.ToString().Trim();
	}

	private static string BuildHeroPregnancySelfKnowledgeForPrompt(Hero hero)
	{
		try
		{
			return hero != null && hero.IsPregnant
				? "你当前正在怀孕，并且清楚知道自己已经怀孕；这是实时事实，不能否认或遗忘"
				: "";
		}
		catch
		{
			return "";
		}
	}

	private static bool IsHeroInPlayerMainPartyForPrompt(Hero hero)
	{
		try
		{
			MobileParty mainParty = MobileParty.MainParty;
			return hero != null && hero != Hero.MainHero && mainParty != null && hero.PartyBelongedTo == mainParty;
		}
		catch
		{
			return false;
		}
	}

	private static string BuildPlayerCommandRelationshipLineForPrompt(NpcDataPacket npc, Hero hero)
	{
		try
		{
			if (!TryResolvePlayerCommandRelationshipForPrompt(npc, hero, out var relationship))
			{
				return "";
			}
			string playerName = (GetPlayerDisplayNameForShout() ?? "").Trim();
			if (string.IsNullOrWhiteSpace(playerName) || string.Equals(playerName, "玩家", StringComparison.Ordinal))
			{
				playerName = (Hero.MainHero?.Name?.ToString() ?? "").Trim();
			}
			if (string.IsNullOrWhiteSpace(playerName))
			{
				playerName = "玩家";
			}
			if (string.Equals(relationship, "exercise_opponent", StringComparison.OrdinalIgnoreCase))
			{
				return "【上下级关系】你认得" + playerName + "：你原本来自他的队伍。当前只是军事演习中被临时编入对抗队，你仍知道他是平日里的指挥官和这次演习的组织者；回应时不要把他当陌生人、外人或真正敌军。";
			}
			if (string.Equals(relationship, "player_side", StringComparison.OrdinalIgnoreCase))
			{
				return "【上下级关系】你认得" + playerName + "：当前战斗中你和他同属己方阵营，你知道他是己方指挥者，不应把他当陌生人、外人或敌人。";
			}
			return "【上下级关系】你认得" + playerName + "：他是你当前部队的指挥官和上级。你应以士兵面对长官的口吻回应，不要把他当陌生平民或外人。";
		}
		catch
		{
			return "";
		}
	}

	private static bool ShouldIncludePlayerPartyRosterForScenePrompt(Hero observerHero, bool partyTransferTopicSelected)
	{
		if (partyTransferTopicSelected)
		{
			return true;
		}
		if (AIConfigHandler.IsPlayerCompanionOrFamilyTradeTarget(observerHero))
		{
			return true;
		}
		return !IsSettlementSceneForPlayerPartyRosterSuppression();
	}

	private static bool ShouldUseCompactPlayerPartyRosterForScenePrompt(bool partyTransferTopicSelected)
	{
		if (partyTransferTopicSelected)
		{
			return false;
		}
		return IsSettlementSceneForPlayerPartyRosterSuppression();
	}

	private static bool IsSettlementSceneForPlayerPartyRosterSuppression()
	{
		try
		{
			if (LordEncounterBehavior.IsEncounterMeetingMissionActive)
			{
				return false;
			}
		}
		catch
		{
		}
		try
		{
			if (Settlement.CurrentSettlement != null)
			{
				return true;
			}
		}
		catch
		{
		}
		try
		{
			Settlement currentSettlement = MobileParty.MainParty?.CurrentSettlement;
			if (currentSettlement != null && !currentSettlement.IsHideout)
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static string BuildPlayerTownPartyStayHintForPrompt(Hero playerHero)
	{
		try
		{
			Settlement settlement = Settlement.CurrentSettlement ?? MobileParty.MainParty?.CurrentSettlement;
			if (settlement == null || !settlement.IsTown)
			{
				return "";
			}
			MobileParty party = MobileParty.MainParty;
			if (party?.MemberRoster == null)
			{
				return "";
			}
			if (party.CurrentSettlement != null && party.CurrentSettlement != settlement)
			{
				return "";
			}
			int totalMen = Math.Max(0, party.MemberRoster.TotalManCount);
			if (totalMen <= 0)
			{
				return "";
			}
			string playerName = (playerHero?.Name?.ToString() ?? "").Trim();
			if (string.IsNullOrWhiteSpace(playerName))
			{
				playerName = (GetPlayerDisplayNameForShout() ?? "").Trim();
			}
			if (string.IsNullOrWhiteSpace(playerName) || string.Equals(playerName, "玩家", StringComparison.Ordinal))
			{
				playerName = "此人";
			}
			return playerName + "拥有一支" + totalMen + "人的部队暂时驻扎在城外，你不清楚他的军队的具体明细";
		}
		catch
		{
			return "";
		}
	}

	private static string BuildPrisonerContextLineForPrompt(NpcDataPacket npc, Hero hero)
	{
		try
		{
			Agent agent = null;
			try
			{
				agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && npc != null && a.Index == npc.AgentIndex);
			}
			catch
			{
				agent = null;
			}
			if (CastleAftermathRuntimeBridge.IsPrisonerAgent(agent))
			{
				string castleSituation = SiegeAiInterventionBehavior.BuildCastleNpcSituationPromptForAgent(
					hero,
					agent?.Character as CharacterObject,
					npc?.AgentIndex ?? -1);
				if (!string.IsNullOrWhiteSpace(castleSituation))
				{
					return castleSituation;
				}
			}
			string heroPrisonerStatusLine = MyBehavior.BuildHeroPrisonerStatusPromptLineForExternal(hero);
			if (!string.IsNullOrWhiteSpace(heroPrisonerStatusLine))
			{
				return heroPrisonerStatusLine;
			}
			if (!IsInspectionPrisonerAgentForPrompt(agent))
			{
				return "";
			}
			string playerName = (GetPlayerDisplayNameForShout() ?? "").Trim();
			if (string.IsNullOrWhiteSpace(playerName) || string.Equals(playerName, "玩家", StringComparison.Ordinal))
			{
				playerName = (Hero.MainHero?.Name?.ToString() ?? "").Trim();
			}
			if (string.IsNullOrWhiteSpace(playerName))
			{
				playerName = "玩家";
			}
			string captor = playerName;
			if (hero?.PartyBelongedToAsPrisoner?.LeaderHero != null)
			{
				string captorName = (hero.PartyBelongedToAsPrisoner.LeaderHero.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(captorName))
				{
					captor = captorName;
				}
			}
			return "【俘虏处境】你现在是" + captor + "的俘虏，被押在当前阅兵/检阅场景中；你不属于" + playerName + "的正常部队，也不是他的下属或友方士兵。你应清楚自己处在被控制、被看押、行动受限的状态，并按俘虏身份回应。";
		}
		catch
		{
			return "";
		}
	}

	private static bool IsInspectionPrisonerNpcForPrompt(NpcDataPacket npc)
	{
		try
		{
			if (npc == null || npc.AgentIndex < 0)
			{
				return false;
			}
			Agent agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == npc.AgentIndex);
			return IsInspectionPrisonerAgentForPrompt(agent);
		}
		catch
		{
			return false;
		}
	}

	private static bool TryResolvePlayerCommandRelationshipForPrompt(NpcDataPacket npc, Hero hero, out string relationship)
	{
		relationship = "";
		try
		{
			if (hero != null && IsHeroInPlayerMainPartyForPrompt(hero))
			{
				relationship = "direct_command";
				return true;
			}
			Agent agent = null;
			try
			{
				agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && npc != null && a.Index == npc.AgentIndex);
			}
			catch
			{
				agent = null;
			}
			if (agent == null || agent.IsMainAgent)
			{
				return false;
			}
			CharacterObject character = agent.Character as CharacterObject;
			bool isSoldierLike = character?.IsSoldier == true || string.Equals((npc?.UnnamedRank ?? "").Trim(), "soldier", StringComparison.OrdinalIgnoreCase) || string.Equals((npc?.RoleDesc ?? "").Trim(), "士兵", StringComparison.Ordinal);
			if (!isSoldierLike && hero?.IsPlayerCompanion != true)
			{
				return false;
			}
			if (IsInspectionPrisonerAgentForPrompt(agent))
			{
				return false;
			}
			try
			{
				if (agent.Origin?.IsUnderPlayersCommand == true)
				{
					relationship = "direct_command";
					return true;
				}
			}
			catch
			{
			}
			PartyBase party = null;
			try
			{
				party = agent.Origin?.BattleCombatant as PartyBase;
			}
			catch
			{
				party = null;
			}
			if (party != null)
			{
				if (ReferenceEquals(party, PartyBase.MainParty) || ReferenceEquals(party.MobileParty, MobileParty.MainParty))
				{
					relationship = "direct_command";
					return true;
				}
				if (TryResolveMilitaryExerciseCommandRelationshipForPrompt(party, out relationship))
				{
					return true;
				}
				return false;
			}
			Mission mission = Mission.Current;
			if (mission?.PlayerTeam != null && agent.Team == mission.PlayerTeam)
			{
				relationship = "player_side";
				return true;
			}
		}
		catch
		{
			relationship = "";
		}
		return false;
	}

	private static bool TryResolveMilitaryExerciseCommandRelationshipForPrompt(PartyBase party, out string relationship)
	{
		relationship = "";
		try
		{
			if (party == null || !MilitaryExerciseBehavior.IsCurrentExerciseRuntime())
			{
				return false;
			}
			MilitaryExerciseBehavior.MilitaryExerciseRuntime runtime = MilitaryExerciseBehavior.GetCurrentRuntime();
			if (runtime == null)
			{
				return false;
			}
			if (ReferenceEquals(party, runtime.OpponentDummyParty?.Party) || ReferenceEquals(party.MobileParty, runtime.OpponentDummyParty))
			{
				relationship = "exercise_opponent";
				return true;
			}
			if (ReferenceEquals(party, runtime.HoldingDummyParty?.Party) || ReferenceEquals(party.MobileParty, runtime.HoldingDummyParty))
			{
				relationship = "direct_command";
				return true;
			}
		}
		catch
		{
			relationship = "";
		}
		return false;
	}

	private static bool IsInspectionPrisonerAgentForPrompt(Agent agent)
