	private static string BuildFactionNameForPrompt(IFaction faction)
	{
		try
		{
			string text = (faction?.Name?.ToString() ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
			if (!string.IsNullOrWhiteSpace(text))
