	{
		return SubmitNativeConversationTextForExternalAsync(playerText, null, null, null);
	}

	public static Task<string> SubmitNativeConversationTextForExternalAsync(string playerText, Action<string> onStreamText)
	{
		return SubmitNativeConversationTextForExternalAsync(playerText, onStreamText, null, null);
	}

	public static Task<string> SubmitNativeConversationTextForExternalAsync(string playerText, Action<string> onStreamText, string currentDialogTextOverride)
	{
		return SubmitNativeConversationTextForExternalAsync(playerText, onStreamText, currentDialogTextOverride, null);
	}

	public static Task<string> SubmitNativeConversationTextForExternalAsync(string playerText, Action<string> onStreamText, string currentDialogTextOverride, Action<string> onPostprocessStarted)
	{
		return SubmitNativeConversationTextForExternalAsync(playerText, onStreamText, currentDialogTextOverride, onPostprocessStarted, null);
	}

	// The main-reply callback is deliberately separate from postprocess start so UI can present a completed reply while actions still resolve.
	public static Task<string> SubmitNativeConversationTextForExternalAsync(string playerText, Action<string> onStreamText, string currentDialogTextOverride, Action<string> onPostprocessStarted, Action<string, Hero, CharacterObject> onMainReplyReady)
	{
		ShoutBehavior currentInstance = CurrentInstance;
		if (currentInstance == null)
		{
			return Task.FromResult("AnimusForge ShoutBehavior is not ready.");
		}
		if (PlayerEncounterCompat.IsInPostBattleResultFlow())
		{
			return Task.FromResult("");
		}
		return Task.Run(async delegate
		{
			SynchronizationContext.SetSynchronizationContext(null);
			return await currentInstance.SubmitNativeConversationTextInternalAsync(playerText, onStreamText, currentDialogTextOverride, onPostprocessStarted, onMainReplyReady).ConfigureAwait(false);
		});
	}

	public static Task<string> SubmitNativeConversationNpcInitiatedOpeningForExternalAsync(Action<string> onStreamText, string currentDialogTextOverride, Action<string> onPostprocessStarted)
	{
		return SubmitNativeConversationNpcInitiatedOpeningForExternalAsync(onStreamText, currentDialogTextOverride, onPostprocessStarted, null);
	}

	// Keep the existing three-argument entry point intact while exposing the same early completed-reply signal for NPC openings.
	public static Task<string> SubmitNativeConversationNpcInitiatedOpeningForExternalAsync(Action<string> onStreamText, string currentDialogTextOverride, Action<string> onPostprocessStarted, Action<string, Hero, CharacterObject> onMainReplyReady)
	{
		ShoutBehavior currentInstance = CurrentInstance;
		if (currentInstance == null)
		{
			return Task.FromResult("AnimusForge ShoutBehavior is not ready.");
		}
		if (PlayerEncounterCompat.IsInPostBattleResultFlow())
		{
			return Task.FromResult("");
		}
		return Task.Run(async delegate
		{
			SynchronizationContext.SetSynchronizationContext(null);
			return await currentInstance.SubmitNativeConversationTextInternalAsync("", onStreamText, currentDialogTextOverride, onPostprocessStarted, onMainReplyReady, npcInitiatedOpening: true).ConfigureAwait(false);
		});
	}

	private static bool TryResolveNativeConversationTarget(out Hero targetHero, out CharacterObject targetCharacter, out string npcName)
	{
		targetHero = null;
		targetCharacter = null;
		npcName = "";
		try
		{
			targetHero = Hero.OneToOneConversationHero;
		}
		catch
		{
			targetHero = null;
		}
		try
		{
			targetCharacter = CharacterObject.OneToOneConversationCharacter;
		}
		catch
		{
			targetCharacter = null;
		}
		if (targetHero == null)
		{
			targetHero = targetCharacter?.HeroObject;
		}
		if ((targetHero == null && targetCharacter == null) || IsNativeConversationSelfTarget(targetHero, targetCharacter))
		{
			if (TryResolveNativeConversationTargetFromAgent(out var agentHero, out var agentCharacter, out var agentName))
			{
				targetHero = agentHero;
				targetCharacter = agentCharacter;
				npcName = agentName;
			}
		}
		if (targetHero == null)
		{
			try
			{
				targetHero = PlayerEncounter.EncounteredParty?.LeaderHero;
			}
			catch
			{
				targetHero = null;
			}
		}
		if (targetCharacter == null)
		{
			targetCharacter = targetHero?.CharacterObject;
		}
		if (targetCharacter == null)
		{
			try
			{
				targetCharacter = TaleWorlds.CampaignSystem.Conversation.ConversationHelper.GetConversationCharacterPartyLeader(PlayerEncounter.EncounteredParty);
			}
			catch
			{
				targetCharacter = null;
			}
		}
		if (targetHero == null)
		{
			targetHero = targetCharacter?.HeroObject;
		}
		if (targetHero == null && TryResolveNativeConversationTargetFromAgent(out var directAgentHero, out var directAgentCharacter, out var directAgentName) && !IsNativeConversationSelfTarget(directAgentHero, directAgentCharacter))
		{
			targetHero = directAgentHero;
			targetCharacter = directAgentCharacter;
			npcName = directAgentName;
		}
		if (IsNativeConversationSelfTarget(targetHero, targetCharacter))
		{
			if (TryResolveNativeConversationTargetFromAgent(out var agentHero, out var agentCharacter, out var agentName) && !IsNativeConversationSelfTarget(agentHero, agentCharacter))
			{
				targetHero = agentHero;
				targetCharacter = agentCharacter;
				npcName = agentName;
			}
			else
			{
				targetHero = null;
				targetCharacter = null;
				npcName = "";
				return false;
			}
		}
		npcName = (targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString() ?? "").Trim();
		return targetHero != null || targetCharacter != null;
	}

	private static bool IsNativeConversationSelfTarget(Hero targetHero, CharacterObject targetCharacter)
	{
		try
		{
			if (targetHero != null && targetHero == Hero.MainHero)
			{
				return true;
			}
			CharacterObject playerCharacter = CharacterObject.PlayerCharacter ?? Hero.MainHero?.CharacterObject;
			return targetCharacter != null && playerCharacter != null && targetCharacter == playerCharacter;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryResolveNativeConversationTargetFromAgent(out Hero targetHero, out CharacterObject targetCharacter, out string npcName)
	{
		targetHero = null;
		targetCharacter = null;
		npcName = "";
		try
		{
			Agent agent = Campaign.Current?.ConversationManager?.OneToOneConversationAgent as Agent;
			if (agent == null || agent.IsMainAgent || agent.Character == null)
			{
				return false;
			}
			targetCharacter = agent.Character as CharacterObject;
			targetHero = targetCharacter?.HeroObject;
			if (IsNativeConversationSelfTarget(targetHero, targetCharacter))
			{
				targetHero = null;
				targetCharacter = null;
				return false;
			}
			npcName = (targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString() ?? agent.Name ?? "").Trim();
			return targetHero != null || targetCharacter != null;
		}
		catch
		{
			targetHero = null;
			targetCharacter = null;
			npcName = "";
			return false;
		}
	}

	private static NpcDataPacket BuildNativeConversationNpcData(Hero targetHero, CharacterObject targetCharacter)
	{
		try
		{
			int agentIndex = TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
			var agents = Mission.Current?.Agents;
			if (agentIndex >= 0 && agents != null)
			{
				Agent agent = agents.FirstOrDefault((Agent a) => a != null && a.Index == agentIndex && a.IsActive());
				NpcDataPacket sceneNpc = ShoutUtils.ExtractNpcData(agent);
				if (sceneNpc != null)
				{
					sceneNpc.AgentIndex = agentIndex;
					return sceneNpc;
				}
			}
		}
		catch
		{
		}
		string npcName = (targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString() ?? "NPC").Trim();
		string role = "";
		string personality = "";
		string background = "";
		try
		{
			role = targetHero != null ? MyBehavior.BuildHeroIdentityTitleForExternal(targetHero) : (targetCharacter?.Occupation.ToString() ?? "");
		}
		catch
		{
			role = "";
		}
		if (targetHero != null)
		{
			try
			{
				MyBehavior.GetNpcPersonaForExternal(targetHero, out personality, out background);
			}
			catch
			{
				personality = "";
				background = "";
			}
		}
		Hero npcHero = targetHero ?? targetCharacter?.HeroObject;
		bool isNonHero = npcHero == null;
		string troopId = targetCharacter?.StringId ?? targetHero?.CharacterObject?.StringId ?? "";
		int unnamedAgentIndex = isNonHero ? TryResolveNativeConversationAgentIndex(targetHero, targetCharacter) : -1;
		string unnamedKey = isNonHero ? BuildNativeConversationNonHeroUnnamedKey(targetCharacter, npcName, unnamedAgentIndex) : "";
		string unnamedRank = "";
		if (isNonHero)
		{
			try
			{
				unnamedRank = targetCharacter != null && targetCharacter.IsSoldier ? "soldier" : "commoner";
			}
			catch
			{
				unnamedRank = "";
			}
		}
		float age = npcHero?.Age ?? (isNonHero ? ResolveNativeConversationNonHeroAge(targetCharacter) : 0f);
		return new NpcDataPacket
		{
			Name = npcName,
			RoleDesc = string.IsNullOrWhiteSpace(role) ? "原版对话对象" : role,
			PersonalityDesc = (personality ?? "").Trim(),
			BackgroundDesc = (background ?? "").Trim(),
			AgentIndex = -1,
			IsHero = !isNonHero,
			CultureId = targetHero?.Culture?.StringId ?? targetCharacter?.Culture?.StringId ?? "neutral",
			UnnamedKey = unnamedKey,
			TroopId = troopId,
			UnnamedRank = unnamedRank,
			IsFemale = targetHero?.IsFemale ?? targetCharacter?.IsFemale ?? false,
			Age = age,
			PromptGivenName = npcName,
			PromptDisplayName = npcName
		};
	}

	private sealed class PendingNativeSceneMechanismAction
	{
		public NpcDataPacket Speaker;

		public List<NpcDataPacket> Context;

		public List<SceneSummonPromptTarget> SummonTargets;

		public List<SceneGuidePromptTarget> GuideTargets;

		public string Tags;

		public long CreatedUtcTicks;
	}

	private sealed class PendingNativeSceneTauntFight
	{
		public Hero TargetHero;

		public CharacterObject TargetCharacter;

		public int TargetAgentIndex;

		public string TargetKey;

		public string TargetName;

		public float ExecuteAtMissionTime;

		public long CreatedUtcTicks;
	}

	private bool TryQueueNativeSceneMechanismActionAfterConversationExit(NpcDataPacket npc, List<NpcDataPacket> allNpcData, List<SceneSummonPromptTarget> sceneSummonTargets, List<SceneGuidePromptTarget> sceneGuideTargets, ref string content)
	{
		if (ContainsOpenLordsHallActionTag(content))
		{
			// OPEN_LORDS_HALL is an immediate scene transition, never an escort follow-up.
			return false;
		}
		string text = ExtractSceneMechanismActionTagsForScene(content);
		if (npc == null || string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		content = StripSceneMechanismActionTagsForScene(content);
		PendingNativeSceneMechanismAction pending = new PendingNativeSceneMechanismAction
		{
			Speaker = CloneNpcDataPacket(npc),
			Context = CloneNpcDataSnapshot(allNpcData),
			SummonTargets = CloneSceneSummonPromptTargets(sceneSummonTargets),
			GuideTargets = CloneSceneGuidePromptTargets(sceneGuideTargets),
			Tags = text,
			CreatedUtcTicks = DateTime.UtcNow.Ticks
		};
		int pendingCount;
		lock (_pendingNativeSceneMechanismActionLock)
		{
			_pendingNativeSceneMechanismActions.Enqueue(pending);
			pendingCount = _pendingNativeSceneMechanismActions.Count;
		}
		ShowNativeSceneMechanismPendingExitPrompt(pendingCount);
		Logger.Log("ShoutBehavior", "[NativeConversation] deferred scene mechanism action until manual conversation exit agent=" + pending.Speaker.AgentIndex + " pending=" + pendingCount + " tags=" + text.Replace("\r", "\\r").Replace("\n", "\\n"));
		return true;
	}

	private static void ShowNativeSceneMechanismPendingExitPrompt(int pendingCount)
	{
		try
		{
			string suffix = pendingCount > 1 ? (" 当前待执行 " + pendingCount + " 个。") : "";
			InformationManager.DisplayMessage(new InformationMessage("SCENE_MOVE已准备。请手动退出对话框，退出后将执行NPC场景动作。" + suffix, new Color(1f, 0.95f, 0.25f)));
		}
		catch
		{
		}
	}

	private void ExecutePendingNativeSceneMechanismActionsAfterConversationExit(string reason)
	{
		List<PendingNativeSceneMechanismAction> pendingActions = new List<PendingNativeSceneMechanismAction>();
		lock (_pendingNativeSceneMechanismActionLock)
		{
			while (_pendingNativeSceneMechanismActions.Count > 0)
			{
				pendingActions.Add(_pendingNativeSceneMechanismActions.Dequeue());
			}
		}
		if (pendingActions.Count == 0)
		{
			return;
		}
		foreach (PendingNativeSceneMechanismAction pending in pendingActions)
		{
			_mainThreadActions.Enqueue(delegate
			{
				ExecutePendingNativeSceneMechanismAction(pending, reason);
			});
		}
		Logger.Log("ShoutBehavior", "[NativeConversation] queued deferred scene mechanism actions after manual exit count=" + pendingActions.Count + " reason=" + (reason ?? ""));
		TryDrainNativeConversationQueuedActions("scene_mechanism_after_conversation_exit");
	}

	private void ExecutePendingNativeSceneMechanismAction(PendingNativeSceneMechanismAction pending, string reason)
	{
		if (pending == null || pending.Speaker == null || string.IsNullOrWhiteSpace(pending.Tags))
		{
			return;
		}
		try
		{
			if (TryExecuteNativeSceneMechanismActionTagsDirectly(pending.Speaker, pending.SummonTargets, pending.GuideTargets, pending.Tags))
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] executed deferred scene mechanism action agent=" + pending.Speaker.AgentIndex + " reason=" + (reason ?? "") + " tags=" + pending.Tags.Replace("\r", "\\r").Replace("\n", "\\n"));
				return;
			}
			EnqueueSpeechLineWithOptions(pending.Speaker, pending.Tags, pending.Context, commitHistory: false, suppressStare: true, allowPlayerDirectedActions: true, requiredConversationEpoch: 0, pending.SummonTargets, pending.GuideTargets, null);
			Logger.Log("ShoutBehavior", "[NativeConversation] queued deferred scene mechanism action fallback agent=" + pending.Speaker.AgentIndex + " reason=" + (reason ?? "") + " tags=" + pending.Tags.Replace("\r", "\\r").Replace("\n", "\\n"));
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] execute deferred scene mechanism action failed: " + ex.Message);
		}
	}

	private void ClearPendingNativeSceneMechanismActions(string reason)
	{
		try
		{
			int count;
			lock (_pendingNativeSceneMechanismActionLock)
			{
				count = _pendingNativeSceneMechanismActions.Count;
				_pendingNativeSceneMechanismActions.Clear();
			}
			if (count > 0)
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] cleared pending scene mechanism actions count=" + count + " reason=" + (reason ?? ""));
			}
		}
		catch
		{
		}
	}

	private bool ScheduleNativeSceneTauntFightAfterDelay(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, string targetKey, string reason)
	{
		try
		{
			Mission mission = Mission.Current;
			if (mission == null)
			{
				return false;
			}
			string targetName = (targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString() ?? "NPC").Trim();
			if (string.IsNullOrWhiteSpace(targetName))
			{
				targetName = "NPC";
			}
			PendingNativeSceneTauntFight pending = new PendingNativeSceneTauntFight
			{
				TargetHero = targetHero,
				TargetCharacter = targetCharacter,
				TargetAgentIndex = targetAgentIndex,
				TargetKey = targetKey,
				TargetName = targetName,
				ExecuteAtMissionTime = mission.CurrentTime + NativeSceneTauntFightDelaySeconds,
				CreatedUtcTicks = DateTime.UtcNow.Ticks
			};
			lock (_pendingNativeSceneTauntFightLock)
			{
				_pendingNativeSceneTauntFight = pending;
			}
			try
			{
				InformationManager.DisplayMessage(new InformationMessage("SCENE_TAUNT_FIGHT已触发：10秒后将自动退出对话并爆发冲突。", new Color(1f, 0.55f, 0.25f)));
			}
			catch
			{
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] delayed scene taunt fight scheduled target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? targetName) + " agentIndex=" + targetAgentIndex + " executeAt=" + pending.ExecuteAtMissionTime.ToString("F2") + " reason=" + (reason ?? ""));
			return true;
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] schedule delayed scene taunt fight failed: " + ex.Message);
			return false;
		}
	}

	private void UpdatePendingNativeSceneTauntFightDelay()
	{
		PendingNativeSceneTauntFight pending = null;
		try
		{
			Mission mission = Mission.Current;
			if (mission == null)
			{
				return;
			}
			lock (_pendingNativeSceneTauntFightLock)
			{
				if (_pendingNativeSceneTauntFight == null)
				{
					return;
				}
				double elapsedRealSeconds = new TimeSpan(Math.Max(0L, DateTime.UtcNow.Ticks - _pendingNativeSceneTauntFight.CreatedUtcTicks)).TotalSeconds;
				bool missionTimeElapsed = mission.CurrentTime >= _pendingNativeSceneTauntFight.ExecuteAtMissionTime;
				bool realTimeElapsed = elapsedRealSeconds >= NativeSceneTauntFightDelaySeconds;
				if (!missionTimeElapsed && !realTimeElapsed)
				{
					return;
				}
				pending = _pendingNativeSceneTauntFight;
				_pendingNativeSceneTauntFight = null;
			}
			ExecuteDelayedNativeSceneTauntFight(pending);
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] update delayed scene taunt fight failed: " + ex.Message);
			if (pending != null)
			{
				ClearPendingNativeSceneTauntFight("update_failed");
			}
		}
	}

	private void ExecuteDelayedNativeSceneTauntFight(PendingNativeSceneTauntFight pending)
	{
		if (pending == null)
		{
			return;
		}
		try
		{
			CloseNativeConversationForSceneMechanism("native_scene_taunt_fight_delay_elapsed");
			bool started = SceneTauntBehavior.TryStartSceneTauntFightForExternal(pending.TargetHero, pending.TargetCharacter, pending.TargetAgentIndex, pending.TargetKey, "native_scene_taunt_fight_delay_elapsed");
			try
			{
				InformationManager.DisplayMessage(new InformationMessage(started ? "冲突爆发！" : "冲突未能爆发：当前场景目标不可用。", started ? new Color(1f, 0.35f, 0.2f) : new Color(1f, 0.75f, 0.25f)));
			}
			catch
			{
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] delayed scene taunt fight executed started=" + started + " target=" + (pending.TargetHero?.StringId ?? pending.TargetCharacter?.StringId ?? pending.TargetName ?? "unknown") + " agentIndex=" + pending.TargetAgentIndex);
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] execute delayed scene taunt fight failed: " + ex.Message);
		}
	}

	private void ClearPendingNativeSceneTauntFight(string reason)
	{
		try
		{
			bool hadPending;
			lock (_pendingNativeSceneTauntFightLock)
			{
				hadPending = _pendingNativeSceneTauntFight != null;
				_pendingNativeSceneTauntFight = null;
			}
			if (hadPending)
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] cleared delayed scene taunt fight reason=" + (reason ?? ""));
			}
		}
		catch
		{
		}
	}

	private bool TryExecuteNativeSceneMechanismActionTagsDirectly(NpcDataPacket npc, List<SceneSummonPromptTarget> sceneSummonTargets, List<SceneGuidePromptTarget> sceneGuideTargets, string tags)
	{
		Mission mission = Mission.Current;
		var agents = mission?.Agents;
		if (npc == null || string.IsNullOrWhiteSpace(tags) || agents == null)
		{
			return false;
		}
		Agent agent = agents.FirstOrDefault((Agent a) => a != null && a.Index == npc.AgentIndex);
		string content = tags;
		bool openLordsHall = TryTriggerOpenLordsHallAction(npc, agent, ref content);
		if (openLordsHall)
		{
			bool waitForConversationEnd = IsNativeConversationActiveForLordsHallEntry();
			ScheduleLordsHallMissionEntryAfterSpeech(npc.AgentIndex, null, "native_scene_direct_tag", waitForConversationEnd);
			if (waitForConversationEnd)
			{
				CloseNativeConversationForSceneMechanism("native_scene_open_lords_hall_tag");
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] scene mechanism direct result agent=" + npc.AgentIndex + " openLordsHall=True");
			return true;
		}
		bool setsOwnedMassacre = TryProcessSetsOwnedSettlementMassacreActionTags(npc.AgentIndex, ref content);
		if (setsOwnedMassacre && string.IsNullOrWhiteSpace(content))
		{
			return true;
		}
		if (IsPrisonBreakRescueMissionActive() && (SceneFollowStartTagRegex.IsMatch(tags) || SceneFollowStopTagRegex.IsMatch(tags)))
		{
			Agent commandAgent = ResolvePrisonBreakSceneFollowCommandAgent(agent);
			if (commandAgent != null && commandAgent != agent)
			{
				Logger.Log("SceneFollow", "prison_break_native_follow_redirect requested=" + (agent?.Index ?? npc.AgentIndex) + " prisoner=" + commandAgent.Index);
				agent = commandAgent;
				npc = ShoutUtils.ExtractNpcData(commandAgent) ?? npc;
			}
		}
		if (!CanAgentParticipateInSceneSpeech(agent) || agent == Agent.Main)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] scene mechanism direct skip agent=" + (npc?.AgentIndex ?? -1) + " reason=agent_unavailable tags=" + ((tags ?? "").Replace("\r", "\\r").Replace("\n", "\\n")));
			return false;
		}
		SceneSummonConversationSession sceneSummonConversationSession = null;
		ActiveSceneSummonRequest activeSceneSummonRequest = null;
		ActiveSceneGuideRequest activeSceneGuideRequest = null;
		bool stopFollow = TryConsumeSceneFollowStopTag(npc, agent, ref content);
		bool startFollow = TryConsumeSceneFollowStartTag(npc, agent, ref content);
		bool endChat = TryConsumeSceneEndChatActionTag(npc, agent, ref content, out sceneSummonConversationSession);
		bool summon = !openLordsHall && !string.IsNullOrWhiteSpace(content) && TryTriggerSceneSummonAction(npc, agent, sceneSummonTargets, ref content, out activeSceneSummonRequest);
		bool guide = !openLordsHall && !string.IsNullOrWhiteSpace(content) && TryTriggerSceneGuideAction(npc, agent, sceneGuideTargets, sceneSummonTargets, ref content, out activeSceneGuideRequest);
		bool handled = setsOwnedMassacre || openLordsHall || stopFollow || startFollow || endChat || summon || guide;
		if (!handled)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] scene mechanism direct no-op agent=" + npc.AgentIndex + " tags=" + ((tags ?? "").Replace("\r", "\\r").Replace("\n", "\\n")));
			return false;
		}
		if (stopFollow)
		{
			StopSceneSummonFollowPlayer(agent, restoreDailyBehaviors: false);
			ReturnAgentAfterStoppingSceneFollow(agent);
		}
		else if (startFollow)
		{
			RememberSceneFollowReturnState(agent, overwriteExisting: true);
			RemoveAgentFromSceneSummonConversationForFollow(agent);
			StartSceneSummonFollowPlayer(agent);
		}
		if (endChat && sceneSummonConversationSession != null)
		{
			BeginSceneSummonConversationReturn(sceneSummonConversationSession);
		}
		if (summon && activeSceneSummonRequest != null)
		{
			SchedulePreparedSceneSummonLaunch(activeSceneSummonRequest, null, "");
		}
		if (guide && activeSceneGuideRequest != null)
		{
			SchedulePreparedSceneGuideLaunch(activeSceneGuideRequest, null, "");
		}
		Logger.Log("ShoutBehavior", "[NativeConversation] scene mechanism direct result agent=" + npc.AgentIndex + " openLordsHall=" + openLordsHall + " setsMassacre=" + setsOwnedMassacre + " stop=" + stopFollow + " start=" + startFollow + " end=" + endChat + " summon=" + summon + " guide=" + guide + " remaining=" + ((content ?? "").Replace("\r", "\\r").Replace("\n", "\\n")));
		return true;
	}

	private static void CloseNativeConversationForSceneMechanism(string reason)
	{
		try
		{
			CloseNativeConversationInput(clearSessionHistory: false);
			ConversationManager conversationManager = Campaign.Current?.ConversationManager;
			if (conversationManager != null && (conversationManager.IsConversationInProgress || conversationManager.IsConversationFlowActive))
			{
				conversationManager.EndConversation();
				Logger.Log("ShoutBehavior", "[NativeConversation] closed native conversation for scene mechanism. reason=" + (reason ?? ""));
			}
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] close native conversation for scene mechanism failed: " + ex.Message);
		}
	}

	private bool TryTriggerNativeConversationOpenLordsHallAction(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, ref string content)
	{
		if (!ContainsOpenLordsHallActionTag(content))
		{
			return false;
		}
		try
		{
			NpcDataPacket npc = BuildNativeConversationNpcData(targetHero, targetCharacter);
			npc.AgentIndex = targetAgentIndex;
			Agent agent = (targetAgentIndex >= 0) ? Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == targetAgentIndex) : null;
			bool result = TryTriggerOpenLordsHallAction(npc, agent, ref content);
			if (result)
			{
				content = StripActionTagsForSceneSpeech(content);
				bool waitForConversationEnd = IsNativeConversationActiveForLordsHallEntry();
				ScheduleLordsHallMissionEntryAfterSpeech(targetAgentIndex, null, "native_conversation_tag", waitForConversationEnd);
				if (waitForConversationEnd)
				{
					CloseNativeConversationForSceneMechanism("native_conversation_open_lords_hall_tag");
				}
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] open lords hall tag handled=" + result + " target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agentIndex=" + targetAgentIndex);
			return result;
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] open lords hall action failed: " + ex.Message);
			return false;
		}
	}

	private bool TryProcessSetsOwnedSettlementMassacreActionTags(int targetAgentIndex, ref string content)
	{
		try
		{
			bool requestPermission = !string.IsNullOrWhiteSpace(content) && SetsOwnedSettlementMassacreRequestActionTagRegex.IsMatch(content);
			bool startRequested = !string.IsNullOrWhiteSpace(content) && SetsOwnedSettlementMassacreStartActionTagRegex.IsMatch(content);
			bool stopRequested = !string.IsNullOrWhiteSpace(content) && SetsOwnedSettlementMassacreStopActionTagRegex.IsMatch(content);
			bool cancelRequest = !string.IsNullOrWhiteSpace(content) && SetsOwnedSettlementMassacreCancelRequestActionTagRegex.IsMatch(content);
			if (!requestPermission && !startRequested && !stopRequested && !cancelRequest)
			{
				return false;
			}

			content = StripSetsOwnedSettlementMassacreActionTags(content);
			Mission mission = Mission.Current;
			if (!SettlementEntryTroopSelectionBehavior.IsOwnedOrAttachedSettlementEntryActiveForExternal(mission))
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] ignored SETS massacre tag outside owned/attached settlement scene. agent=" + targetAgentIndex);
				return false;
			}

			bool massacreActive = SettlementEntryTroopSelectionBehavior.IsOwnedOrAttachedSettlementMassacreActiveForExternal(mission);
			bool requestPendingForSpeaker = SettlementEntryTroopSelectionBehavior.IsOwnedOrAttachedSettlementMassacreRequestPendingForExternal(mission, targetAgentIndex);
			bool anyRequestPending = SettlementEntryTroopSelectionBehavior.HasOwnedOrAttachedSettlementMassacreRequestForExternal(mission);
			bool handled = false;
			string action = "none";
			if (stopRequested && massacreActive)
			{
				action = "stop";
				handled = SettlementEntryTroopSelectionBehavior.TryStopOwnedOrAttachedSettlementMassacreForExternal(targetAgentIndex, SetsOwnedSettlementMassacreProfile.StopSource);
			}
			else if (cancelRequest && !massacreActive && requestPendingForSpeaker)
			{
				action = "cancel_request";
				handled = SettlementEntryTroopSelectionBehavior.TryCancelOwnedOrAttachedSettlementMassacreRequestForExternal(targetAgentIndex, SetsOwnedSettlementMassacreProfile.CancelRequestSource);
			}
			else if (startRequested && !massacreActive)
			{
				action = "start";
				handled = SettlementEntryTroopSelectionBehavior.TryStartOwnedOrAttachedSettlementMassacreForExternal(targetAgentIndex, SetsOwnedSettlementMassacreProfile.StartSource);
			}
			else if (requestPermission && !massacreActive && !anyRequestPending)
			{
				action = "request_permission";
				handled = SettlementEntryTroopSelectionBehavior.TryRecordOwnedOrAttachedSettlementMassacreRequestForExternal(targetAgentIndex, SetsOwnedSettlementMassacreProfile.RequestSource);
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] SETS owned/attached massacre tag action=" + action
				+ " handled=" + handled
				+ " activeBefore=" + massacreActive
				+ " pendingForSpeaker=" + requestPendingForSpeaker
				+ " anyPending=" + anyRequestPending
				+ " agent=" + targetAgentIndex);
			return handled;
		}
		catch (Exception ex)
		{
			content = StripSetsOwnedSettlementMassacreActionTags(content);
			Logger.Log("ShoutBehavior", "[NativeConversation] SETS owned/attached massacre action failed: " + ex.Message);
			return false;
		}
	}

	private static string StripSetsOwnedSettlementMassacreActionTags(string content)
	{
		string result = SetsOwnedSettlementMassacreRequestActionTagRegex.Replace(content ?? "", "");
		result = SetsOwnedSettlementMassacreStartActionTagRegex.Replace(result, "");
		result = SetsOwnedSettlementMassacreStopActionTagRegex.Replace(result, "");
		result = SetsOwnedSettlementMassacreCancelRequestActionTagRegex.Replace(result, "");
		return result.Trim();
	}

	private static bool TryProcessCustomPolicyAgendaActionTag(Hero targetHero, string chainName, string playerProposalText, ref string content, string npcReplyTextOverride = null)
	{
		if (string.IsNullOrWhiteSpace(content) || !CustomPolicyAgendaActionTagRegex.IsMatch(content))
		{
			return false;
		}
		string resolvedChainName = string.IsNullOrWhiteSpace(chainName) ? "native" : chainName.Trim();
		string npcReplyText = StripActionTagsForSceneSpeech(string.IsNullOrWhiteSpace(npcReplyTextOverride) ? content : npcReplyTextOverride);
		string failureReason = "";
		bool started = false;
		try
		{
			started = KingdomAgendaCustomPolicyBehavior.TryProcessAcceptedAgendaTag(targetHero, resolvedChainName, playerProposalText, npcReplyText, ref content, out failureReason);
			Logger.Log("ShoutBehavior", "[CustomPolicyAgenda] dispatch chain=" + resolvedChainName + " ruler=" + (targetHero?.StringId ?? "null") + " started=" + started + " reason=" + (failureReason ?? ""));
		}
		catch (Exception ex)
		{
			failureReason = ex.GetType().Name + ": " + ex.Message;
			Logger.Log("ShoutBehavior", "[CustomPolicyAgenda] dispatch exception chain=" + resolvedChainName + " ruler=" + (targetHero?.StringId ?? "null") + " error=" + failureReason);
			PolicySystemLog.Failure("CustomPolicyAgenda", "dispatch-failure", "Policy proposal action dispatch failed. chain=" + resolvedChainName + " ruler=" + (targetHero?.StringId ?? "null"), failureReason);
		}
		finally
		{
			// Internal action tags must never leak into scene/native/courier-visible text,
			// including rejected or exceptional paths.
			content = CustomPolicyAgendaActionTagRegex.Replace(content ?? "", "").Trim();
		}
		return started;
	}

	private WorldMapPartyCommandBehavior.WorldMapOrderApplyResult ApplyNativeConversationActionTags(
		Hero targetHero,
		CharacterObject targetCharacter,
		ref string content,
		int targetAgentIndexOverride = -1,
		string latestPlayerText = null,
		ConversationManager expectedConversationManager = null,
		int expectedConversationToken = int.MinValue,
		string actionChainName = null,
		string npcReplyTextOverride = null)
	{
		WorldMapPartyCommandBehavior.WorldMapOrderApplyResult worldMapResult = new WorldMapPartyCommandBehavior.WorldMapOrderApplyResult();
		if (string.IsNullOrWhiteSpace(content))
		{
			return worldMapResult;
		}
		targetHero = targetHero ?? targetCharacter?.HeroObject;
		int resolvedTargetAgentIndex = targetAgentIndexOverride >= 0 ? targetAgentIndexOverride : TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
		if (TryTriggerNativeConversationOpenLordsHallAction(targetHero, targetCharacter, resolvedTargetAgentIndex, ref content))
		{
			return worldMapResult;
		}
		if (!IsNativeConversationResponseTargetAvailableForActionDispatch(resolvedTargetAgentIndex, targetHero, targetCharacter, out string unavailableReason))
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] dropped postprocess response because target is unavailable target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agentIndex=" + resolvedTargetAgentIndex + " reason=" + unavailableReason);
			content = "";
			return worldMapResult;
		}
		NoblePrisonerEscortBehavior.TryProcessSceneExecutionTag(
			resolvedTargetAgentIndex,
			!string.IsNullOrWhiteSpace(latestPlayerText),
			ref content);
		NoblePrisonerExecutionOrderBehavior.TryProcessAcceptedTag(
			targetHero,
			resolvedTargetAgentIndex,
			!string.IsNullOrWhiteSpace(latestPlayerText),
			ref content,
			out _);
		TroopInspectionBehavior.TryProcessPrisonerSlaughterActionTagForExternal(
			resolvedTargetAgentIndex,
			ref content);
		if (string.IsNullOrWhiteSpace(content))
		{
			return worldMapResult;
		}
		try
		{
			LogNativeActionStep("start", targetHero, targetCharacter, content);
			TryProcessSetsOwnedSettlementMassacreActionTags(resolvedTargetAgentIndex, ref content);
			int siegeAgentIndex = resolvedTargetAgentIndex;
			bool siegeActionHandled;
			LogNativeActionStep("siege_before", targetHero, targetCharacter, content);
			if (AfGcczShoutBridge.TryProcessActionTags(
				targetHero,
				targetCharacter,
				siegeAgentIndex,
				ref content,
				out siegeActionHandled,
				replyIsDirectPlayerResponse: true,
				playerText: latestPlayerText) && siegeActionHandled)
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] siege_intervention handled target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown"));
			}
			LogNativeActionStep("siege_after", targetHero, targetCharacter, content);

			if (targetHero != null)
			{
				LogNativeActionStep("hero_dispatch_before", targetHero, targetCharacter, content);
				TryProcessCustomPolicyAgendaActionTag(targetHero, actionChainName ?? ResolveNativeConversationPostprocessChainName(), latestPlayerText, ref content, npcReplyTextOverride);
				VoteDealBehavior.ProcessAgendaTagsDispatch(targetHero, ref content);
				DiplomacyBehavior.ProcessDiplomacyTagsDispatch(targetHero, ref content);
				worldMapResult = WorldMapPartyCommandBehavior.ProcessWorldMapOrderTagsDispatch(targetHero, ref content);
				DuelBehavior.TryCacheDuelAfterLinesFromText(targetHero, ref content);
				DuelBehavior.TryCacheDuelStakeFromText(targetHero, ref content);
				VanillaIssueOfferBridge.ApplyIssueOfferTags(targetHero, ref content);
				LogNativeActionStep("hero_dispatch_after", targetHero, targetCharacter, content);
				int targetAgentIndex = resolvedTargetAgentIndex;
				bool nativeSceneTauntHandled = TryProcessNativeConversationSceneTauntTags(targetHero, targetCharacter, targetAgentIndex, ref content, out var nativeSceneTauntEscalated);
				if (nativeSceneTauntHandled && string.IsNullOrWhiteSpace(content))
				{
					content = BuildFallbackSceneTauntSpeech(nativeSceneTauntEscalated);
				}
				TryTriggerNativeConversationOpenLordsHallAction(targetHero, targetCharacter, targetAgentIndex, ref content);
				LogNativeActionStep("scene_taunt_lords_hall_after", targetHero, targetCharacter, content);
				LogNativeActionStep("noble_gathering_before", targetHero, targetCharacter, content);
				if (NobleGatheringBehavior.TryApplyNobleGatheringTagsForExternal(targetHero, ref content, out var nobleFacts, out var nobleNotifications))
				{
					if (nobleFacts != null)
					{
						foreach (string generatedFact in nobleFacts)
						{
							if (!string.IsNullOrWhiteSpace(generatedFact))
							{
								MyBehavior.AppendExternalDialogueHistory(targetHero, null, null, generatedFact);
							}
						}
						RecordGeneratedNpcAfefFactsForNativeConversation(targetHero, targetCharacter, nobleFacts);
					}
					foreach (string notification in nobleNotifications ?? new List<string>())
					{
						if (!string.IsNullOrWhiteSpace(notification))
						{
							InformationManager.DisplayMessage(new InformationMessage(notification, new Color(0.4f, 1f, 0.4f)));
						}
					}
				}
				LogNativeActionStep("noble_gathering_after", targetHero, targetCharacter, content);
				bool rewardBeforeHasVassalage = ContainsVassalageActionTagForLog(content);
				bool rewardBeforeHasKingdomAnnex = ContainsKingdomAnnexActionTagForLog(content);
				string rewardChainName = ResolveNativeConversationPostprocessChainName();
				Logger.Log("ShoutBehavior", "[NativeConversation] ApplyRewardTags start chain=" + rewardChainName + " target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " containsVASSALAGE=" + rewardBeforeHasVassalage + " containsKINGDOM_ANNEX=" + rewardBeforeHasKingdomAnnex);
				LogNativeActionStep("party_transfer_before", targetHero, targetCharacter, content);
				if (MyBehavior.TryApplyPartyTransferTagsForExternal(targetHero, targetCharacter, targetAgentIndex, ref content, out var generatedFacts, out var notifications))
				{
					if (generatedFacts != null)
					{
						foreach (string generatedFact in generatedFacts)
						{
							if (!string.IsNullOrWhiteSpace(generatedFact))
							{
								MyBehavior.AppendExternalDialogueHistory(targetHero, null, null, generatedFact);
							}
						}
						RecordGeneratedNpcAfefFactsForNativeConversation(targetHero, targetCharacter, generatedFacts);
					}
					if (notifications != null)
					{
						foreach (string notification in notifications)
						{
							if (!string.IsNullOrWhiteSpace(notification))
							{
								InformationManager.DisplayMessage(new InformationMessage(notification, new Color(0.4f, 1f, 0.4f)));
							}
						}
					}
				}
				LogNativeActionStep("party_transfer_after", targetHero, targetCharacter, content);
				RewardSystemBehavior rewardSystem = RewardSystemBehavior.Instance;
				LogNativeActionStep("reward_before", targetHero, targetCharacter, content);
				RewardSystemBehavior.RpItemIntroductionContext rpItemIntroductionContext = MayContainGeneratedRpItemReward(content)
					? CreateRpItemIntroductionContextForReward(
						targetHero,
						null,
						targetCharacter,
						targetAgentIndex,
						targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString(),
						latestPlayerText,
						content,
						includeNativeConversationSessionHistory: true)
					: null;
				rewardSystem?.ApplyRewardTags(targetHero, Hero.MainHero, ref content, rpItemIntroductionContext);
				RecordGeneratedNpcAfefFactsForNativeConversation(targetHero, targetCharacter, rewardSystem?.ConsumeLastGeneratedNpcFactLines());
				Logger.Log("ShoutBehavior", "[NativeConversation] ApplyRewardTags done chain=" + rewardChainName + " target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " beforeVASSALAGE=" + rewardBeforeHasVassalage + " afterVASSALAGE=" + ContainsVassalageActionTagForLog(content) + " beforeKINGDOM_ANNEX=" + rewardBeforeHasKingdomAnnex + " afterKINGDOM_ANNEX=" + ContainsKingdomAnnexActionTagForLog(content));
				LogNativeActionStep("reward_after", targetHero, targetCharacter, content);
				LogNativeActionStep("marriage_before", targetHero, targetCharacter, content);
				RomanceSystemBehavior.Instance?.ApplyMarriageTags(targetHero, Hero.MainHero, ref content, runPostprocessIfMissing: false);
				LogNativeActionStep("marriage_after", targetHero, targetCharacter, content);
				SexualConceptionBehavior.TryApplyIntimacyTags(targetHero, ref content, rewardChainName);
				LogNativeActionStep("meeting_duel_before", targetHero, targetCharacter, content);
				LordEncounterBehavior.TryProcessMeetingTauntAction(targetHero, ref content, out var escalatedToBattle);
				LordEncounterBehavior.TryConsumeMeetingPlayerReleaseTag(targetHero, ref content, out var meetingReleaseTriggered);
				if (meetingReleaseTriggered)
				{
					LordEncounterBehavior.ScheduleNativeConversationMeetingPlayerRelease(targetHero, "native_conversation_release_tag");
				}
				if (!escalatedToBattle && !meetingReleaseTriggered && !nativeSceneTauntEscalated && Regex.IsMatch(content, "\\[ACTION:DUEL\\]", RegexOptions.IgnoreCase))
				{
					content = Regex.Replace(content, "\\[ACTION:DUEL\\]", "", RegexOptions.IgnoreCase).Trim();
					DuelBehavior.PrepareDuel(targetHero, 3f);
				}
				LogNativeActionStep("meeting_duel_after", targetHero, targetCharacter, content);
			}
			else if (targetCharacter != null)
			{
				int agentIndex = resolvedTargetAgentIndex;
				RewardSystemBehavior rewardSystem = RewardSystemBehavior.Instance;
				bool isWildernessNonHeroPartyReward = false;
				NpcDataPacket nonHeroNpc = null;
				bool nonHeroJoinTagHandled = false;
				LogNativeActionStep("nonhero_scene_taunt_before", targetHero, targetCharacter, content);
				bool nonHeroSceneTauntHandled = TryProcessNativeConversationSceneTauntTags(targetHero, targetCharacter, agentIndex, ref content, out var nonHeroSceneTauntEscalated);
				if (nonHeroSceneTauntHandled && string.IsNullOrWhiteSpace(content))
				{
					content = BuildFallbackSceneTauntSpeech(nonHeroSceneTauntEscalated);
				}
				TryTriggerNativeConversationOpenLordsHallAction(targetHero, targetCharacter, agentIndex, ref content);
				LogNativeActionStep("nonhero_scene_taunt_after", targetHero, targetCharacter, content);
				LogNativeActionStep("nonhero_worldmap_before", targetHero, targetCharacter, content);
				worldMapResult = WorldMapPartyCommandBehavior.ProcessWorldMapOrderTagsDispatch(targetHero, targetCharacter, agentIndex, ref content);
				LogNativeActionStep("nonhero_worldmap_after", targetHero, targetCharacter, content);
				LogNativeActionStep("nonhero_party_transfer_before", targetHero, targetCharacter, content);
				if (MyBehavior.TryApplyPartyTransferTagsForExternal(targetHero, targetCharacter, agentIndex, ref content, out var nonHeroTransferFacts, out var nonHeroTransferNotifications))
				{
					RecordGeneratedNpcAfefFactsForNativeConversation(targetHero, targetCharacter, nonHeroTransferFacts);
					foreach (string notification in nonHeroTransferNotifications ?? new List<string>())
					{
						if (!string.IsNullOrWhiteSpace(notification))
						{
							InformationManager.DisplayMessage(new InformationMessage(notification, new Color(0.4f, 1f, 0.4f)));
						}
					}
				}
				LogNativeActionStep("nonhero_party_transfer_after", targetHero, targetCharacter, content);
				if (rewardSystem != null)
				{
					nonHeroNpc = BuildNativeConversationNpcData(targetHero, targetCharacter);
					nonHeroNpc.AgentIndex = agentIndex;
					LogNativeActionStep("nonhero_join_before", targetHero, targetCharacter, content);
					List<string> joinFacts;
					List<string> joinNotifications;
					bool nonHeroJoinHandled;
					if (expectedConversationToken != int.MinValue)
					{
						nonHeroJoinHandled = rewardSystem.TryApplyNonHeroJoinPlayerPartyTagForNativeConversationExternal(targetCharacter, agentIndex, nonHeroNpc.PromptGivenName, nonHeroNpc.PromptDisplayName, expectedConversationManager, expectedConversationToken, ref content, out joinFacts, out joinNotifications);
					}
					else
					{
						nonHeroJoinHandled = rewardSystem.TryApplyNonHeroJoinPlayerPartyTagForExternal(targetCharacter, agentIndex, nonHeroNpc.PromptGivenName, nonHeroNpc.PromptDisplayName, ref content, out joinFacts, out joinNotifications);
					}
					if (nonHeroJoinHandled)
					{
						nonHeroJoinTagHandled = true;
						RecordGeneratedNpcAfefFactsForNativeConversation(targetHero, targetCharacter, joinFacts);
						foreach (string notification in joinNotifications ?? new List<string>())
						{
							if (!string.IsNullOrWhiteSpace(notification))
							{
								InformationManager.DisplayMessage(new InformationMessage(notification, notification.IndexOf("失败", StringComparison.OrdinalIgnoreCase) >= 0 ? new Color(1f, 0.45f, 0.25f) : new Color(0.4f, 1f, 0.4f)));
							}
						}
					}
					LogNativeActionStep("nonhero_join_after", targetHero, targetCharacter, content);
				}
				PartyBase wildernessNonHeroParty = null;
				bool hasWildernessNonHeroParty = !nonHeroJoinTagHandled && TryResolveWildernessNonHeroRewardParty(targetHero, targetCharacter, agentIndex, out wildernessNonHeroParty);
				LogNativeActionStep("nonhero_reward_before", targetHero, targetCharacter, content);
				string npcName = (targetCharacter.Name?.ToString() ?? "对方部队").Trim();
				RewardSystemBehavior.RpItemIntroductionContext rpItemIntroductionContext = (rewardSystem == null
					|| !MayContainGeneratedRpItemReward(content))
					? null
					: CreateRpItemIntroductionContextForReward(
						null,
						nonHeroNpc,
						targetCharacter,
						agentIndex,
						npcName,
						latestPlayerText,
						content,
						includeNativeConversationSessionHistory: true);
				if (rewardSystem != null && hasWildernessNonHeroParty)
				{
					rewardSystem.ApplyPartyRewardTags(wildernessNonHeroParty, Hero.MainHero, npcName, targetCharacter, ref content, rpItemIntroductionContext);
					isWildernessNonHeroPartyReward = true;
				}
				else
				{
					rewardSystem?.ApplyMerchantRewardTags(targetCharacter, Hero.MainHero, ref content, rpItemIntroductionContext);
				}
				LogNativeActionStep("nonhero_reward_after", targetHero, targetCharacter, content);
				List<string> list = rewardSystem?.ConsumeLastGeneratedNpcFactLines();
				RecordGeneratedNpcAfefFactsForNativeConversation(targetHero, targetCharacter, list);
				if (isWildernessNonHeroPartyReward && list != null)
				{
					foreach (string item in list)
					{
						if (!string.IsNullOrWhiteSpace(item))
						{
							AppendWildernessNonHeroMemory(nonHeroNpc, targetHero, targetCharacter, agentIndex, null, null, item);
						}
					}
				}
				if (hasWildernessNonHeroParty)
				{
					LogNativeActionStep("nonhero_meeting_duel_before", targetHero, targetCharacter, content);
					LordEncounterBehavior.TryProcessMeetingTauntAction(null, wildernessNonHeroParty, ref content, out var nonHeroMeetingTauntEscalated);
					LordEncounterBehavior.TryConsumeMeetingPlayerReleaseTag(null, ref content, out var nonHeroMeetingReleaseTriggered);
					if (nonHeroMeetingReleaseTriggered)
					{
						LordEncounterBehavior.ScheduleNativeConversationMeetingPlayerRelease(null, "native_nonhero_conversation_release_tag");
					}
					if (!nonHeroMeetingTauntEscalated && !nonHeroMeetingReleaseTriggered && !nonHeroSceneTauntEscalated && Regex.IsMatch(content, "\\[ACTION:DUEL\\]", RegexOptions.IgnoreCase))
					{
						content = Regex.Replace(content, "\\[ACTION:DUEL\\]", "", RegexOptions.IgnoreCase).Trim();
						Agent duelAgent = (agentIndex >= 0) ? Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == agentIndex) : null;
						if (duelAgent != null)
						{
							DuelBehavior.PrepareDuel(duelAgent, 3f);
						}
						else
						{
							if (nonHeroNpc == null)
							{
								nonHeroNpc = BuildNativeConversationNpcData(targetHero, targetCharacter);
								nonHeroNpc.AgentIndex = agentIndex;
							}
							if (TryResolveWildernessNonHeroMemoryForExternal(nonHeroNpc, targetHero, targetCharacter, agentIndex, out var duelMemoryId, out var duelMemoryName))
							{
								DuelBehavior.SetPendingNonHeroDuelMemoryTarget(duelMemoryId, duelMemoryName);
							}
							DuelBehavior.PrepareDuel(targetCharacter, 3f);
						}
					}
					LogNativeActionStep("nonhero_meeting_duel_after", targetHero, targetCharacter, content);
				}
				else if (!nonHeroSceneTauntEscalated && Regex.IsMatch(content, "\\[ACTION:DUEL\\]", RegexOptions.IgnoreCase))
				{
					LogNativeActionStep("nonhero_duel_before", targetHero, targetCharacter, content);
					content = Regex.Replace(content, "\\[ACTION:DUEL\\]", "", RegexOptions.IgnoreCase).Trim();
					Agent duelAgent = (agentIndex >= 0) ? Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == agentIndex) : null;
					if (duelAgent != null)
					{
						DuelBehavior.PrepareDuel(duelAgent, 3f);
					}
					else
					{
						if (nonHeroNpc == null)
						{
							nonHeroNpc = BuildNativeConversationNpcData(targetHero, targetCharacter);
							nonHeroNpc.AgentIndex = agentIndex;
						}
						if (TryResolveWildernessNonHeroMemoryForExternal(nonHeroNpc, targetHero, targetCharacter, agentIndex, out var duelMemoryId, out var duelMemoryName))
						{
							DuelBehavior.SetPendingNonHeroDuelMemoryTarget(duelMemoryId, duelMemoryName);
						}
						DuelBehavior.PrepareDuel(targetCharacter, 3f);
					}
					LogNativeActionStep("nonhero_duel_after", targetHero, targetCharacter, content);
				}
			}
			LogNativeActionStep("npc_surrender_before", targetHero, targetCharacter, content);
			if (TryConsumeNativeConversationSiegeSurrenderTag(targetHero, targetCharacter, ref content, out var siegeSurrenderAgentIndex))
			{
				Logger.Log("SiegeSurrender", "Consumed native/direct conversation siege surrender tag. Target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agentIndex=" + siegeSurrenderAgentIndex);
			}
			if (TryConsumeNativeConversationNpcSurrenderTag(targetHero, targetCharacter, ref content, out var surrenderAgentIndex))
			{
				QueueNativeConversationNpcSurrender(targetHero, targetCharacter, surrenderAgentIndex, "native_conversation_npc_surrender_tag");
			}
			LogNativeActionStep("done", targetHero, targetCharacter, content);
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] action tag handling failed: " + ex.Message);
		}
		return worldMapResult;
	}

	private static void LogNativeActionStep(string step, Hero targetHero, CharacterObject targetCharacter, string content)
	{
		try
		{
			Logger.Log("Logic", "[NativeActionStep] step=" + (step ?? "") + " target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " contentLen=" + ((content ?? "").Length));
		}
		catch
		{
		}
	}

	private static MyBehavior.ShoutPromptContext CreateEmptyNativeConversationPromptContext()
	{
		return new MyBehavior.ShoutPromptContext
		{
			Extras = "",
			EntityPostprocessContext = "",
			PreprocessRuleIds = new List<string>(),
			UseDuelContext = false,
			UseRewardContext = false,
			IsLoanContext = false,
			IsQualified = true
		};
	}

	private static string BuildNativeConversationPreprocessUnavailableText()
	{
		return "（API请求失败: 原生对话前处理超时或上一轮仍在运行，请稍后重试）";
	}

	public static bool IsNativeConversationPreprocessUnavailableTextForExternal(string text)
	{
		string value = (text ?? "").Replace("\r", "").Trim();
		if (string.IsNullOrWhiteSpace(value))
		{
			return false;
		}
		return value.StartsWith("（API请求失败", StringComparison.Ordinal)
			&& value.IndexOf("原生对话前处理", StringComparison.Ordinal) >= 0;
	}

	private bool TryAcquireNativeConversationBackgroundPreprocessSlot(long requestId, long runtimeGeneration, string target, int targetAgentIndex)
	{
		for (int attempt = 0; attempt < 2; attempt++)
		{
			long activeRequestId = Interlocked.Read(ref _nativeConversationBackgroundPreprocessActiveRequestId);
			if (activeRequestId == 0L)
			{
				if (Interlocked.CompareExchange(ref _nativeConversationBackgroundPreprocessActiveRequestId, requestId, 0L) == 0L)
				{
					Interlocked.Exchange(ref _nativeConversationBackgroundPreprocessActiveGeneration, runtimeGeneration);
					return true;
				}
				continue;
			}
			long activeGeneration = Interlocked.Read(ref _nativeConversationBackgroundPreprocessActiveGeneration);
			long currentGeneration = SaveRuntimeGuard.CurrentGeneration;
			if (activeGeneration > 0L && activeGeneration != currentGeneration)
			{
				if (Interlocked.CompareExchange(ref _nativeConversationBackgroundPreprocessActiveRequestId, requestId, activeRequestId) == activeRequestId)
				{
					Interlocked.Exchange(ref _nativeConversationBackgroundPreprocessActiveGeneration, runtimeGeneration);
					Logger.Log("ShoutBehavior", "[NativeConversation] replaced stale preprocess owner target=" + target + " agent=" + targetAgentIndex + " oldRequest=" + activeRequestId + " oldGeneration=" + activeGeneration + " currentGeneration=" + currentGeneration + " newRequest=" + requestId);
					FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_stale_owner_replaced", "target=" + target + " agent=" + targetAgentIndex + " oldRequest=" + activeRequestId + " oldGeneration=" + activeGeneration + " currentGeneration=" + currentGeneration + " newRequest=" + requestId, immediate: true);
					return true;
				}
			}
		}
		long busyRequestId = Interlocked.Read(ref _nativeConversationBackgroundPreprocessActiveRequestId);
		long busyGeneration = Interlocked.Read(ref _nativeConversationBackgroundPreprocessActiveGeneration);
		Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background busy target=" + target + " agent=" + targetAgentIndex + " activeRequest=" + busyRequestId + " activeGeneration=" + busyGeneration + " currentGeneration=" + SaveRuntimeGuard.CurrentGeneration);
		FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_busy", "target=" + target + " agent=" + targetAgentIndex + " activeRequest=" + busyRequestId + " activeGeneration=" + busyGeneration, immediate: true);
		return false;
	}

	private Task<MyBehavior.ShoutPromptContext> RunNativeConversationBackgroundPreprocessAsync(string targetLog, int targetAgentIndex, long runtimeGeneration, Func<MyBehavior.ShoutPromptContext> func)
	{
		string target = string.IsNullOrWhiteSpace(targetLog) ? "unknown" : targetLog.Trim();
		long requestId = Interlocked.Increment(ref _nativeConversationBackgroundPreprocessSequence);
		if (func == null)
		{
			return Task.FromResult(CreateEmptyNativeConversationPromptContext());
		}
		if (!TryAcquireNativeConversationBackgroundPreprocessSlot(requestId, runtimeGeneration, target, targetAgentIndex))
		{
			return Task.FromResult<MyBehavior.ShoutPromptContext>(null);
		}
		return Task.Factory.StartNew(delegate
		{
			ThreadPriority previousPriority = Thread.CurrentThread.Priority;
			Stopwatch sw = Stopwatch.StartNew();
			try
			{
				try
				{
					Thread.CurrentThread.Priority = ThreadPriority.BelowNormal;
				}
				catch
				{
				}
				Logger.Log("Logic", "[NativePerf] preprocess_context_background_start target=" + target + " agent=" + targetAgentIndex + " request=" + requestId + " callerThread=" + Thread.CurrentThread.ManagedThreadId + " knowledge=" + AIConfigHandler.KnowledgeRetrievalEnabled + " semanticFirst=" + AIConfigHandler.KnowledgeSemanticFirst + " topK=" + AIConfigHandler.KnowledgeSemanticTopK);
				FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_start", "target=" + target + " agent=" + targetAgentIndex + " request=" + requestId + " thread=" + Thread.CurrentThread.ManagedThreadId + " onnx=True", immediate: true);
				if (SaveRuntimeGuard.IsStale(runtimeGeneration, "native_conversation_preprocess_background_before_run"))
				{
					return CreateEmptyNativeConversationPromptContext();
				}
				using (FreezeWatchdog.Scope("NativeConversation.preprocess_context.background"))
				{
					MyBehavior.ShoutPromptContext ctx = func() ?? CreateEmptyNativeConversationPromptContext();
					sw.Stop();
					Logger.Log("Logic", "[NativePerf] preprocess_context_background_done target=" + target + " agent=" + targetAgentIndex + " request=" + requestId + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " stale=" + SaveRuntimeGuard.IsStale(runtimeGeneration, "native_conversation_preprocess_background_after_run") + " hits=" + ((ctx.PreprocessRuleIds == null || ctx.PreprocessRuleIds.Count == 0) ? "(none)" : string.Join(",", ctx.PreprocessRuleIds)) + " extrasLen=" + ((ctx.Extras ?? "").Length));
					FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_done", "target=" + target + " agent=" + targetAgentIndex + " request=" + requestId + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " extrasLen=" + ((ctx.Extras ?? "").Length), immediate: true);
					return ctx;
				}
			}
			catch (PreprocessFormatException)
			{
				sw.Stop();
				FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_format_exception", "target=" + target + " agent=" + targetAgentIndex + " request=" + requestId + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2), immediate: true);
				throw;
			}
			catch (Exception ex)
			{
				sw.Stop();
				Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background failed target=" + target + " agent=" + targetAgentIndex + " request=" + requestId + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2) + " error=" + ex.Message);
				FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_exception", ex.GetType().Name + ": " + ex.Message + " target=" + target + " agent=" + targetAgentIndex + " request=" + requestId, immediate: true);
				return CreateEmptyNativeConversationPromptContext();
			}
			finally
			{
				if (Interlocked.CompareExchange(ref _nativeConversationBackgroundPreprocessActiveRequestId, 0L, requestId) == requestId)
				{
					Interlocked.Exchange(ref _nativeConversationBackgroundPreprocessActiveGeneration, 0L);
				}
				try
				{
					Thread.CurrentThread.Priority = previousPriority;
				}
				catch
				{
				}
			}
		}, CancellationToken.None, TaskCreationOptions.LongRunning, TaskScheduler.Default);
	}

	private static async Task<MyBehavior.ShoutPromptContext> AwaitNativeConversationBackgroundPreprocessAsync(Task<MyBehavior.ShoutPromptContext> task, string targetLog, int targetAgentIndex, long runtimeGeneration)
	{
		string target = string.IsNullOrWhiteSpace(targetLog) ? "unknown" : targetLog.Trim();
		if (task == null)
		{
			return null;
		}
		try
		{
			Task completed = await Task.WhenAny(task, Task.Delay(NativeConversationBackgroundPreprocessTimeoutMs)).ConfigureAwait(false);
			if (ReferenceEquals(completed, task))
			{
				return await task.ConfigureAwait(false);
			}
			long timeoutCount = Interlocked.Increment(ref _nativeConversationBackgroundPreprocessTimeoutCount);
			Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background timeout target=" + target + " agent=" + targetAgentIndex + " timeoutMs=" + NativeConversationBackgroundPreprocessTimeoutMs + " taskStatus=" + task.Status + " runtimeGeneration=" + runtimeGeneration + " currentGeneration=" + SaveRuntimeGuard.CurrentGeneration + " timeoutCount=" + timeoutCount);
			FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_timeout", "target=" + target + " agent=" + targetAgentIndex + " timeoutMs=" + NativeConversationBackgroundPreprocessTimeoutMs + " status=" + task.Status + " timeoutCount=" + timeoutCount, immediate: true);
			ObserveNativeConversationBackgroundPreprocessLateCompletion(task, target, targetAgentIndex, timeoutCount);
			return null;
		}
		catch (PreprocessFormatException)
		{
			throw;
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background await failed target=" + target + " agent=" + targetAgentIndex + " error=" + ex.Message);
			FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_await_exception", ex.GetType().Name + ": " + ex.Message + " target=" + target + " agent=" + targetAgentIndex, immediate: true);
			return CreateEmptyNativeConversationPromptContext();
		}
	}

	private static void ObserveNativeConversationBackgroundPreprocessLateCompletion(Task<MyBehavior.ShoutPromptContext> task, string target, int targetAgentIndex, long timeoutCount)
	{
		try
		{
			task.ContinueWith(delegate(Task<MyBehavior.ShoutPromptContext> completedTask)
			{
				try
				{
					if (completedTask.IsCanceled)
					{
						Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background late canceled target=" + target + " agent=" + targetAgentIndex + " timeoutCount=" + timeoutCount);
						FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_late_canceled", "target=" + target + " agent=" + targetAgentIndex + " timeoutCount=" + timeoutCount, immediate: true);
						return;
					}
					if (completedTask.IsFaulted)
					{
						Exception lateEx = completedTask.Exception?.GetBaseException();
						Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background late fault target=" + target + " agent=" + targetAgentIndex + " timeoutCount=" + timeoutCount + " error=" + (lateEx?.Message ?? "unknown"));
						FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_late_fault", (lateEx?.GetType().Name ?? "Exception") + ": " + (lateEx?.Message ?? "") + " target=" + target + " agent=" + targetAgentIndex + " timeoutCount=" + timeoutCount, immediate: true);
						return;
					}
					MyBehavior.ShoutPromptContext ctx = completedTask.Result;
					Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background late complete target=" + target + " agent=" + targetAgentIndex + " timeoutCount=" + timeoutCount + " hits=" + ((ctx?.PreprocessRuleIds == null || ctx.PreprocessRuleIds.Count == 0) ? "(none)" : string.Join(",", ctx.PreprocessRuleIds)) + " extrasLen=" + ((ctx?.Extras ?? "").Length));
					FreezeWatchdog.Mark("NativeConversation.preprocess_context_background_late_complete", "target=" + target + " agent=" + targetAgentIndex + " timeoutCount=" + timeoutCount + " extrasLen=" + ((ctx?.Extras ?? "").Length), immediate: true);
				}
				catch (Exception ex)
				{
					Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background late observer failed target=" + target + " agent=" + targetAgentIndex + " error=" + ex.Message);
				}
			}, CancellationToken.None, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] preprocess background late observer registration failed target=" + target + " agent=" + targetAgentIndex + " error=" + ex.Message);
		}
	}

	private Task<T> RunNativeConversationMainThreadFuncAsync<T>(string operationName, string targetLog, int targetAgentIndex, Func<T> func, T fallback)
	{
		if (func == null)
		{
			return Task.FromResult(fallback);
		}
		string op = string.IsNullOrWhiteSpace(operationName) ? "operation" : operationName.Trim();
		string target = string.IsNullOrWhiteSpace(targetLog) ? "unknown" : targetLog.Trim();
		if (IsBannerlordMainThreadForNativeActions())
		{
			Stopwatch directSw = Stopwatch.StartNew();
			FreezeWatchdog.Mark("NativeConversation." + op + "_direct_start", "target=" + target + " agent=" + targetAgentIndex, immediate: true);
			try
			{
				T direct = func();
				directSw.Stop();
				Logger.Log("Logic", "[NativePerf] " + op + "_mainthread_direct target=" + target + " agent=" + targetAgentIndex + " ms=" + Math.Round(directSw.Elapsed.TotalMilliseconds, 2));
				FreezeWatchdog.Mark("NativeConversation." + op + "_direct_done", "target=" + target + " agent=" + targetAgentIndex + " ms=" + Math.Round(directSw.Elapsed.TotalMilliseconds, 2), immediate: true);
				return Task.FromResult(direct);
			}
			catch (Exception ex)
			{
				directSw.Stop();
				Logger.Log("ShoutBehavior", "[NativeConversation] " + op + " direct failed target=" + target + " agent=" + targetAgentIndex + " ms=" + Math.Round(directSw.Elapsed.TotalMilliseconds, 2) + " error=" + ex.Message);
				FreezeWatchdog.Mark("NativeConversation." + op + "_direct_exception", ex.GetType().Name + ": " + ex.Message + " target=" + target + " agent=" + targetAgentIndex, immediate: true);
				if (ex is PreprocessFormatException)
				{
					return Task.FromException<T>(ex);
				}
				return Task.FromResult(fallback);
			}
		}
		TaskCompletionSource<T> tcs = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);
		bool cancelledBeforeRun = false;
		try
		{
			_mainThreadActions.Enqueue(delegate
			{
				if (cancelledBeforeRun)
				{
					FreezeWatchdog.Mark("NativeConversation." + op + "_mainthread_skipped", "target=" + target + " agent=" + targetAgentIndex, immediate: true);
					return;
				}
				Stopwatch actionSw = Stopwatch.StartNew();
				try
				{
					Logger.Log("Logic", "[NativePerf] " + op + "_mainthread_start target=" + target + " agent=" + targetAgentIndex);
					FreezeWatchdog.Mark("NativeConversation." + op + "_mainthread_start", "target=" + target + " agent=" + targetAgentIndex, immediate: true);
					T result = func();
					actionSw.Stop();
					Logger.Log("Logic", "[NativePerf] " + op + "_mainthread_done target=" + target + " agent=" + targetAgentIndex + " ms=" + Math.Round(actionSw.Elapsed.TotalMilliseconds, 2));
					FreezeWatchdog.Mark("NativeConversation." + op + "_mainthread_done", "target=" + target + " agent=" + targetAgentIndex + " ms=" + Math.Round(actionSw.Elapsed.TotalMilliseconds, 2), immediate: true);
					tcs.TrySetResult(result);
				}
				catch (Exception ex)
				{
					actionSw.Stop();
					Logger.Log("ShoutBehavior", "[NativeConversation] " + op + " main-thread failed target=" + target + " agent=" + targetAgentIndex + " ms=" + Math.Round(actionSw.Elapsed.TotalMilliseconds, 2) + " error=" + ex.Message);
					FreezeWatchdog.Mark("NativeConversation." + op + "_mainthread_exception", ex.GetType().Name + ": " + ex.Message + " target=" + target + " agent=" + targetAgentIndex, immediate: true);
					if (ex is PreprocessFormatException)
					{
						tcs.TrySetException(ex);
						return;
					}
					tcs.TrySetResult(fallback);
				}
			});
			Logger.Log("Logic", "[NativePerf] " + op + "_queued target=" + target + " agent=" + targetAgentIndex + " callerThread=" + Thread.CurrentThread.ManagedThreadId + " pending=" + _mainThreadActions.Count);
			FreezeWatchdog.Mark("NativeConversation." + op + "_queued", "target=" + target + " agent=" + targetAgentIndex + " callerThread=" + Thread.CurrentThread.ManagedThreadId + " pending=" + _mainThreadActions.Count, immediate: true);
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] queue " + op + " failed target=" + target + " agent=" + targetAgentIndex + " error=" + ex.Message);
			FreezeWatchdog.Mark("NativeConversation." + op + "_queue_exception", ex.GetType().Name + ": " + ex.Message + " target=" + target + " agent=" + targetAgentIndex, immediate: true);
			tcs.TrySetResult(fallback);
		}
		return AwaitNativeConversationMainThreadFuncAsync(tcs.Task, op, target, targetAgentIndex, () => cancelledBeforeRun = true, fallback);
	}

	private static async Task<T> AwaitNativeConversationMainThreadFuncAsync<T>(Task<T> task, string operationName, string targetLog, int targetAgentIndex, Action onTimeout, T fallback)
	{
		try
		{
			Task completed = await Task.WhenAny(task, Task.Delay(NativeConversationMainThreadPreprocessTimeoutMs)).ConfigureAwait(false);
			if (completed == task)
			{
				return await task.ConfigureAwait(false);
			}
			try
			{
				onTimeout?.Invoke();
			}
			catch
			{
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] " + operationName + " main-thread queue timeout target=" + targetLog + " agent=" + targetAgentIndex + " timeoutMs=" + NativeConversationMainThreadPreprocessTimeoutMs);
			FreezeWatchdog.Mark("NativeConversation." + operationName + "_mainthread_timeout", "target=" + targetLog + " agent=" + targetAgentIndex + " timeoutMs=" + NativeConversationMainThreadPreprocessTimeoutMs, immediate: true);
			return fallback;
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] " + operationName + " main-thread await failed target=" + targetLog + " agent=" + targetAgentIndex + " error=" + ex.Message);
			FreezeWatchdog.Mark("NativeConversation." + operationName + "_mainthread_await_exception", ex.GetType().Name + ": " + ex.Message + " target=" + targetLog + " agent=" + targetAgentIndex, immediate: true);
			return fallback;
		}
	}

	private sealed class NativeConversationGameActionResult
	{
		public string Content;
		public WorldMapPartyCommandBehavior.WorldMapOrderApplyResult WorldMapResult;
		public bool ResponseDiscarded;
	}

	private Task<NativeConversationGameActionResult> ApplyNativeConversationGameActionsOnMainThreadAsync(Hero targetHero, CharacterObject targetCharacter, NpcDataPacket npc, List<NpcDataPacket> allNpcData, List<SceneSummonPromptTarget> sceneSummonTargets, List<SceneGuidePromptTarget> sceneGuideTargets, string content, string npcName, int targetAgentIndex, string playerText, ConversationManager expectedConversationManager, int expectedConversationToken)
	{
		string initial = content ?? "";
		string targetLog = targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? npc?.Name ?? "unknown";
		if (IsBannerlordMainThreadForNativeActions())
		{
			Stopwatch directSw = Stopwatch.StartNew();
			FreezeWatchdog.Mark("NativeConversation.game_actions_direct_start", "target=" + targetLog + " agent=" + targetAgentIndex, immediate: true);
			NativeConversationGameActionResult direct = ApplyNativeConversationGameActionsCore(targetHero, targetCharacter, npc, allNpcData, sceneSummonTargets, sceneGuideTargets, initial, playerText, expectedConversationManager, expectedConversationToken);
			directSw.Stop();
			Logger.Log("Logic", "[NativePerf] game_actions_mainthread_direct target=" + targetLog + " agent=" + targetAgentIndex + " ms=" + Math.Round(directSw.Elapsed.TotalMilliseconds, 2));
			FreezeWatchdog.Mark("NativeConversation.game_actions_direct_done", "target=" + targetLog + " agent=" + targetAgentIndex + " ms=" + Math.Round(directSw.Elapsed.TotalMilliseconds, 2), immediate: true);
			return Task.FromResult(direct);
		}
		TaskCompletionSource<NativeConversationGameActionResult> tcs = new TaskCompletionSource<NativeConversationGameActionResult>(TaskCreationOptions.RunContinuationsAsynchronously);
		try
		{
			_mainThreadActions.Enqueue(delegate
			{
				Stopwatch actionSw = Stopwatch.StartNew();
				NativeConversationGameActionResult result = new NativeConversationGameActionResult { Content = initial, WorldMapResult = new WorldMapPartyCommandBehavior.WorldMapOrderApplyResult() };
				try
				{
					Logger.Log("Logic", "[NativePerf] game_actions_mainthread_start target=" + targetLog + " agent=" + targetAgentIndex);
					FreezeWatchdog.Mark("NativeConversation.game_actions_mainthread_start", "target=" + targetLog + " agent=" + targetAgentIndex, immediate: true);
					result = ApplyNativeConversationGameActionsCore(targetHero, targetCharacter, npc, allNpcData, sceneSummonTargets, sceneGuideTargets, result.Content, playerText, expectedConversationManager, expectedConversationToken);
					actionSw.Stop();
					Logger.Log("Logic", "[NativePerf] game_actions_mainthread_done target=" + targetLog + " agent=" + targetAgentIndex + " ms=" + Math.Round(actionSw.Elapsed.TotalMilliseconds, 2) + " resultLen=" + ((result?.Content ?? "").Length));
					FreezeWatchdog.Mark("NativeConversation.game_actions_mainthread_done", "target=" + targetLog + " agent=" + targetAgentIndex + " ms=" + Math.Round(actionSw.Elapsed.TotalMilliseconds, 2) + " resultLen=" + ((result?.Content ?? "").Length), immediate: true);
					tcs.TrySetResult(result);
				}
				catch (Exception ex)
				{
					actionSw.Stop();
					Logger.Log("ShoutBehavior", "[NativeConversation] main-thread game actions failed target=" + targetLog + " agent=" + targetAgentIndex + " ms=" + Math.Round(actionSw.Elapsed.TotalMilliseconds, 2) + " error=" + ex.Message);
					FreezeWatchdog.Mark("NativeConversation.game_actions_mainthread_exception", ex.GetType().Name + ": " + ex.Message + " target=" + targetLog + " agent=" + targetAgentIndex, immediate: true);
					tcs.TrySetResult(result);
				}
			});
			Logger.Log("Logic", "[NativePerf] game_actions_queued target=" + targetLog + " agent=" + targetAgentIndex + " callerThread=" + Thread.CurrentThread.ManagedThreadId);
			FreezeWatchdog.Mark("NativeConversation.game_actions_queued", "target=" + targetLog + " agent=" + targetAgentIndex + " callerThread=" + Thread.CurrentThread.ManagedThreadId, immediate: true);
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] queue game actions failed target=" + targetLog + " agent=" + targetAgentIndex + " error=" + ex.Message);
			FreezeWatchdog.Mark("NativeConversation.game_actions_queue_exception", ex.GetType().Name + ": " + ex.Message + " target=" + targetLog + " agent=" + targetAgentIndex, immediate: true);
			tcs.TrySetResult(new NativeConversationGameActionResult { Content = initial, WorldMapResult = new WorldMapPartyCommandBehavior.WorldMapOrderApplyResult() });
		}
		return tcs.Task;
	}

	private NativeConversationGameActionResult ApplyNativeConversationGameActionsCore(Hero targetHero, CharacterObject targetCharacter, NpcDataPacket npc, List<NpcDataPacket> allNpcData, List<SceneSummonPromptTarget> sceneSummonTargets, List<SceneGuidePromptTarget> sceneGuideTargets, string content, string playerText, ConversationManager expectedConversationManager, int expectedConversationToken)
	{
		string result = content ?? "";
		int targetAgentIndex = npc?.AgentIndex ?? (-1);
		if (TryTriggerNativeConversationOpenLordsHallAction(targetHero, targetCharacter, targetAgentIndex, ref result))
		{
			return new NativeConversationGameActionResult
			{
				Content = result ?? "",
				WorldMapResult = new WorldMapPartyCommandBehavior.WorldMapOrderApplyResult()
			};
		}
		if (!IsNativeConversationResponseTargetAvailableForActionDispatch(targetAgentIndex, targetHero, targetCharacter, out string unavailableReason))
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] dropped queued postprocess actions because target is unavailable target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npc?.Name ?? "unknown") + " agentIndex=" + targetAgentIndex + " reason=" + unavailableReason);
			return new NativeConversationGameActionResult
			{
				Content = "",
				WorldMapResult = new WorldMapPartyCommandBehavior.WorldMapOrderApplyResult(),
				ResponseDiscarded = true
			};
		}
		if (targetHero != null)
		{
			MyBehavior.ApplyPostprocessMoodFromSceneHeroResponseExternal(targetHero, ref result);
		}
		else
		{
			MyBehavior.ApplyPostprocessMoodFromSceneUnnamedResponseExternal(npc?.UnnamedKey, npc?.Name, ref result);
		}
		TryQueueNativeSceneMechanismActionAfterConversationExit(npc, allNpcData, sceneSummonTargets, sceneGuideTargets, ref result);
		WorldMapPartyCommandBehavior.WorldMapOrderApplyResult worldMapResult = ApplyNativeConversationActionTags(targetHero, targetCharacter, ref result, targetAgentIndex, playerText, expectedConversationManager, expectedConversationToken);
		return new NativeConversationGameActionResult { Content = result ?? "", WorldMapResult = worldMapResult };
	}

	private static bool IsBannerlordMainThreadForNativeActions()
	{
		try
		{
			return TWParallel.IsMainThread();
		}
		catch
		{
			return false;
		}
	}

	private static bool TryConsumeNativeConversationSiegeSurrenderTag(Hero targetHero, CharacterObject targetCharacter, ref string content, out int targetAgentIndex)
	{
		targetAgentIndex = -1;
		string pattern = Regex.Escape(SiegeSurrenderActionTag);
		if (string.IsNullOrWhiteSpace(content) || !Regex.IsMatch(content, pattern, RegexOptions.IgnoreCase))
		{
			return false;
		}
		targetAgentIndex = TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
		bool validContext = TryResolveNativeConversationSiegeSurrenderContext(targetHero, targetCharacter, targetAgentIndex, out var settlement, out var side, out var sideLabel);
		if (!validContext)
		{
			return false;
		}
		content = Regex.Replace(content, pattern, "", RegexOptions.IgnoreCase).Trim();
		Logger.Log("SiegeSurrender", "Accepted native/direct conversation siege surrender tag. Target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " settlement=" + (settlement?.StringId ?? "") + " side=" + (sideLabel ?? side.ToString()) + " agentIndex=" + targetAgentIndex);
		return true;
	}

	private static bool TryConsumeNativeConversationNpcSurrenderTag(Hero targetHero, CharacterObject targetCharacter, ref string content, out int targetAgentIndex)
	{
		targetAgentIndex = -1;
		if (string.IsNullOrWhiteSpace(content) || !Regex.IsMatch(content, "\\[ACTION:NPC_SURRENDER\\]", RegexOptions.IgnoreCase))
		{
			return false;
		}
		targetAgentIndex = TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
		if (TryResolveNativeConversationSiegeSurrenderContext(targetHero, targetCharacter, targetAgentIndex, out var settlement, out var side, out var sideLabel))
		{
			content = Regex.Replace(content, "\\[ACTION:NPC_SURRENDER\\]", "", RegexOptions.IgnoreCase).Trim();
			Logger.Log("NpcSurrender", "Hidden native/direct conversation NPC surrender tag in siege context. Target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " settlement=" + (settlement?.StringId ?? "") + " side=" + (sideLabel ?? side.ToString()) + " agentIndex=" + targetAgentIndex);
			return false;
		}
		content = Regex.Replace(content, "\\[ACTION:NPC_SURRENDER\\]", "", RegexOptions.IgnoreCase).Trim();
		return true;
	}

	private void QueueNativeConversationNpcSurrender(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, string reason)
	{
		string targetId = targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown";
		try
		{
			_mainThreadActions.Enqueue(delegate
			{
				LordEncounterBehavior.TryExecuteNpcSurrenderFromNativeConversation(targetHero, targetCharacter, targetAgentIndex, reason ?? "native_conversation_npc_surrender_tag");
			});
			Logger.Log("NpcSurrender", "Queued native/direct conversation NPC surrender. Target=" + targetId + " agentIndex=" + targetAgentIndex + " reason=" + (reason ?? "N/A"));
			TryDrainNativeConversationQueuedActions("npc_surrender_queued");
		}
		catch (Exception ex)
		{
			Logger.Log("NpcSurrender", "Queue native/direct conversation NPC surrender failed. Target=" + targetId + " error=" + ex.Message);
		}
	}

	private void TryDrainNativeConversationQueuedActions(string reason)
	{
		try
		{
			int pending = _mainThreadActions.Count;
			if (pending <= 0)
			{
				return;
			}
			Logger.Log("ShoutBehavior", "[NativeConversation] draining queued actions. Pending=" + pending + " missionActive=" + (Mission.Current != null) + " reason=" + (reason ?? "N/A"));
			if (!IsBannerlordMainThreadForNativeActions())
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] skip immediate drain from background thread. Pending=" + pending + " reason=" + (reason ?? "N/A") + " thread=" + Thread.CurrentThread.ManagedThreadId);
				return;
			}
			DrainMainThreadActionsForMissionTick();
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] drain queued actions failed. Reason=" + (reason ?? "N/A") + " error=" + ex.Message);
		}
	}

	private void RecordGeneratedNpcAfefFactsForNativeConversation(Hero targetHero, CharacterObject targetCharacter, IEnumerable<string> factLines)
	{
		if (factLines == null)
		{
			return;
		}
		targetHero ??= targetCharacter?.HeroObject;
		targetCharacter ??= targetHero?.CharacterObject;
		string npcName = (targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString() ?? "NPC").Trim();
		if (string.IsNullOrWhiteSpace(npcName))
		{
			npcName = "NPC";
		}
		int targetAgentIndex = TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
		NpcDataPacket targetNpc = BuildNativeConversationNpcData(targetHero, targetCharacter);
		targetNpc.AgentIndex = targetAgentIndex;
		string nativeKey = BuildNativeConversationHistoryKey(targetHero, targetCharacter, npcName, targetAgentIndex, targetNpc);
		foreach (string rawFact in factLines)
		{
			string fact = NormalizeNativeConversationFactLineForPrompt(rawFact, "NPC");
			if (string.IsNullOrWhiteSpace(fact))
			{
				continue;
			}
			try
			{
				AppendNativeConversationSessionHistory(targetHero, targetCharacter, npcName, "系统", fact, "fact", targetAgentIndex: targetAgentIndex, npc: targetNpc);
				if (targetAgentIndex >= 0)
				{
					QueuePendingCurrentAfefFactForAgent(targetAgentIndex, fact);
				}
				if (!string.IsNullOrWhiteSpace(nativeKey))
				{
					QueuePendingCurrentNativeAfefFactForKey(nativeKey, fact);
				}
				Logger.Log("NativeConversationTrade", "recorded generated NPC AFEF fact target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName) + " fact=" + fact.Replace("\r", "\\r").Replace("\n", "\\n"));
			}
			catch (Exception ex)
			{
				Logger.Log("NativeConversationTrade", "[WARN] Failed to record generated NPC AFEF fact: " + ex.Message);
			}
		}
	}

	private static bool IsNativeConversationWorldMapContext()
	{
		try
		{
			if (Mission.Current != null)
			{
				return false;
			}
		}
		catch
		{
		}
		try
		{
			if (Game.Current?.GameStateManager?.ActiveState is MissionState)
			{
				return false;
			}
		}
		catch
		{
		}
		return true;
	}

	private static bool TryProcessNativeConversationRawMeetingTauntTags(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, ref string content, out bool escalatedToBattle)
	{
		escalatedToBattle = false;
		if (!AfGcczShoutBridge.ShouldAllowAfRuleForCurrentStage(TownAfRuleRoutingPolicy.MeetingTauntRuleId, targetAgentIndex))
		{
			StripBlockedTownTauntTags(ref content);
			return false;
		}
		if (string.IsNullOrWhiteSpace(content) || !IsNativeConversationWorldMapContext())
		{
			return false;
		}
		try
		{
			if (!MeetingSceneShoutTauntTagRegex.IsMatch(content))
			{
				return false;
			}
			PartyBase nonHeroParty = null;
			if (targetHero == null)
			{
				TryResolveNativeConversationMeetingTauntParty(targetHero, targetCharacter, targetAgentIndex, out nonHeroParty);
			}
			if (targetHero == null && nonHeroParty == null)
			{
				return false;
			}
			bool result = LordEncounterBehavior.TryProcessMeetingTauntAction(targetHero, nonHeroParty, ref content, out escalatedToBattle);
			if (result)
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] raw meeting taunt tag consumed before postprocess. target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? nonHeroParty?.Name?.ToString() ?? "") + " escalated=" + escalatedToBattle);
			}
			return result;
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] raw meeting taunt handling failed: " + ex.Message);
			return false;
		}
	}

	private static bool TryProcessNativeConversationSceneTauntTags(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, ref string content, out bool escalatedToFight)
	{
		escalatedToFight = false;
		if (!AfGcczShoutBridge.ShouldAllowAfRuleForCurrentStage(TownAfRuleRoutingPolicy.MeetingTauntRuleId, targetAgentIndex))
		{
			StripBlockedTownTauntTags(ref content);
			return false;
		}
		if (string.IsNullOrWhiteSpace(content))
		{
			return false;
		}
		try
		{
			if (SceneTauntBehavior.HasSceneTauntFightTagForExternal(content))
			{
				if (SceneTauntBehavior.TryConsumeSceneTauntTagsForDelayedFightExternal(targetHero, targetCharacter, targetAgentIndex, ref content, out var hadWarnTag, out var hadFightTag, out var targetKey))
				{
					bool scheduled = hadFightTag && CurrentInstance?.ScheduleNativeSceneTauntFightAfterDelay(targetHero, targetCharacter, targetAgentIndex, targetKey, "native_conversation_scene_taunt_fight_tag") == true;
					escalatedToFight = scheduled;
					Logger.Log("ShoutBehavior", "[NativeConversation] scene taunt tag consumed for delayed fight. target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agentIndex=" + targetAgentIndex + " warn=" + hadWarnTag + " fight=" + hadFightTag + " scheduled=" + scheduled);
					return true;
				}
			}
			bool result = SceneTauntBehavior.TryProcessSceneTauntAction(targetHero, targetCharacter, targetAgentIndex, ref content, out escalatedToFight);
			if (result)
			{
				Logger.Log("ShoutBehavior", "[NativeConversation] scene taunt tag consumed. target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agentIndex=" + targetAgentIndex + " escalated=" + escalatedToFight);
				if (escalatedToFight)
				{
					CloseNativeConversationForSceneMechanism("native_scene_taunt_fight");
				}
			}
			return result;
		}
		catch (Exception ex)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] scene taunt handling failed: " + ex.Message);
			return false;
		}
	}

	private static void StripBlockedTownTauntTags(ref string content)
	{
		if (string.IsNullOrWhiteSpace(content))
		{
			return;
		}

		content = MeetingSceneShoutTauntTagRegex.Replace(content, "");
		content = Regex.Replace(content, "\\[ACTION:SCENE_TAUNT_(?:WARN|FIGHT)\\]", "", RegexOptions.IgnoreCase).Trim();
	}

	private List<string> BuildPreprocessExcludedRuleIdsForCurrentInteraction(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, bool hasAnyHero, List<SceneSummonPromptTarget> sceneSummonTargets = null, List<SceneGuidePromptTarget> sceneGuideTargets = null, NpcDataPacket sceneSpeakerNpc = null, List<NpcDataPacket> sceneCandidates = null, string currentPlayerText = null)
	{
		List<string> allRuleIds = AIConfigHandler.GetConfiguredEnabledGuardrailRuleIdsForExternal();
		if (AfGcczShoutBridge.ShouldUseExclusivePreprocessRuleRouting(targetAgentIndex))
		{
			return AfGcczShoutBridge.BuildRuntimePreprocessRuleExclusions(allRuleIds, targetAgentIndex);
		}
		if (allRuleIds == null || allRuleIds.Count == 0)
		{
			return new List<string>();
		}
		HashSet<string> excluded = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		Agent agent = (targetAgentIndex >= 0) ? Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == targetAgentIndex) : null;
		string targetKingdomId = TryGetKingdomIdOverrideFromAgent(agent);
		string targetHeroId = (targetHero?.StringId ?? targetCharacter?.HeroObject?.StringId ?? "").Trim();
		string targetCharacterId = (targetCharacter?.StringId ?? "").Trim();
		try
		{
			AIConfigHandler.SetGuardrailRuntimeTargetKingdom(targetKingdomId);
			AIConfigHandler.SetGuardrailRuntimeTargetHero(targetHeroId);
			AIConfigHandler.SetGuardrailRuntimeTargetCharacter(targetCharacterId);
			AIConfigHandler.SetGuardrailRuntimeTargetTroop(targetCharacterId);
			AIConfigHandler.SetGuardrailRuntimeTargetUnnamedRank((targetHero == null && targetCharacter != null) ? (targetCharacter.IsSoldier ? "soldier" : "commoner") : "");
			AIConfigHandler.SetGuardrailRuntimeTargetAgentIndex(targetAgentIndex);
			foreach (string ruleId in allRuleIds)
			{
				string id = (ruleId ?? "").Trim();
				if (string.IsNullOrWhiteSpace(id))
				{
					continue;
				}
				if (!CanInjectRuleTopicIntoPreprocessForCurrentInteraction(id, targetHero, targetCharacter, targetAgentIndex, hasAnyHero, sceneSummonTargets, sceneGuideTargets, sceneSpeakerNpc, sceneCandidates))
				{
					excluded.Add(id);
				}
			}
		}
		finally
		{
			AIConfigHandler.SetGuardrailRuntimeTargetKingdom("");
			AIConfigHandler.SetGuardrailRuntimeTargetHero("");
			AIConfigHandler.SetGuardrailRuntimeTargetCharacter("");
			AIConfigHandler.SetGuardrailRuntimeTargetTroop("");
			AIConfigHandler.SetGuardrailRuntimeTargetUnnamedRank("");
			AIConfigHandler.SetGuardrailRuntimeTargetAgentIndex(-1);
		}
		return excluded.ToList();
	}

	private bool CanInjectRuleTopicIntoPreprocessForCurrentInteraction(string ruleId, Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, bool hasAnyHero, List<SceneSummonPromptTarget> sceneSummonTargets = null, List<SceneGuidePromptTarget> sceneGuideTargets = null, NpcDataPacket sceneSpeakerNpc = null, List<NpcDataPacket> sceneCandidates = null)
	{
		string id = (ruleId ?? "").Trim().ToLowerInvariant();
		if (string.IsNullOrWhiteSpace(id))
		{
			return false;
		}
		Hero hero = targetHero ?? targetCharacter?.HeroObject;
		if (!AIConfigHandler.IsGuardrailRuleAvailableToPreprocessForExternal(id, hasAnyHero))
		{
			return false;
		}
		if (NoblePrisonerEscortBehavior.IsEscortedAgent(targetAgentIndex))
		{
			return true;
		}
		if (AIConfigHandler.IsPlayerPartyTradeLimitedTarget(hero) && (id == "loan" || id == "kingdom_agenda" || id == "diplomacy" || id == "party_transfer"))
		{
			return false;
		}
		if (id == AutoGroupRelayRuleId)
		{
			return false;
		}
		switch (id)
		{
		case "scene_mechanism_actions":
			return CanInjectSceneMechanismTopicIntoPreprocess(sceneSummonTargets, sceneGuideTargets, sceneSpeakerNpc, sceneCandidates);
		case "worldmap_party_command":
			return !ShouldExcludeWorldMapCommandTopicForPreprocess(hero, targetCharacter, targetAgentIndex);
		case "party_transfer":
			return (MyBehavior.BuildPartyTransferPromptEntriesForExternal(hero, targetCharacter, targetAgentIndex)?.Count ?? 0) > 0;
		case "encounter_release_player":
			return !string.IsNullOrWhiteSpace(LordEncounterBehavior.BuildMeetingPlayerReleaseRuntimeInstructionForExternal(hero));
		case "meeting_taunt":
			PartyBase meetingTauntParty = null;
			if (hero == null)
			{
				TryResolveNativeConversationMeetingTauntParty(targetHero, targetCharacter, targetAgentIndex, out meetingTauntParty);
			}
			return !string.IsNullOrWhiteSpace(LordEncounterBehavior.BuildMeetingTauntRuntimeInstructionForExternal(hero, targetCharacter, meetingTauntParty))
				|| !string.IsNullOrWhiteSpace(SceneTauntBehavior.BuildUnifiedTauntRuntimeInstructionForExternal(hero, targetCharacter, targetAgentIndex));
		default:
			return true;
		}
	}

	private bool CanInjectSceneMechanismTopicIntoPreprocess(List<SceneSummonPromptTarget> sceneSummonTargets, List<SceneGuidePromptTarget> sceneGuideTargets, NpcDataPacket sceneSpeakerNpc, List<NpcDataPacket> sceneCandidates)
	{
		try
		{
			if (Mission.Current == null)
			{
				return false;
			}
			string sceneSummonClosureInstruction = "";
			if (sceneCandidates != null && sceneCandidates.Count > 0)
			{
				sceneSummonClosureInstruction = BuildSceneSummonClosurePromptInstruction(sceneCandidates);
			}
			else if (sceneSpeakerNpc != null)
			{
				sceneSummonClosureInstruction = BuildSceneSummonClosurePromptInstruction(new List<NpcDataPacket> { sceneSpeakerNpc });
			}
			string sceneFollowControlInstruction = BuildSceneFollowControlPromptInstruction(sceneSpeakerNpc);
			string section = BuildSceneMechanismPromptSection(sceneSummonTargets, sceneGuideTargets, sceneSummonClosureInstruction, sceneFollowControlInstruction, sceneSpeakerNpc);
			return !string.IsNullOrWhiteSpace(section);
		}
		catch
		{
			return false;
		}
	}

	private static bool ShouldExcludeWorldMapCommandTopicForPreprocess(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex = -1)
	{
		try
		{
			Hero hero = targetHero ?? targetCharacter?.HeroObject;
			if (hero != null)
			{
				return hero.IsNotable
					|| hero.Occupation == Occupation.Headman
					|| hero.Occupation == Occupation.RuralNotable
					|| hero.Occupation == Occupation.GangLeader
					|| hero.Occupation == Occupation.Merchant
					|| hero.Occupation == Occupation.Artisan
					|| hero.Occupation == Occupation.Preacher;
			}
			if (targetCharacter != null && !targetCharacter.IsHero)
			{
				return !WorldMapPartyCommandBehavior.CanUseNonHeroPartyFallbackForExternal(targetCharacter, targetAgentIndex);
			}
			return false;
		}
		catch
		{
			return false;
		}
	}

	private async Task<string> SubmitNativeConversationTextInternalAsync(string playerText, Action<string> onStreamText = null, string currentDialogTextOverride = null, Action<string> onPostprocessStarted = null, Action<string, Hero, CharacterObject> onMainReplyReady = null, bool npcInitiatedOpening = false)
	{
		Stopwatch nativeTurnSw = Stopwatch.StartNew();
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		playerText = (playerText ?? "").Replace("\r", "").Trim();
		if (PlayerEncounterCompat.IsInPostBattleResultFlow())
		{
			return "";
		}
		if (string.IsNullOrWhiteSpace(playerText) && !npcInitiatedOpening)
		{
			return "";
		}
		if (!TryResolveNativeConversationTarget(out var targetHero, out var targetCharacter, out var npcName))
		{
			return "当前没有可接入的对话对象。";
		}
		ConversationManager nativeRequestConversationManager = Campaign.Current?.ConversationManager;
		int nativeRequestConversationToken = nativeRequestConversationManager?.ActiveToken ?? int.MinValue;
		Logger.Log("Logic", "[NativePerf] submit_start target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown") + " npcInitiated=" + npcInitiatedOpening + " inputLen=" + playerText.Length);
		FreezeWatchdog.Mark("NativeConversation.submit_start", "target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown") + " npcInitiated=" + npcInitiatedOpening + " inputLen=" + playerText.Length, immediate: true);
		string npcOpeningExtraFact = "";
		string npcOpeningPromptText = "";
		string npcOpeningUserText = "";
		string npcOpeningPersistentFactText = "";
		string npcOpeningSource = "";
		bool npcOpeningConsumed = false;
		if (npcInitiatedOpening)
		{
			npcOpeningConsumed = NpcInitiatedOpeningRouter.TryConsumePendingNativeOpening(targetHero, out npcOpeningExtraFact, out npcOpeningPromptText, out npcOpeningSource);
			if (!npcOpeningConsumed)
			{
				return "";
			}
			npcOpeningUserText = BuildNpcInitiatedOpeningUserText(npcOpeningExtraFact, npcOpeningPromptText);
			npcOpeningPersistentFactText = BuildNpcInitiatedOpeningPersistentFactText(npcOpeningExtraFact);
			Logger.Log("ShoutBehavior", "[NativeConversation] NPC initiated opening consumed source=" + npcOpeningSource + " target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown"));
		}
		string promptPlayerText = npcInitiatedOpening ? "" : playerText;
		string routingInput = npcInitiatedOpening ? npcOpeningUserText : promptPlayerText;
		bool shouldRecordPlayerInput = !npcInitiatedOpening;
		FreezeWatchdog.Mark("NativeConversation.persona_start", "target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown"), immediate: true);
		bool personaReady = await EnsureNativeConversationPersonaReadyAsync(targetHero, onStreamText).ConfigureAwait(false);
		FreezeWatchdog.Mark("NativeConversation.persona_done", "target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown") + " ready=" + personaReady, immediate: true);
		if (SaveRuntimeGuard.IsStale(runtimeGeneration, "native_conversation_persona_ready"))
		{
			return SaveRuntimeGuard.BuildStaleRequestErrorText();
		}
		if (!personaReady)
		{
			return "";
		}
		int nativeTargetAgentIndex = TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
		NpcDataPacket npc = BuildNativeConversationNpcData(targetHero, targetCharacter);
		npc.AgentIndex = nativeTargetAgentIndex;
		string nativeTargetLog = targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown";
		string nativeInitialTargetUnavailableReason = "";
		bool nativeInitialTargetAvailable = await RunNativeConversationMainThreadFuncAsync(
			"request_target_validation",
			nativeTargetLog,
			nativeTargetAgentIndex,
			() => IsNativeConversationResponseTargetAvailableForActionDispatch(nativeTargetAgentIndex, targetHero, targetCharacter, out nativeInitialTargetUnavailableReason),
			false).ConfigureAwait(false);
		if (!nativeInitialTargetAvailable)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] skipped request because target is unavailable target=" + nativeTargetLog + " agentIndex=" + nativeTargetAgentIndex + " reason=" + (string.IsNullOrWhiteSpace(nativeInitialTargetUnavailableReason) ? "main_thread_validation_failed" : nativeInitialTargetUnavailableReason));
			return "";
		}
		List<NpcDataPacket> presentNpcs = new List<NpcDataPacket> { npc };
		string cultureId = npc.CultureId ?? "neutral";
		// Do not feed vanilla conversation UI text into AF prompt history.
		string currentNativeDialogText = "";
		bool hadNativeConversationSessionHistoryBeforeTurn = HasNativeConversationSessionHistory(targetHero, targetCharacter, npcName, nativeTargetAgentIndex, npc);
		string extraFact = npcOpeningPersistentFactText;
		string nativeMeetingTauntRuleBlock = "";
		PartyBase nativeMeetingTauntParty = null;
		if (targetHero == null)
		{
			TryResolveNativeConversationMeetingTauntParty(targetHero, targetCharacter, nativeTargetAgentIndex, out nativeMeetingTauntParty);
		}
		string nativeMeetingTauntInstruction = (LordEncounterBehavior.BuildMeetingTauntRuntimeInstructionForExternal(targetHero, targetCharacter, nativeMeetingTauntParty) ?? "").Trim();
		if (string.IsNullOrWhiteSpace(nativeMeetingTauntInstruction))
		{
			nativeMeetingTauntInstruction = (SceneTauntBehavior.BuildSceneTauntRuntimeInstructionForExternal(targetHero, targetCharacter, nativeTargetAgentIndex) ?? "").Trim();
		}
		if (AfGcczShoutBridge.ShouldAllowAfRuleForCurrentStage(TownAfRuleRoutingPolicy.MeetingTauntRuleId, nativeTargetAgentIndex) && !string.IsNullOrWhiteSpace(nativeMeetingTauntInstruction))
		{
			nativeMeetingTauntRuleBlock = AfGcczShoutBridge.MeetingTauntRuleBlockMarker + Environment.NewLine + nativeMeetingTauntInstruction;
		}
		Dictionary<int, Hero> nativeResolvedHeroes = new Dictionary<int, Hero>();
		if (nativeTargetAgentIndex >= 0 && targetHero != null)
		{
			nativeResolvedHeroes[nativeTargetAgentIndex] = targetHero;
		}
		List<SceneSummonPromptTarget> nativeSceneSummonTargets = (nativeTargetAgentIndex >= 0) ? BuildSceneSummonPromptTargets(presentNpcs, nativeResolvedHeroes) : null;
		int nativeSceneGuideFirstPromptId = ((nativeSceneSummonTargets != null && nativeSceneSummonTargets.Count > 0) ? nativeSceneSummonTargets.Max((SceneSummonPromptTarget x) => x?.PromptId ?? 0) : 0) + 1;
		Agent nativeTargetAgent = (nativeTargetAgentIndex >= 0) ? Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == nativeTargetAgentIndex) : null;
		List<SceneGuidePromptTarget> nativeSceneGuideTargets = (nativeTargetAgentIndex >= 0) ? BuildSceneGuidePromptTargets(nativeTargetAgent, nativeSceneGuideFirstPromptId) : null;
		List<string> preprocessExcludedRuleIds = BuildPreprocessExcludedRuleIdsForCurrentInteraction(targetHero, targetCharacter, nativeTargetAgentIndex, npc.IsHero, nativeSceneSummonTargets, nativeSceneGuideTargets, npc, presentNpcs, routingInput);
		bool includeCurrentSceneSessionInPersistedHistory = false;
		if (includeCurrentSceneSessionInPersistedHistory)
		{
			Logger.Log("ShoutBehavior", "[NativeConversation] including active scene-session memory because scene dialogue snapshot is missing. target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agentIndex=" + nativeTargetAgentIndex);
		}
		Logger.Log("Logic", "[MemoryPerf] parallel_history_start reason=native_conversation target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? "unknown") + " agent=" + nativeTargetAgentIndex + " mode=task");
		Task<string> persistedHeroHistoryTask = Task.Run(() => BuildNativeConversationPersistedHistoryContextForPrompt(targetHero, targetCharacter, shouldRecordPlayerInput ? promptPlayerText : "", currentNativeDialogText, includeCurrentSceneSessionInPersistedHistory));
		Stopwatch nativePreprocessSw = Stopwatch.StartNew();
		FreezeWatchdog.Mark("NativeConversation.preprocess_start", "target=" + (targetHero?.StringId ?? targetCharacter?.StringId ?? npcName ?? "unknown") + " agent=" + nativeTargetAgentIndex, immediate: true);
		MyBehavior.WeeklyPromptSnapshot weeklyPromptSnapshot = await RunNativeConversationMainThreadFuncAsync(
			"weekly_prompt_snapshot",
			nativeTargetLog,
			nativeTargetAgentIndex,
			() => MyBehavior.CaptureWeeklyPromptSnapshotForExternal(targetHero, targetCharacter),
			MyBehavior.WeeklyPromptSnapshot.Empty).ConfigureAwait(false) ?? MyBehavior.WeeklyPromptSnapshot.Empty;
		Task<MyBehavior.ShoutPromptContext> nativePreprocessTask = RunNativeConversationBackgroundPreprocessAsync(
			nativeTargetLog,
			nativeTargetAgentIndex,
			runtimeGeneration,
			() => MyBehavior.BuildShoutPromptContextForExternal(targetHero, routingInput, extraFact, cultureId, hasAnyHero: npc.IsHero, targetCharacter: targetCharacter, kingdomIdOverride: null, targetAgentIndex: nativeTargetAgentIndex, preprocessExcludedRuleIds: preprocessExcludedRuleIds, weeklyPromptSnapshot: weeklyPromptSnapshot));
		MyBehavior.ShoutPromptContext ctx = await AwaitNativeConversationBackgroundPreprocessAsync(nativePreprocessTask, nativeTargetLog, nativeTargetAgentIndex, runtimeGeneration).ConfigureAwait(false);
		nativePreprocessSw.Stop();
		if (ctx == null)
		{
			FreezeWatchdog.Mark("NativeConversation.preprocess_aborted", "target=" + nativeTargetLog + " agent=" + nativeTargetAgentIndex + " ms=" + Math.Round(nativePreprocessSw.Elapsed.TotalMilliseconds, 2), immediate: true);
