								}
								string historyText = SanitizeSceneSpeechText(content);
								string fullHistoryText = PrepareSceneHistorySpeechText(historyFullContent);
								RefreshSceneSummonConversationForSpeaker((agent != null) ? agent.Index : matchedNpc.AgentIndex);
								bool flag4 = IsAgentHostileToMainAgent(agent);
								if (interactionTimeoutSeconds > 0f && !noblePrisonerExecutionQueued && !flagNpcSurrender && !flag4 && !flag5 && !flag6 && !flag10 && !flagMeetingRelease && !flagSceneTaunt2)
								{
									RefreshActiveInteractionTimeout(matchedNpc, interactionParticipantCount, interactionTimeoutSeconds);
								}
								bool suppressInteractionTimeoutArm = interactionParticipantCount > 1 && interactionTimeoutSeconds <= 0f;
								sceneSpeechPlaybackInfo = ShowNpcSpeechOutput(matchedNpc, agent, historyText, allowTts: true, attachTtsToSceneAgent: true, suppressInteractionTimeoutArm);
								if (!string.IsNullOrWhiteSpace(afterSpeechInfoMessage))
								{
									InformationManager.DisplayMessage(new InformationMessage(afterSpeechInfoMessage, new Color(1f, 0.95f, 0.25f)));
								}
								if (flag7)
								{
									ScheduleSceneFollowCommandAfterSpeech(matchedNpc.AgentIndex, startFollow: false, sceneSpeechPlaybackInfo);
								}
								else if (flag8)
								{
									ScheduleSceneFollowCommandAfterSpeech(matchedNpc.AgentIndex, startFollow: true, sceneSpeechPlaybackInfo);
								}
								if (flag5 && sceneSummonConversationSession != null)
								{
									_pendingSceneSummonReturnsAfterSpeech[matchedNpc.AgentIndex] = new PendingSceneSummonReturnAfterSpeech
									{
										AgentIndex = matchedNpc.AgentIndex,
										Session = sceneSummonConversationSession,
										ReturnOnlySpeaker = ShouldReturnOnlySceneSummonSpeaker(sceneSummonConversationSession, agent)
									};
								}
								ScheduleSceneSummonReturnAfterSpeech(matchedNpc.AgentIndex, sceneSpeechPlaybackInfo);
								ScheduleSceneGuideReturnAfterSpeech(matchedNpc.AgentIndex, sceneSpeechPlaybackInfo);
								ScheduleSceneAutonomyRestoreAfterSpeech(matchedNpc.AgentIndex, sceneSpeechPlaybackInfo);
								if (flagMeetingRelease)
								{
									ScheduleMeetingReleaseAfterSpeech(matchedNpc.AgentIndex, ResolveHeroFromAgentIndex(matchedNpc.AgentIndex), sceneSpeechPlaybackInfo);
								}
								if (flag6 && activeSceneSummonRequest != null)
								{
									SchedulePreparedSceneSummonLaunch(activeSceneSummonRequest, sceneSpeechPlaybackInfo, historyText);
								}
								if (flag10 && activeSceneGuideRequest != null)
								{
									SchedulePreparedSceneGuideLaunch(activeSceneGuideRequest, sceneSpeechPlaybackInfo, historyText);
								}
								if (flag4)
								{
									RefreshHostileCombatAgentAutonomy(agent);
								}
								if (CanAgentParticipateInSceneSpeech(agent) && !suppressStare && !flag4 && !flag6 && !flag10)
								{
									HoldSceneConversationParticipants(allNpcData);
									AddAgentToStareList(agent, interruptCurrentUse: false);
								}
								if (commitHistory && !string.IsNullOrWhiteSpace(fullHistoryText))
								{
									RecordResponseForAllNearbySafe(allNpcData, matchedNpc.AgentIndex, matchedNpc.Name, fullHistoryText);
									PersistNpcSpeechToNamedHeroes(matchedNpc.AgentIndex, matchedNpc.Name, fullHistoryText, allNpcData);
								}
								if (worldMapResult?.NeedsChannelExit == true)
								{
									ScheduleWorldMapMissionExitAfterSpeech(matchedNpc.AgentIndex, sceneSpeechPlaybackInfo);
								}
								if (flagSceneTaunt2 && !IsMeetingSceneConversationReleaseSensitive())
								{
									ReleaseSceneConversationConstraints(allNpcData, matchedNpc.AgentIndex, stopAutoGroupSession: true, clearQueuedSpeech: true);
								}
							}
							else if (flag7)
							{
								ScheduleSceneFollowCommandAfterSpeech(matchedNpc.AgentIndex, startFollow: false, null);
							}
							else if (flag8)
							{
								ScheduleSceneFollowCommandAfterSpeech(matchedNpc.AgentIndex, startFollow: true, null);
							}
							if (flag2)
							{
								ReleaseSceneConversationConstraints(allNpcData, matchedNpc.AgentIndex, stopAutoGroupSession: true, clearQueuedSpeech: true, forceFullAutonomyRelease: true);
								DuelBehavior.SetNextDuelRiskWarningEnabled(_lastShoutDuelLiteralHit);
								ShoutUtils.ExecuteDuel(agent);
							}
							if (flag3)
							{
								ScheduleLordsHallMissionEntryAfterSpeech(matchedNpc.AgentIndex, sceneSpeechPlaybackInfo, "scene_tag");
								return;
							}
							else if (flag6 && activeSceneSummonRequest != null && string.IsNullOrWhiteSpace(content))
							{
								SchedulePreparedSceneSummonLaunch(activeSceneSummonRequest, null, "");
							}
							else if (flag10 && activeSceneGuideRequest != null && string.IsNullOrWhiteSpace(content))
							{
								SchedulePreparedSceneGuideLaunch(activeSceneGuideRequest, null, "");
							}
						}
						if (flag5 && sceneSummonConversationSession != null && string.IsNullOrWhiteSpace(content))
						{
							BeginSceneSummonConversationReturn(sceneSummonConversationSession);
						}
					}
					catch (Exception ex)
					{
						Logger.Log("ShoutBehavior", "[ERROR] RunSpeechQueueWorker mainThread: " + ex.Message);
					}
					finally
					{
						completionSource?.TrySetResult(true);
					}
				});
				await Task.Delay(2000);
				item = null;
			}
		}
		catch
		{
			lock (_speechQueueLock)
			{
				_speechWorkerRunning = false;
			}
		}
	}

	private static string NormalizeSceneExtraFactForHistory(string extraFact)
	{
		string text = (extraFact ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return "";
		}
		if (!text.StartsWith("[AFEF玩家行为补充]", StringComparison.Ordinal)
			&& !text.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
		{
			text = "[AFEF玩家行为补充] " + text;
		}
		return text;
	}

	private void RecordExtraFactToSceneHistory(string extraFact, List<NpcDataPacket> nearbyData)
	{
		if (string.IsNullOrWhiteSpace(extraFact) || nearbyData == null)
		{
			return;
		}
		string text = NormalizeSceneExtraFactForHistory(extraFact);
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		List<int> visibleAgentIndices = BuildVisibleAgentSnapshot(nearbyData);
		long eventSequence = NextConversationEventSequence();
		lock (_historyLock)
		{
			_publicConversationHistory.Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
			{
				EventSequence = eventSequence,
				Role = "system",
				Content = text,
				SpeakerName = "系统",
				SpeakerAgentIndex = -1,
				VisibleAgentIndices = visibleAgentIndices
			}));
			foreach (NpcDataPacket nearbyDatum in nearbyData)
			{
				int agentIndex = nearbyDatum.AgentIndex;
				if (!_npcConversationHistory.ContainsKey(agentIndex))
				{
					_npcConversationHistory[agentIndex] = new List<ConversationMessage>();
				}
				_npcConversationHistory[agentIndex].Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "system",
					Content = text,
					SpeakerName = "系统",
					SpeakerAgentIndex = -1,
					VisibleAgentIndices = visibleAgentIndices
				}));
			}
		}
		AppendSceneEventToNativeSharedHistoryForTargets(nearbyData, "系统", text, "fact", eventSequence);
	}

	private void AppendNativeConversationSessionLineToSceneHistory(Hero targetHero, CharacterObject targetCharacter, string npcName, string speaker, string text, string kind, long eventSequence = 0L, int targetAgentIndexOverride = -1, NpcDataPacket targetNpc = null, int playerTargetAgentIndexOverride = -1, string playerTargetNameOverride = null)
	{
		text = (text ?? "").Replace("\r", "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		try
		{
			int targetAgentIndex = targetAgentIndexOverride >= 0 ? targetAgentIndexOverride : TryResolveNativeConversationAgentIndex(targetHero, targetCharacter);
			if (targetAgentIndex < 0)
			{
				return;
			}
			string targetName = (npcName ?? "").Trim();
			try
			{
				NpcDataPacket npc = targetNpc;
				if (npc == null)
				{
					Agent agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == targetAgentIndex && a.IsActive());
					npc = ShoutUtils.ExtractNpcData(agent);
				}
				string sceneName = (npc != null) ? GetSceneNpcHistoryNameForPrompt(npc) : "";
				if (!string.IsNullOrWhiteSpace(sceneName))
				{
					targetName = sceneName;
				}
			}
			catch
			{
			}
			if (string.IsNullOrWhiteSpace(targetName))
			{
				targetName = (targetHero?.Name?.ToString() ?? targetCharacter?.Name?.ToString() ?? "NPC").Trim();
			}
			string normalizedKind = (kind ?? "").Trim().ToLowerInvariant();
			int actualPlayerTargetAgentIndex = playerTargetAgentIndexOverride >= 0 ? playerTargetAgentIndexOverride : targetAgentIndex;
			string actualPlayerTargetName = (playerTargetNameOverride ?? "").Trim();
			if (string.IsNullOrWhiteSpace(actualPlayerTargetName))
			{
				actualPlayerTargetName = targetName;
			}
			ConversationMessage message;
			List<int> visibleAgentIndices = new List<int> { targetAgentIndex };
			if (normalizedKind == "npc")
			{
				message = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "assistant",
					Content = NormalizeNativeConversationVisibleTextKey(text),
					SpeakerName = targetName,
					SpeakerAgentIndex = targetAgentIndex,
					VisibleAgentIndices = visibleAgentIndices
				});
			}
			else if (normalizedKind == "fact")
			{
				message = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "system",
					Content = NormalizeNativeConversationFactLineForPrompt(text, speaker),
					SpeakerName = "系统",
					SpeakerAgentIndex = -1,
					VisibleAgentIndices = visibleAgentIndices
				});
			}
			else
			{
				message = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "user",
					Content = text,
					SpeakerName = "你",
					SpeakerAgentIndex = -1,
					TargetAgentIndex = actualPlayerTargetAgentIndex,
					TargetName = actualPlayerTargetName,
					PlayerDistanceMeters = GetPlayerDistanceToAgentForScenePrompt(actualPlayerTargetAgentIndex),
					VisibleAgentIndices = visibleAgentIndices
				});
			}
			if (string.IsNullOrWhiteSpace(message.Content))
			{
				return;
			}
			lock (_historyLock)
			{
				_publicConversationHistory.Add(message);
				if (!_npcConversationHistory.ContainsKey(targetAgentIndex))
				{
					_npcConversationHistory[targetAgentIndex] = new List<ConversationMessage>();
				}
				_npcConversationHistory[targetAgentIndex].Add(message);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("NativeConversation", "[WARN] scene-history bridge failed: " + ex.Message);
		}
	}

	private void RemoveNativeConversationSessionHistoryEventFromSceneHistory(long eventSequence)
	{
		if (eventSequence <= 0L)
		{
			return;
		}
		try
		{
			lock (_historyLock)
			{
				_publicConversationHistory.RemoveAll((ConversationMessage message) => message != null && message.EventSequence == eventSequence);
				foreach (List<ConversationMessage> history in _npcConversationHistory.Values)
				{
					history?.RemoveAll((ConversationMessage message) => message != null && message.EventSequence == eventSequence);
				}
			}
		}
		catch (Exception ex)
		{
			Logger.Log("NativeConversation", "[WARN] scene-history rollback failed: " + ex.Message);
		}
	}

	private void ClearPendingCurrentAfefFacts()
	{
		lock (_pendingCurrentAfefFactsLock)
		{
			_pendingCurrentAfefFactsByAgent.Clear();
		}
		lock (_pendingCurrentNativeAfefFactsLock)
		{
			_pendingCurrentNativeAfefFactsByKey.Clear();
		}
	}

	private NpcDataPacket ResolveSceneNpcDataForSharedHistory(int agentIndex, string fallbackName = "")
	{
		try
		{
			Agent agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == agentIndex && a.IsActive());
			NpcDataPacket npc = ShoutUtils.ExtractNpcData(agent);
			if (npc != null)
			{
				return npc;
			}
		}
		catch
		{
		}
		if (agentIndex < 0 && string.IsNullOrWhiteSpace(fallbackName))
		{
			return null;
		}
		return new NpcDataPacket
		{
			AgentIndex = agentIndex,
			Name = string.IsNullOrWhiteSpace(fallbackName) ? "NPC" : fallbackName.Trim(),
			IsHero = false,
			CultureId = "neutral"
		};
	}

	private void AppendSceneEventToNativeSharedHistory(NpcDataPacket targetNpc, string speaker, string text, string kind, long eventSequence, int playerTargetAgentIndex = -1, string playerTargetName = null, Agent targetAgentOverride = null)
	{
		text = (text ?? "").Replace("\r", "").Trim();
		if (targetNpc == null || string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		try
		{
			Agent targetAgent = targetAgentOverride != null && targetAgentOverride.Index == targetNpc.AgentIndex ? targetAgentOverride : null;
			CharacterObject character = targetAgent?.Character as CharacterObject;
			Hero hero = character?.HeroObject;
			if (hero == null && targetAgent == null)
			{
				hero = ResolveHeroFromAgentIndex(targetNpc.AgentIndex);
				character = hero?.CharacterObject;
			}
			if (character == null && targetNpc.AgentIndex >= 0)
			{
				targetAgent ??= Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == targetNpc.AgentIndex && a.IsActive());
				character = targetAgent?.Character as CharacterObject;
				hero ??= character?.HeroObject;
			}
			string npcName = GetSceneNpcHistoryNameForPrompt(targetNpc);
			if (string.IsNullOrWhiteSpace(npcName))
			{
				npcName = (hero?.Name?.ToString() ?? character?.Name?.ToString() ?? targetNpc.Name ?? "NPC").Trim();
			}
			AppendNativeConversationSessionHistory(hero, character, npcName, speaker, text, kind, eventSequence, bridgeToSceneHistory: false, targetAgentIndex: targetNpc.AgentIndex, npc: targetNpc, playerTargetAgentIndex: playerTargetAgentIndex, playerTargetName: playerTargetName);
		}
		catch (Exception ex)
		{
			Logger.Log("SharedConversationHistory", "[WARN] scene->native append failed: " + ex.Message);
		}
	}

	private void AppendSceneEventToNativeSharedHistoryForTargets(IEnumerable<NpcDataPacket> targets, string speaker, string text, string kind, long eventSequence, int playerTargetAgentIndex = -1, string playerTargetName = null, Dictionary<int, Agent> audienceAgentsByIndex = null)
	{
		if (targets == null)
		{
			return;
		}
		HashSet<string> writtenKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (NpcDataPacket target in targets)
		{
			if (target == null)
			{
				continue;
			}
			string key = target.AgentIndex.ToString();
			if (!writtenKeys.Add(key))
			{
				continue;
			}
			Agent targetAgent = null;
			audienceAgentsByIndex?.TryGetValue(target.AgentIndex, out targetAgent);
			AppendSceneEventToNativeSharedHistory(target, speaker, text, kind, eventSequence, playerTargetAgentIndex, playerTargetName, targetAgent);
		}
	}

	private void QueuePendingCurrentNativeAfefFactForSceneTarget(NpcDataPacket targetNpc, string fact)
	{
		if (targetNpc == null || string.IsNullOrWhiteSpace(fact))
		{
			return;
		}
		try
		{
			Hero hero = ResolveHeroFromAgentIndex(targetNpc.AgentIndex);
			CharacterObject character = hero?.CharacterObject;
			if (character == null && targetNpc.AgentIndex >= 0)
			{
				Agent agent = Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == targetNpc.AgentIndex && a.IsActive());
				character = agent?.Character as CharacterObject;
				hero ??= character?.HeroObject;
			}
			string npcName = GetSceneNpcHistoryNameForPrompt(targetNpc);
			if (string.IsNullOrWhiteSpace(npcName))
			{
				npcName = (hero?.Name?.ToString() ?? character?.Name?.ToString() ?? targetNpc.Name ?? "NPC").Trim();
			}
			string key = BuildNativeConversationHistoryKey(hero, character, npcName, targetNpc.AgentIndex, targetNpc);
			if (!string.IsNullOrWhiteSpace(key))
			{
				QueuePendingCurrentNativeAfefFactForKey(key, fact);
			}
		}
		catch
		{
		}
	}

	private void QueuePendingCurrentAfefFactForAgent(int targetAgentIndex, string fact)
	{
		if (targetAgentIndex < 0)
		{
			return;
		}
		string factLine = NormalizeAfefFactLineForPrompt(fact);
		if (string.IsNullOrWhiteSpace(factLine))
		{
			return;
		}
		ConversationMessage message = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
		{
			Role = "system",
			Content = factLine,
			SpeakerName = "系统",
			SpeakerAgentIndex = -1,
			VisibleAgentIndices = new List<int> { targetAgentIndex }
		});
		lock (_pendingCurrentAfefFactsLock)
		{
			if (!_pendingCurrentAfefFactsByAgent.TryGetValue(targetAgentIndex, out var list) || list == null)
			{
				list = new List<ConversationMessage>();
				_pendingCurrentAfefFactsByAgent[targetAgentIndex] = list;
			}
			list.Add(message);
			while (list.Count > 12)
			{
				list.RemoveAt(0);
			}
		}
	}

	private List<ConversationMessage> ConsumePendingCurrentAfefFactMessagesForPrompt(int targetAgentIndex)
	{
		if (targetAgentIndex < 0)
		{
			return new List<ConversationMessage>();
		}
		lock (_pendingCurrentAfefFactsLock)
		{
			if (!_pendingCurrentAfefFactsByAgent.TryGetValue(targetAgentIndex, out var list) || list == null || list.Count == 0)
			{
				return new List<ConversationMessage>();
			}
			_pendingCurrentAfefFactsByAgent.Remove(targetAgentIndex);
			return list.Where((ConversationMessage x) => x != null).ToList();
		}
	}

	private void QueuePendingCurrentNativeAfefFactForKey(string key, string fact)
	{
		key = (key ?? "").Trim();
		if (string.IsNullOrWhiteSpace(key))
		{
			return;
		}
		string factLine = NormalizeAfefFactLineForPrompt(fact);
		if (string.IsNullOrWhiteSpace(factLine))
		{
			return;
		}
		ConversationMessage message = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
		{
			Role = "system",
			Content = factLine,
			SpeakerName = "系统",
			SpeakerAgentIndex = -1
		});
		lock (_pendingCurrentNativeAfefFactsLock)
		{
			if (!_pendingCurrentNativeAfefFactsByKey.TryGetValue(key, out var list) || list == null)
			{
				list = new List<ConversationMessage>();
				_pendingCurrentNativeAfefFactsByKey[key] = list;
			}
			list.Add(message);
			while (list.Count > 12)
			{
				list.RemoveAt(0);
			}
		}
	}

	private List<ConversationMessage> ConsumePendingCurrentNativeAfefFactMessagesForPrompt(string key)
	{
		key = (key ?? "").Trim();
		if (string.IsNullOrWhiteSpace(key))
		{
			return new List<ConversationMessage>();
		}
		lock (_pendingCurrentNativeAfefFactsLock)
		{
			if (!_pendingCurrentNativeAfefFactsByKey.TryGetValue(key, out var list) || list == null || list.Count == 0)
			{
