	private void AppendActionAfefFactToSceneHistoryInOrder(int targetAgentIndex, string fact, bool mirrorToNativeSharedHistory = true)
	{
		if (targetAgentIndex < 0)
		{
			return;
		}
		string factLine = NormalizeNativeConversationFactLineForPrompt(fact, "玩家动作");
		if (string.IsNullOrWhiteSpace(factLine))
		{
			return;
		}
		long eventSequence = NextConversationEventSequence();
		ConversationMessage publicMessage = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
		{
			EventSequence = eventSequence,
			Role = "system",
			Content = factLine,
			SpeakerName = "系统",
			SpeakerAgentIndex = -1,
			VisibleAgentIndices = new List<int> { targetAgentIndex }
		});
		ConversationMessage privateMessage = StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
		{
			EventSequence = eventSequence,
			Role = "system",
			Content = factLine,
			SpeakerName = "系统",
			SpeakerAgentIndex = -1,
			VisibleAgentIndices = new List<int> { targetAgentIndex }
		});
		lock (_historyLock)
		{
			_publicConversationHistory.Add(publicMessage);
			if (!_npcConversationHistory.TryGetValue(targetAgentIndex, out var history) || history == null)
			{
				history = new List<ConversationMessage>();
				_npcConversationHistory[targetAgentIndex] = history;
			}
			history.Add(privateMessage);
		}
		if (mirrorToNativeSharedHistory)
		{
			AppendSceneEventToNativeSharedHistory(ResolveSceneNpcDataForSharedHistory(targetAgentIndex), "玩家动作", factLine, "fact", eventSequence);
		}
	}

	private void PersistExtraFactToNamedHeroes(
		string extraFact,
		List<NpcDataPacket> nearbyData,
		int personalizedAgentIndex = -1)
	{
		if (string.IsNullOrWhiteSpace(extraFact) || nearbyData == null)
		{
			return;
		}
		string sharedExtraFact = personalizedAgentIndex >= 0
			? StripPlayerCraftedAfefInspectionSuffix(extraFact)
			: extraFact;
		HashSet<string> persistedNonHeroIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		if (personalizedAgentIndex >= 0)
		{
			NpcDataPacket personalizedTarget = nearbyData.FirstOrDefault(
				npc => npc != null && npc.AgentIndex == personalizedAgentIndex);
			PersistExtraFactToNamedObserver(
				personalizedTarget,
				extraFact,
				persistedNonHeroIds);
		}
		foreach (NpcDataPacket nearbyDatum in nearbyData)
		{
			if (nearbyDatum == null || nearbyDatum.AgentIndex == personalizedAgentIndex)
			{
				continue;
			}
			PersistExtraFactToNamedObserver(
				nearbyDatum,
				sharedExtraFact,
				persistedNonHeroIds);
		}
	}

	private void PersistExtraFactToNamedObserver(
		NpcDataPacket observer,
		string extraFact,
		HashSet<string> persistedNonHeroIds)
	{
		if (observer == null || string.IsNullOrWhiteSpace(extraFact))
		{
			return;
		}
		if (observer.IsHero)
		{
			Hero hero = ResolveHeroFromAgentIndex(observer.AgentIndex);
			if (hero != null)
			{
				MyBehavior.AppendExternalSceneDialogueHistory(
					hero,
					null,
					null,
					extraFact,
					_sceneHistorySessionId);
			}
			return;
		}
		if (TryResolveWildernessNonHeroMemory(
			observer,
			null,
			null,
			observer.AgentIndex,
			out var memoryId,
			out var memoryName)
			&& (persistedNonHeroIds == null || persistedNonHeroIds.Add(memoryId)))
		{
			MyBehavior.AppendExternalNonHeroSceneDialogueHistory(
				memoryId,
				memoryName,
				null,
				null,
				extraFact,
				_sceneHistorySessionId);
		}
	}

	private void RecordPlayerMessage(string text, List<NpcDataPacket> nearbyData, int primaryTargetAgentIndex = -1, string primaryTargetName = "", Dictionary<int, Agent> audienceAgentsByIndex = null)
	{
		// Must happen first so the dynamic AFEF fact sits directly above the player's current scene utterance.
		TryInjectSceneFirstMeetingFactsBeforePlayerMessage(nearbyData);
		TryInjectSceneRevisitFactsBeforePlayerMessage(nearbyData);
		List<int> visibleAgentIndices = BuildVisibleAgentSnapshot(nearbyData);
		string text2 = ResolveSceneTargetNameForPrompt(primaryTargetAgentIndex, primaryTargetName, nearbyData);
		float playerDistanceMeters = GetPlayerDistanceToAgentForScenePrompt(primaryTargetAgentIndex);
		long eventSequence = NextConversationEventSequence();
		lock (_historyLock)
		{
			_publicConversationHistory.Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
			{
				EventSequence = eventSequence,
				Role = "user",
				Content = text,
				SpeakerName = "你",
				SpeakerAgentIndex = -1,
				TargetAgentIndex = primaryTargetAgentIndex,
				TargetName = text2,
				PlayerDistanceMeters = playerDistanceMeters,
				VisibleAgentIndices = visibleAgentIndices
			}));
			foreach (NpcDataPacket nearbyDatum in nearbyData)
			{
				int agentIndex = nearbyDatum.AgentIndex;
				if (!_npcConversationHistory.ContainsKey(agentIndex))
				{
					_npcConversationHistory[agentIndex] = new List<ConversationMessage>();
				}
				_npcConversationHistory[agentIndex].Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "user",
					Content = text,
					SpeakerName = "你",
					SpeakerAgentIndex = -1,
					TargetAgentIndex = primaryTargetAgentIndex,
					TargetName = text2,
					PlayerDistanceMeters = playerDistanceMeters,
					VisibleAgentIndices = visibleAgentIndices
				}));
			}
		}
		AppendSceneEventToNativeSharedHistoryForTargets(nearbyData, GetPlayerDisplayNameForShout(), text, "player", eventSequence, primaryTargetAgentIndex, text2, audienceAgentsByIndex);
		try
		{
			PersistPlayerMessageToNamedHeroes(text, nearbyData, primaryTargetAgentIndex, text2, audienceAgentsByIndex);
		}
		catch
		{
		}
	}

	private static bool ShouldDeferExtraFactPersistenceUntilAfterSceneReply(string extraFact)
	{
		string text = (extraFact ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		return text.Contains("看了看 总值为")
			&& text.Contains("暂未交付给你")
			&& text.Contains("证明了他有这些东西");
	}

	private static bool ContainsPlayerCraftedAfefInspectionSuffix(string extraFact)
	{
		return !string.IsNullOrWhiteSpace(extraFact)
			&& extraFact.IndexOf(
				PlayerCraftedAfefInspectionSuffix,
				StringComparison.Ordinal) >= 0;
	}

	private static string StripPlayerCraftedAfefInspectionSuffix(string extraFact)
	{
		return (extraFact ?? "").Replace(
			PlayerCraftedAfefInspectionSuffix,
			"");
	}

	private void SetPendingHeroHistoryExtraFactAfterSceneReply(
		string extraFact,
		List<NpcDataPacket> nearbyData,
		int personalizedAgentIndex = -1)
	{
		_pendingHeroHistoryExtraFactAfterSceneReply = (extraFact ?? "").Trim();
		_pendingHeroHistoryExtraFactTargetsAfterSceneReply = CloneNpcDataSnapshot(nearbyData) ?? new List<NpcDataPacket>();
		_pendingHeroHistoryExtraFactPersonalizedAgentIndexAfterSceneReply = personalizedAgentIndex;
	}

	private void PromotePersonalizedExtraFactInScenePrivateHistory(
		string personalizedExtraFact,
		int personalizedAgentIndex)
	{
		if (personalizedAgentIndex < 0
			|| !ContainsPlayerCraftedAfefInspectionSuffix(personalizedExtraFact))
		{
			return;
		}
		string personalizedLine = NormalizeSceneExtraFactForHistory(personalizedExtraFact);
		string sharedLine = NormalizeSceneExtraFactForHistory(
			StripPlayerCraftedAfefInspectionSuffix(personalizedExtraFact));
		if (string.IsNullOrWhiteSpace(personalizedLine)
			|| string.IsNullOrWhiteSpace(sharedLine)
			|| string.Equals(personalizedLine, sharedLine, StringComparison.Ordinal))
		{
			return;
		}
		lock (_historyLock)
		{
			if (!_npcConversationHistory.TryGetValue(
				personalizedAgentIndex,
				out var privateHistory)
				|| privateHistory == null)
			{
				return;
			}
			for (int i = privateHistory.Count - 1; i >= 0; i--)
			{
				ConversationMessage message = privateHistory[i];
				if (message != null
					&& string.Equals(message.Role ?? "", "system", StringComparison.OrdinalIgnoreCase)
					&& string.Equals(message.Content ?? "", sharedLine, StringComparison.Ordinal))
				{
					message.Content = personalizedLine;
					message.TargetAgentIndex = personalizedAgentIndex;
					message.TargetHeroId = "";
					message.VisibleAgentIndices = new List<int> { personalizedAgentIndex };
					message.VisibleHeroIds = new List<string>();
					FillSceneMessageHeroIdentity(message);
					return;
				}
			}
		}
	}

	private void FlushPendingHeroHistoryExtraFactAfterSceneReply()
	{
		string text = (_pendingHeroHistoryExtraFactAfterSceneReply ?? "").Trim();
		List<NpcDataPacket> list = _pendingHeroHistoryExtraFactTargetsAfterSceneReply ?? new List<NpcDataPacket>();
		int personalizedAgentIndex =
			_pendingHeroHistoryExtraFactPersonalizedAgentIndexAfterSceneReply;
		_pendingHeroHistoryExtraFactAfterSceneReply = "";
		_pendingHeroHistoryExtraFactTargetsAfterSceneReply = new List<NpcDataPacket>();
		_pendingHeroHistoryExtraFactPersonalizedAgentIndexAfterSceneReply = -1;
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		if (personalizedAgentIndex >= 0)
		{
			PromotePersonalizedExtraFactInScenePrivateHistory(
				text,
				personalizedAgentIndex);
		}
		PersistExtraFactToNamedHeroes(
			text,
			list,
			personalizedAgentIndex);
	}

	private static bool IsSingleUseSceneNpcFactText(string text)
	{
		string text2 = (text ?? "").Trim();
		if (!text2.StartsWith("[AFEF NPC行为补充]", StringComparison.Ordinal))
		{
			return false;
		}
		string text3 = text2.Substring("[AFEF NPC行为补充]".Length).Trim();
		if (string.IsNullOrWhiteSpace(text3))
		{
			return false;
		}
		if (text3.StartsWith("今天稍早时候刚与", StringComparison.Ordinal) && text3.EndsWith("见过面。", StringComparison.Ordinal))
		{
			return true;
		}
		if (text3.StartsWith("距离你上次与", StringComparison.Ordinal) && text3.Contains("见面，已有") && text3.EndsWith("天了。", StringComparison.Ordinal))
		{
			return true;
		}
		return false;
	}

	private static bool IsSceneConversationTurn(ConversationMessage msg)
	{
		string text = (msg?.Role ?? "").Trim();
		return text.Equals("user", StringComparison.OrdinalIgnoreCase) || text.Equals("assistant", StringComparison.OrdinalIgnoreCase);
	}

	private static void RemoveExpiredSingleUseSceneNpcFacts(List<ConversationMessage> history)
	{
		if (history == null || history.Count == 0)
		{
			return;
		}
		bool flag = false;
		for (int num = history.Count - 1; num >= 0; num--)
		{
			ConversationMessage conversationMessage = history[num];
			if (flag && IsSingleUseSceneNpcFactText(conversationMessage?.Content))
			{
				history.RemoveAt(num);
				continue;
			}
			if (IsSceneConversationTurn(conversationMessage))
			{
				flag = true;
			}
		}
	}

	private void RecordResponseForAllNearbySafe(List<NpcDataPacket> nearbyData, int speakerAgentIndex, string speakerName, string response)
	{
		List<int> visibleAgentIndices = BuildVisibleAgentSnapshot(nearbyData);
		string text = ResolveSceneHistorySpeakerNameForPrompt(speakerAgentIndex, speakerName, nearbyData);
		long eventSequence = NextConversationEventSequence();
		lock (_historyLock)
		{
			foreach (NpcDataPacket nearbyDatum in nearbyData)
			{
				int agentIndex = nearbyDatum.AgentIndex;
				if (!_npcConversationHistory.ContainsKey(agentIndex))
				{
					_npcConversationHistory[agentIndex] = new List<ConversationMessage>();
				}
				_npcConversationHistory[agentIndex].Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "assistant",
					Content = "[" + text + "]: " + response,
					SpeakerName = text,
					SpeakerAgentIndex = speakerAgentIndex,
					VisibleAgentIndices = visibleAgentIndices
				}));
				RemoveExpiredSingleUseSceneNpcFacts(_npcConversationHistory[agentIndex]);
			}
			_publicConversationHistory.Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
			{
				EventSequence = eventSequence,
				Role = "assistant",
				Content = response,
				SpeakerName = text,
				SpeakerAgentIndex = speakerAgentIndex,
				VisibleAgentIndices = visibleAgentIndices
			}));
			RemoveExpiredSingleUseSceneNpcFacts(_publicConversationHistory);
		}
		NpcDataPacket speakerNpc = nearbyData?.FirstOrDefault((NpcDataPacket x) => x != null && x.AgentIndex == speakerAgentIndex) ?? ResolveSceneNpcDataForSharedHistory(speakerAgentIndex, speakerName);
		AfGcczShoutBridge.RecordOrdinarySpeakerUtterance(speakerNpc, response);
		AppendSceneEventToNativeSharedHistory(speakerNpc, text, response, "npc", eventSequence);
		FlushPendingHeroHistoryExtraFactAfterSceneReply();
	}

	private void RecordSystemFactForNearbySafe(List<NpcDataPacket> nearbyData, string factText)
	{
		string text = (factText ?? "").Replace("\r", "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		bool isAfefFact = TryNormalizeAfefFactLineForPrompt(text, out var afefFactLine);
		List<int> visibleAgentIndices = BuildVisibleAgentSnapshot(nearbyData);
		List<NpcDataPacket> afefPendingTargets = isAfefFact ? new List<NpcDataPacket>() : null;
		long eventSequence = NextConversationEventSequence();
		lock (_historyLock)
		{
			_publicConversationHistory.Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
			{
				EventSequence = eventSequence,
				Role = "system",
				Content = text,
				SpeakerName = "system",
				SpeakerAgentIndex = -1,
				VisibleAgentIndices = visibleAgentIndices
			}));
			if (nearbyData == null)
			{
				return;
			}
			foreach (NpcDataPacket nearbyDatum in nearbyData)
			{
				if (nearbyDatum == null)
				{
					continue;
				}
				int agentIndex = nearbyDatum.AgentIndex;
				if (!_npcConversationHistory.ContainsKey(agentIndex))
				{
					_npcConversationHistory[agentIndex] = new List<ConversationMessage>();
				}
				_npcConversationHistory[agentIndex].Add(StampConversationMessageWithCurrentMemoryContext(new ConversationMessage
				{
					EventSequence = eventSequence,
					Role = "system",
					Content = text,
					SpeakerName = "system",
					SpeakerAgentIndex = -1,
					VisibleAgentIndices = visibleAgentIndices
				}));
				if (isAfefFact)
				{
					afefPendingTargets.Add(nearbyDatum);
				}
			}
		}
		if (afefPendingTargets != null)
		{
			foreach (NpcDataPacket target in afefPendingTargets)
			{
				if (target == null)
				{
					continue;
				}
				QueuePendingCurrentAfefFactForAgent(target.AgentIndex, afefFactLine);
				QueuePendingCurrentNativeAfefFactForSceneTarget(target, afefFactLine);
			}
		}
		AppendSceneEventToNativeSharedHistoryForTargets(nearbyData, "系统", text, "fact", eventSequence);
		try
		{
			if (nearbyData != null)
			{
				HashSet<string> persistedNonHeroIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
				foreach (NpcDataPacket nearbyDatum in nearbyData)
				{
					if (nearbyDatum != null && !nearbyDatum.IsHero && TryResolveWildernessNonHeroMemory(nearbyDatum, null, null, nearbyDatum.AgentIndex, out var memoryId, out var memoryName) && persistedNonHeroIds.Add(memoryId))
					{
						MyBehavior.AppendExternalNonHeroSceneDialogueHistory(memoryId, memoryName, null, null, text, _sceneHistorySessionId);
					}
				}
			}
		}
		catch
		{
		}
	}

	private async Task EnsurePersonaForCandidatesAsync(List<NpcDataPacket> candidates, Dictionary<int, Hero> resolvedHeroes)
	{
		if (candidates == null || candidates.Count == 0)
		{
			return;
		}
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (NpcDataPacket npc in candidates)
		{
			if (npc == null)
			{
				continue;
			}
			try
			{
				if (npc.IsHero)
				{
					Hero hero = null;
					if (resolvedHeroes != null) resolvedHeroes.TryGetValue(npc.AgentIndex, out hero);
					if (hero == null)
					{
						continue;
					}
					MyBehavior.GetNpcPersonaForExternal(hero, out var p, out var b);
					if (string.IsNullOrWhiteSpace(p) && string.IsNullOrWhiteSpace(b))
					{
						string text = (hero.StringId ?? "").Trim();
						bool flag = string.IsNullOrWhiteSpace(text) || hashSet.Add(text);
						if (flag)
						{
							bool flag2 = !MyBehavior.TryGetNpcPersonaGenerationStatusForExternal(hero, out var needsGeneration, out var inFlightOrCoolingDown) || (needsGeneration && !inFlightOrCoolingDown);
							if (flag2)
							{
								InformationManager.DisplayMessage(new InformationMessage(MyBehavior.BuildNpcPersonaGenerationHintForExternal(hero), new Color(1f, 0.85f, 0.3f)));
							}
						}
						try
						{
							await MyBehavior.EnsureNpcPersonaGeneratedForExternalAsync(hero);
						}
						catch
						{
						}
						MyBehavior.GetNpcPersonaForExternal(hero, out p, out b);
					}
					if (string.IsNullOrWhiteSpace(p) || string.IsNullOrWhiteSpace(b))
					{
						BuildHeroPersonaFallback(hero, out var fp, out var fb);
						if (string.IsNullOrWhiteSpace(p))
						{
							p = fp;
						}
						if (string.IsNullOrWhiteSpace(b))
						{
							b = fb;
						}
						fp = null;
						fb = null;
					}
					if (!string.IsNullOrWhiteSpace(p))
					{
						npc.PersonalityDesc = p.Trim();
					}
					if (!string.IsNullOrWhiteSpace(b))
					{
						npc.BackgroundDesc = b.Trim();
					}
					p = null;
					b = null;
					continue;
				}
				string key = (npc.UnnamedKey ?? "").Trim().ToLower();
				if (!string.IsNullOrEmpty(key))
				{
					if (ShoutUtils.TryGetUnnamedPersonaByKey(key, out var up, out var ub))
					{
						if (!string.IsNullOrWhiteSpace(up))
						{
							npc.PersonalityDesc = up.Trim();
						}
						if (!string.IsNullOrWhiteSpace(ub))
						{
							npc.BackgroundDesc = ub.Trim();
						}
					}
				}
			}
			catch
			{
			}
		}
	}

	private static void BuildHeroPersonaFallback(Hero hero, out string personality, out string background)
	{
		personality = "";
		background = "";
		if (hero == null)
		{
			return;
		}
		string text = "";
		string text2 = "";
		string value = "";
		try
		{
			text = hero.Culture?.Name?.ToString() ?? "";
		}
		catch
		{
		}
		try
		{
			text2 = hero.Clan?.Name?.ToString() ?? "";
		}
		catch
		{
		}
		try
		{
			value = hero.MapFaction?.Name?.ToString() ?? hero.Clan?.Kingdom?.Name?.ToString() ?? "";
		}
		catch
		{
		}
		string arg = "英雄";
		try
		{
			if (MyBehavior.IsHeroActiveKingdomRulerForExternal(hero))
			{
				arg = "统治者";
			}
			else if (hero.Clan?.Leader == hero)
			{
				arg = "家族族长";
			}
			else if (hero.IsLord)
			{
				arg = "领主";
			}
			else if (hero.IsWanderer)
			{
				arg = "流浪者";
			}
			else if (hero.IsNotable)
			{
				arg = "要人";
			}
		}
		catch
		{
		}
		string arg2 = (string.IsNullOrWhiteSpace(text) ? "" : (text + "的"));
		personality = $"{hero.Name}是一位{arg2}{arg}，处事谨慎务实，重视秩序与利益平衡。";
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append(hero.Name).Append("出身于");
		stringBuilder.Append(string.IsNullOrWhiteSpace(text2) ? "本地家族" : text2);
		if (!string.IsNullOrWhiteSpace(value))
		{
			stringBuilder.Append("，当前活跃于").Append(value).Append("的政治与军事事务中");
		}
		background = stringBuilder.ToString().TrimEnd('。', '.', ' ') + "。";
	}

	private Hero ResolveHeroFromAgentIndex(int agentIndex)
	{
		try
		{
			BasicCharacterObject basicCharacterObject = (Mission.Current?.Agents?.FirstOrDefault((Agent a) => a != null && a.Index == agentIndex))?.Character;
			if (basicCharacterObject == null || !basicCharacterObject.IsHero)
			{
				return null;
			}
			return (basicCharacterObject is CharacterObject characterObject) ? characterObject.HeroObject : null;
		}
		catch
		{
			return null;
		}
	}

	private static Agent ResolveAgentForLocationCharacter(LocationCharacter locationCharacter)
	{
		Mission mission = Mission.Current;
		var agents = mission?.Agents;
		if (locationCharacter == null || agents == null)
		{
			return null;
		}
		IAgentOriginBase agentOrigin = locationCharacter.AgentOrigin;
		if (agentOrigin != null)
		{
			Agent agent = agents.FirstOrDefault((Agent a) => a != null && a.Origin == agentOrigin);
			if (agent != null)
			{
				return agent;
			}
		}
		CharacterObject character = locationCharacter.Character;
		if (character == null)
		{
			return null;
		}
		return agents.FirstOrDefault((Agent a) => a != null && a.Character == character);
	}

	private static Passage FindCurrentScenePassageToLocation(Location targetLocation)
	{
		if (targetLocation == null)
		{
			return null;
		}
		MissionAgentHandler missionBehavior = Mission.Current?.GetMissionBehavior<MissionAgentHandler>();
		IEnumerable<UsableMachine> enumerable = Enumerable.Empty<UsableMachine>();
		if (missionBehavior?.TownPassageProps != null)
		{
			enumerable = enumerable.Concat(missionBehavior.TownPassageProps);
		}
		if (missionBehavior?.DisabledPassages != null)
		{
			enumerable = enumerable.Concat(missionBehavior.DisabledPassages);
		}
		return enumerable.OfType<Passage>().FirstOrDefault((Passage x) => x != null && x.ToLocation == targetLocation);
	}

	private Agent ResolveSceneSummonDoorProxyAgent(ActiveSceneSummonRequest request)
	{
		Mission mission = Mission.Current;
		var agents = mission?.Agents;
		if (request == null || request.DoorProxyAgentIndex < 0 || agents == null)
		{
			return null;
		}
		Agent agent = agents.FirstOrDefault((Agent a) => a != null && a.Index == request.DoorProxyAgentIndex);
		if (agent == null || !agent.IsActive())
		{
			request.DoorProxyAgentIndex = -1;
			return null;
		}
		return agent;
	}

	private Agent EnsureSceneSummonDoorProxyAgent(ActiveSceneSummonRequest request, Passage passage, Agent speakerAgent)
	{
		Agent agent = ResolveSceneSummonDoorProxyAgent(request);
		if (agent != null)
		{
			return agent;
		}
		Mission mission = Mission.Current;
		if (request == null || passage == null || mission?.Scene == null)
		{
			return null;
		}
		CharacterObject characterObject = speakerAgent?.Character as CharacterObject;
		if (characterObject == null)
		{
			characterObject = request.SpeakerLocationCharacter?.Character as CharacterObject;
		}
		if (characterObject == null)
		{
			return null;
		}
		Vec3 passageWaitingPosition = GetPassageWaitingPosition(passage);
		passageWaitingPosition.z = mission.Scene.GetGroundHeightAtPosition(passageWaitingPosition, BodyFlags.CommonCollisionExcludeFlags);
		Vec3 vec3 = passageWaitingPosition;
		vec3.z -= 25f;
		Vec2 vec = Vec2.Forward;
		try
		{
			Vec2 vec2 = ((Agent.Main != null && Agent.Main.IsActive()) ? (Agent.Main.Position - passageWaitingPosition).AsVec2 : Vec2.Zero);
			if (vec2.LengthSquared > 0.001f)
			{
				vec = vec2.Normalized();
			}
			else if (speakerAgent != null)
			{
				vec = speakerAgent.LookDirection.AsVec2;
			}
		}
		catch
		{
		}
		Equipment equipment = null;
		try
		{
			equipment = speakerAgent?.SpawnEquipment?.Clone(false);
		}
		catch
		{
		}
		if (equipment == null)
		{
			try
			{
				equipment = (mission.DoesMissionRequireCivilianEquipment ? characterObject.FirstCivilianEquipment : characterObject.FirstBattleEquipment)?.Clone(false);
			}
			catch
			{
			}
		}
		Team team = null;
		if (IsUsableTeam(speakerAgent?.Team))
		{
			team = speakerAgent.Team;
		}
		else if (IsUsableTeam(mission.PlayerTeam))
		{
			team = mission.PlayerTeam;
		}
		else if (IsUsableTeam(mission.DefenderTeam))
		{
			team = mission.DefenderTeam;
		}
		else if (IsUsableTeam(mission.AttackerTeam))
		{
			team = mission.AttackerTeam;
		}
		if (!IsUsableTeam(team))
		{
			return null;
		}
		try
		{
			AgentBuildData agentBuildData = new AgentBuildData(characterObject).Team(team).InitialPosition(in passageWaitingPosition)
				.InitialDirection(in vec)
				.NoHorses(true)
				.Controller(AgentControllerType.AI);
			if (equipment != null)
			{
				agentBuildData = agentBuildData.Equipment(equipment);
			}
			Agent agent2 = mission.SpawnAgent(agentBuildData, false);
			if (agent2 == null)
			{
				return null;
			}
			request.DoorProxyAgentIndex = agent2.Index;
			try
			{
				agent2.AgentVisuals?.SetVisible(false);
			}
			catch
			{
			}
			try
			{
				agent2.AgentVisuals?.GetEntity()?.SetVisibilityExcludeParents(false);
			}
			catch
			{
			}
			try
			{
				agent2.TeleportToPosition(vec3);
			}
			catch
			{
			}
			try
			{
				agent2.SetMaximumSpeedLimit(0f, isMultiplier: false);
			}
			catch
			{
			}
			try
			{
				agent2.SetIsAIPaused(isPaused: true);
			}
			catch
			{
			}
			try
			{
				agent2.SetMortalityState(Agent.MortalityState.Invulnerable);
			}
			catch
			{
			}
			LogSceneSummonState("cross_scene_proxy_spawned", request, speakerAgent, agent2, "waitPos=" + FormatSceneSummonPosition(passageWaitingPosition) + " hiddenPos=" + FormatSceneSummonPosition(vec3), force: true);
			return agent2;
		}
		catch
		{
			request.DoorProxyAgentIndex = -1;
			return null;
		}
	}

	private void CleanupSceneSummonDoorProxyAgent(ActiveSceneSummonRequest request)
	{
		if (request == null)
		{
			return;
		}
		Agent agent = ResolveSceneSummonDoorProxyAgent(request);
		request.DoorProxyAgentIndex = -1;
		if (agent == null)
		{
			return;
		}
		try
		{
			agent.SetIsAIPaused(isPaused: false);
		}
		catch
		{
		}
		try
		{
			agent.SetMaximumSpeedLimit(-1f, isMultiplier: false);
		}
		catch
		{
		}
		try
		{
			agent.FadeOut(false, true);
		}
		catch
		{
		}
	}

	private Agent ResolveSceneGuideDoorProxyAgent(ActiveSceneGuideRequest request)
	{
		Mission mission = Mission.Current;
		var agents = mission?.Agents;
		if (request == null || request.DoorProxyAgentIndex < 0 || agents == null)
		{
			return null;
		}
		Agent agent = agents.FirstOrDefault((Agent a) => a != null && a.Index == request.DoorProxyAgentIndex);
		if (agent == null || !agent.IsActive())
		{
			request.DoorProxyAgentIndex = -1;
			return null;
		}
		return agent;
	}

	private Agent EnsureSceneGuideDoorProxyAgent(ActiveSceneGuideRequest request, Passage passage, Agent guideAgent)
	{
		Agent agent = ResolveSceneGuideDoorProxyAgent(request);
		if (agent != null)
		{
			return agent;
		}
		Mission mission = Mission.Current;
		if (request == null || passage == null || mission?.Scene == null)
		{
			return null;
		}
		CharacterObject characterObject = guideAgent?.Character as CharacterObject;
		if (characterObject == null)
		{
			characterObject = request.GuideLocationCharacter?.Character as CharacterObject;
		}
		if (characterObject == null)
		{
			return null;
		}
		Vec3 passageWaitingPosition = GetPassageWaitingPosition(passage);
		passageWaitingPosition.z = mission.Scene.GetGroundHeightAtPosition(passageWaitingPosition, BodyFlags.CommonCollisionExcludeFlags);
		Vec3 vec3 = passageWaitingPosition;
		vec3.z -= 25f;
		Vec2 vec = Vec2.Forward;
		try
		{
			Vec2 vec2 = ((Agent.Main != null && Agent.Main.IsActive()) ? (Agent.Main.Position - passageWaitingPosition).AsVec2 : Vec2.Zero);
			if (vec2.LengthSquared > 0.001f)
			{
				vec = vec2.Normalized();
			}
			else if (guideAgent != null)
			{
				vec = guideAgent.LookDirection.AsVec2;
			}
		}
		catch
		{
		}
		Equipment equipment = null;
		try
		{
			equipment = guideAgent?.SpawnEquipment?.Clone(false);
		}
		catch
		{
		}
		if (equipment == null)
		{
			try
			{
				equipment = (mission.DoesMissionRequireCivilianEquipment ? characterObject.FirstCivilianEquipment : characterObject.FirstBattleEquipment)?.Clone(false);
			}
			catch
			{
			}
		}
		Team team = null;
		if (IsUsableTeam(guideAgent?.Team))
		{
			team = guideAgent.Team;
		}
		else if (IsUsableTeam(mission.PlayerTeam))
		{
			team = mission.PlayerTeam;
		}
		else if (IsUsableTeam(mission.DefenderTeam))
		{
			team = mission.DefenderTeam;
		}
		else if (IsUsableTeam(mission.AttackerTeam))
		{
			team = mission.AttackerTeam;
		}
		if (!IsUsableTeam(team))
		{
			return null;
		}
		try
		{
			AgentBuildData agentBuildData = new AgentBuildData(characterObject).Team(team).InitialPosition(in passageWaitingPosition)
				.InitialDirection(in vec)
				.NoHorses(true)
				.Controller(AgentControllerType.AI);
			if (equipment != null)
			{
				agentBuildData = agentBuildData.Equipment(equipment);
			}
			Agent agent2 = mission.SpawnAgent(agentBuildData, false);
			if (agent2 == null)
			{
				return null;
			}
			request.DoorProxyAgentIndex = agent2.Index;
			try
			{
				agent2.AgentVisuals?.SetVisible(false);
			}
			catch
			{
			}
			try
			{
				agent2.AgentVisuals?.GetEntity()?.SetVisibilityExcludeParents(false);
			}
			catch
			{
			}
			try
			{
				agent2.TeleportToPosition(vec3);
			}
			catch
			{
			}
			try
			{
				agent2.SetMaximumSpeedLimit(0f, isMultiplier: false);
			}
			catch
			{
			}
			try
			{
				agent2.SetIsAIPaused(isPaused: true);
			}
			catch
			{
			}
			try
			{
				agent2.SetMortalityState(Agent.MortalityState.Invulnerable);
			}
			catch
			{
			}
			Logger.Log("SceneGuide", "door_proxy_spawned guide=" + (request.GuideName ?? "") + " target=" + (request.TargetName ?? "") + " waitPos=" + FormatSceneSummonPosition(passageWaitingPosition) + " hiddenPos=" + FormatSceneSummonPosition(vec3));
			return agent2;
		}
		catch
		{
			request.DoorProxyAgentIndex = -1;
			return null;
		}
	}

